const createCompatLensSeriesCatalogItems = (
  seed: CompatLensSeriesSeed,
): CompatCatalogItem[] =>
  seed.variants.map((variant) =>
    createCompatLensCatalogItem({
      id: slugifyCompatCatalogId(`${seed.brand}-${variant.model}`),
      brand: seed.brand,
      model: variant.model,
      description: variant.description || seed.description,
      priceNOK: variant.priceNOK,
      releaseYear: variant.releaseYear || seed.releaseYear,
      mount: variant.mount || seed.mount,
      type: seed.type,
      focalLength: variant.focalLength,
      maxAperture: variant.maxAperture,
      weight: variant.weight,
      filterSize: variant.filterSize,
      closeFocus: variant.closeFocus,
      imageStabilization: variant.imageStabilization,
      weatherSealed: variant.weatherSealed,
      norwegianSupplier: seed.norwegianSupplier,
      availability: seed.availability,
      imageUrl: variant.imageUrl || seed.imageUrl,
      productUrl: variant.productUrl || seed.productUrl,
    }),
  );

