const modelTokenMatchesProfile = (
  modelToken: string,
  expectedToken: string,
): boolean => {
  if (!modelToken || !expectedToken) return false;
  return modelToken === expectedToken;
};

const slugifyFirmwareSupportValue = (value: string): string =>
  value
    .trim()
    .toLowerCase()
    .replace(/^canon\s+/u, "")
    .replace(/[α]/gu, "a")
    .replace(/[^a-z0-9]+/gu, "-")
    .replace(/^-+|-+$/gu, "");

const stripLeadingBrandFromModel = (brand: string, model: string): string => {
  const normalizedBrand = brand.trim().toLowerCase();
  const normalizedModel = model.trim();
  if (!normalizedBrand || !normalizedModel) return model.trim();
  const prefixPattern = new RegExp(`^${normalizedBrand}\\s+`, "iu");
  return normalizedModel.replace(prefixPattern, "").trim();
};

const resolvePhotoFirmwareSupportUrl = (
  brandToken: string,
  camera: Pick<FirmwareSeedCandidate, "brand" | "model">,
): string | null => {
  const rawModel = stripLeadingBrandFromModel(camera.brand || "", camera.model || "");
  const modelSlug = slugifyFirmwareSupportValue(rawModel);
  if (!modelSlug) return null;

  switch (brandToken) {
    case "canon":
      return `https://www.usa.canon.com/support/p/${modelSlug}`;
    case "fujifilm":
      return `https://fujifilm-x.com/global/support/download/firmware/cameras/${modelSlug}/`;
    case "sony":
      return `https://www.sony.com/electronics/support/search?search=${encodeURIComponent(rawModel)}`;
    case "nikon":
      return `https://downloadcenter.nikonimglib.com/en/index.html?search=${encodeURIComponent(rawModel)}`;
    case "logitech":
      return `https://support.logi.com/hc/en-us/search?query=${encodeURIComponent(rawModel)}`;
    case "leica":
      return `https://leica-camera.com/en-US/search?search=${encodeURIComponent(rawModel)}`;
    default:
      return PHOTO_BRAND_FIRMWARE_PORTALS[brandToken] || null;
  }
};

