const shouldKeepLegacyCatalogItem = (item: CompatCatalogItem): boolean => {
  if (
    item.category === "lenses" ||
    item.category === "flash" ||
    item.category === "accessories"
  )
    return true;
  if (item.category !== "video") return false;
  const type = String(
    item.specifications.type || item.type || "",
  ).toLowerCase();
  return (
    type.includes("gimbal") || type.includes("monitor") || type.includes("rig")
  );
};

const makeCatalogMergeKey = (
  item: Pick<CompatCatalogItem, "brand" | "model" | "category">,
): string =>
  `${item.category}::${item.brand}::${item.model}`.trim().toLowerCase();

const PRODUCT_IMAGE_SUPPLIER_URLS: Record<string, string> = {
  "foto.no": "https://www.foto.no/",
  "scandinavian photo": "https://www.scandinavianphoto.no/",
  "japan photo": "https://www.japanphoto.no/",
  dustin: "https://www.dustin.no/",
  lightup: "https://www.lightup.no/",
};

const normalizeProductImageCategory = (value: string): CompatCatalogItem["category"] | null => {
  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;
  if (["kameraer", "kamera", "camera", "cameras"].includes(normalized)) return "cameras";
  if (["objektiver", "objektiv", "lens", "lenses"].includes(normalized)) return "lenses";
  if (["lyd", "audio", "mikrofon", "microphone"].includes(normalized)) return "audio";
  if (["video", "gimbal", "monitor", "rig"].includes(normalized)) return "video";
  if (["lys", "blits", "flash", "lighting"].includes(normalized)) return "flash";
  if (["tilbehør", "tilbehor", "accessories", "accessory"].includes(normalized)) return "accessories";
  return null;
};

const tokenizeCatalogLookupValue = (value: string): string[] =>
  normalizeModelLookupValue(value)
    .split(/\s+/u)
    .map((token) => token.trim())
    .filter(Boolean);

const resolveProductImageSupplierUrl = (supplier?: string | null): string | null => {
  const normalized = normalizeModelLookupValue(supplier || "");
  if (!normalized) return null;
  return PRODUCT_IMAGE_SUPPLIER_URLS[normalized] || null;
};

const scoreCatalogImageMatch = (
  item: CompatCatalogItem,
  brand: string,
  model: string,
  category: CompatCatalogItem["category"] | null,
): number => {
  const normalizedBrand = normalizeModelLookupValue(brand);
  const normalizedModel = normalizeModelLookupValue(model);
  const itemBrand = normalizeModelLookupValue(item.brand);
  const itemModel = normalizeModelLookupValue(item.model);
  const modelTokens = tokenizeCatalogLookupValue(model);
  const itemTokens = tokenizeCatalogLookupValue(item.model);

  let score = 0;
  if (itemBrand === normalizedBrand) score += 60;
  if (category && item.category === category) score += 24;
  if (itemModel === normalizedModel) score += 120;
  if (itemModel.includes(normalizedModel) || normalizedModel.includes(itemModel)) {
    score += 48;
  }

  const sharedTokens = modelTokens.filter((token) => itemTokens.includes(token));
  score += sharedTokens.length * 12;

  if (modelTokens[0] && itemTokens[0] && modelTokens[0] === itemTokens[0]) {
    score += 10;
  }

  return score;
};

const findBestCatalogImageMatch = (
  catalog: CompatCatalogItem[],
  brand: string,
  model: string,
  category: CompatCatalogItem["category"] | null,
): { item: CompatCatalogItem; score: number } | null => {
  const candidates = catalog
    .map((item) => ({
      item,
      score: scoreCatalogImageMatch(item, brand, model, category),
    }))
    .filter((entry) => entry.score >= 60)
    .sort((left, right) => right.score - left.score);

  return candidates[0] || null;
};

const loadUnifiedEquipmentCatalog = async (): Promise<CompatCatalogItem[]> => {
  const cameraBundle = await loadCameraSourceBundle(null);
  const cameraItems = cameraBundle.source
    .filter(
      (camera) =>
        !isPlaceholderCameraValue(camera.brand) &&
        !isPlaceholderCameraValue(camera.model),
    )
    .map((camera) => toCatalogItemFromCameraRecord(camera));
  const audioItems = AUDIO_STORAGE_DEVICE_DATABASE.map((device) =>
    toCatalogItemFromAudioStorageDevice(device),
  );
  const memoryCardItems = MEMORY_CARD_PRODUCTS_DB.map((card) =>
    toCatalogItemFromMemoryCard(card),
  );
  const legacyItems = COMPAT_EQUIPMENT_CATALOG.filter(
    shouldKeepLegacyCatalogItem,
  ).map((item) => ({
    ...item,
    norwegianSupplier: "Foto.no",
  }));

  const merged = new Map<string, CompatCatalogItem>();
  for (const item of [
    ...legacyItems,
    ...COMPAT_LENS_CATALOG_SUPPLEMENTS,
    ...COMPAT_CINE_LENS_CATALOG_SUPPLEMENTS,
    ...COMPAT_ACCESSORY_CATALOG_SUPPLEMENTS,
    ...cameraItems,
    ...audioItems,
    ...memoryCardItems,
    ...FIRMWARE_CATALOG_SUPPLEMENTS,
  ]) {
    merged.set(makeCatalogMergeKey(item), item);
  }

  return Array.from(merged.values()).sort(catalogSortByLatest);
};

const catalogPreviewImageCache = new Map<string, string | null>();
const FIRMWARE_AUTO_REFRESH_INTERVAL_MS = 12 * 60 * 60 * 1000;

const matchesEquipmentSearchQuery = (
  item: CompatCatalogItem,
  query: string,
): boolean => {
  const normalizedQuery = normalizeModelLookupValue(query);
  if (!normalizedQuery) return true;

  const queryTokens = tokenizeCatalogLookupValue(normalizedQuery);
  const searchableParts = [
    item.brand,
    item.model,
    item.description,
    item.category,
    item.mount || "",
    item.type || "",
    item.norwegianSupplier || "",
    ...Object.values(item.specifications).map((value) => String(value)),
  ];
  const searchable = normalizeModelLookupValue(searchableParts.join(" "));
  const searchableTokens = tokenizeCatalogLookupValue(searchable);

  if (!queryTokens.length) {
    return searchable.includes(normalizedQuery);
  }

  return queryTokens.every((queryToken) => {
    if (queryToken.length <= 4) {
      return searchableTokens.includes(queryToken);
    }

    return searchableTokens.some(
      (token) =>
        token === queryToken ||
        token.startsWith(queryToken) ||
        token.includes(queryToken),
    );
  });
};

const resolveOfficialCatalogFallback = async (
  item: CompatCatalogItem,
): Promise<Pick<CompatCatalogItem, "imageUrl" | "productUrl"> | null> => {
  const camera = {
    brand: item.brand,
    model: item.model,
  };
  const brandToken = toFirmwareBrandToken(item.brand);
  const itemProductUrl = readString(item.productUrl) || null;
  let imageUrl = readString(item.imageUrl) || null;
  let productUrl = itemProductUrl;

  if (itemProductUrl && brandToken) {
    const productMetadata = await fetchOfficialFirmwarePageMetadata(
      itemProductUrl,
      brandToken,
      camera,
    );
    if (productMetadata) {
      const metadataPageUrl = readString(productMetadata.sourceUrl);
      const metadataDownloadUrl = readString(productMetadata.downloadUrl);
      imageUrl = imageUrl || readString(productMetadata.imageUrl) || null;
      productUrl =
        (metadataPageUrl && !isLikelyImageAssetUrl(metadataPageUrl)
          ? metadataPageUrl
          : null) ||
        (metadataDownloadUrl && !isLikelyImageAssetUrl(metadataDownloadUrl)
          ? metadataDownloadUrl
          : null) ||
        productUrl;
    }
  }

  const canonicalBase = resolveCanonicalFirmwareProfileByDevice(
    item.brand,
    item.model,
    item.category,
  );
  if (canonicalBase) {
    const canonical = await resolveLiveCanonicalFirmwareProfile(camera, canonicalBase);
    imageUrl =
      imageUrl ||
      readString(canonical.officialImageUrl) ||
      null;
    productUrl =
      productUrl ||
      (readString(canonical.downloadUrl) &&
      !isLikelyImageAssetUrl(readString(canonical.downloadUrl))
        ? readString(canonical.downloadUrl)
        : null) ||
      (readString(canonical.sourceUrl) &&
      !isLikelyImageAssetUrl(readString(canonical.sourceUrl))
        ? readString(canonical.sourceUrl)
        : null) ||
      null;
  }

  if (!imageUrl && !productUrl) return null;
  return {
    imageUrl: imageUrl || "",
    productUrl: productUrl || undefined,
  };
};

const enrichCatalogItemWithPreviewImage = async (
  item: CompatCatalogItem,
): Promise<CompatCatalogItem> => {
  if (isUsableEquipmentImageUrl(item.imageUrl)) {
    return item;
  }

  const cacheKey = makeCatalogMergeKey(item);
  if (catalogPreviewImageCache.has(cacheKey)) {
    const cached = catalogPreviewImageCache.get(cacheKey);
    return cached ? { ...item, imageUrl: cached } : item;
  }

  const resolved = await resolveAuthenticSupplierEquipmentImage(
    item.brand,
    item.model,
    item.category,
  );
  const imageUrl = resolved?.imageUrl || null;
  catalogPreviewImageCache.set(cacheKey, imageUrl);
  if (imageUrl) {
    return { ...item, imageUrl };
  }

  const officialFallback = await resolveOfficialCatalogFallback(item);
  if (!officialFallback) {
    return item;
  }

  if (isUsableEquipmentImageUrl(officialFallback.imageUrl)) {
    catalogPreviewImageCache.set(cacheKey, officialFallback.imageUrl);
  }

  return {
    ...item,
    imageUrl: officialFallback.imageUrl || item.imageUrl,
    productUrl: officialFallback.productUrl || item.productUrl,
  };
};

