const FOTO_NO_BASE_URL = "https://www.foto.no";
const FOTO_NO_INSTANT_SEARCH_ENDPOINT =
  `${FOTO_NO_BASE_URL}/webpages/ajaxcall.aspx`;

const FOTO_NO_BRAND_ALIASES: Record<string, string[]> = {
  rode: ["Røde", "Rode"],
};

const EQUIPMENT_IMAGE_GENERIC_TITLE_TOKENS = new Set([
  "kamera",
  "kamerahus",
  "camera",
  "body",
  "objektiv",
  "lens",
  "linse",
  "for",
  "med",
  "inkl",
  "inkludert",
]);

const EQUIPMENT_IMAGE_VARIANT_TOKENS = new Set([
  "c",
  "ii",
  "iii",
  "iv",
  "v",
  "vi",
  "vii",
  "viii",
  "ix",
  "x",
  "mark",
  "mk",
  "mini",
  "max",
  "plus",
  "ultra",
  "kit",
]);

const EQUIPMENT_IMAGE_ACCESSORY_TOKENS = new Set([
  "cage",
  "rig",
  "fan",
  "cooling",
  "case",
  "cover",
  "grip",
  "battery",
  "charger",
  "adapter",
  "mount",
  "plate",
  "clamp",
  "bracket",
  "handle",
  "protector",
  "hood",
  "strap",
  "bag",
  "tripod",
  "filter",
]);

const isUsableEquipmentImageUrl = (value?: string | null): value is string => {
  const trimmed = value?.trim();
  if (!trimmed) return false;
  return (
    !trimmed.includes("placehold.co") &&
    !trimmed.includes("ImageNotFound.gif")
  );
};

const normalizeEquipmentImageLookupValue = (value: string): string =>
  normalizeModelLookupValue(
    value
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/gu, "")
      .replace(/ø/giu, "o")
      .replace(/æ/giu, "ae")
      .replace(/å/giu, "a"),
  )
    .replace(/[^a-z0-9]+/gu, " ")
    .replace(/\s+/gu, " ")
    .trim();

const tokenizeEquipmentImageLookupValue = (value: string): string[] =>
  normalizeEquipmentImageLookupValue(value)
    .split(/\s+/u)
    .map((token) => token.trim())
    .filter(Boolean);

const makeAbsoluteEquipmentSupplierUrl = (
  rawUrl?: string | null,
  baseUrl = FOTO_NO_BASE_URL,
): string | null => {
  const trimmed = rawUrl?.trim();
  if (!trimmed) return null;
  if (/^https?:\/\//iu.test(trimmed)) {
    return trimmed.replace(":443/", "/");
  }
  if (trimmed.startsWith("//")) {
    return `https:${trimmed}`.replace(":443/", "/");
  }
  try {
    return new URL(trimmed, baseUrl).toString().replace(":443/", "/");
  } catch {
    return null;
  }
};

const extractEquipmentImageSourceUrl = (
  description?: string | null,
): string | null => {
  const match = description?.match(/https?:\/\/\S+/iu);
  return makeAbsoluteEquipmentSupplierUrl(match?.[0] || null);
};

const decodeEquipmentHtmlText = (value?: string | null): string => {
  if (!value) return "";
  return loadHtml(`<span>${value}</span>`).text().trim();
};

const findEquipmentImageTokenSequenceIndex = (
  haystack: string[],
  needle: string[],
): number => {
  if (needle.length === 0 || haystack.length < needle.length) return -1;
  for (let index = 0; index <= haystack.length - needle.length; index += 1) {
    const isMatch = needle.every(
      (token, offset) => haystack[index + offset] === token,
    );
    if (isMatch) {
      return index;
    }
  }
  return -1;
};

const scoreFotoNoSearchCandidate = (
  candidate: FotoNoInstantSearchProduct,
  brand: string,
  model: string,
  category?: CompatCatalogItem["category"] | null,
): number => {
  const title = [candidate.ProduktDesc1, candidate.ProduktDesc2]
    .map((value) => decodeEquipmentHtmlText(value))
    .filter(Boolean)
    .join(" ");
  const titleTokens = tokenizeEquipmentImageLookupValue(title);
  const brandTokens = tokenizeEquipmentImageLookupValue(brand);
  const modelTokens = tokenizeEquipmentImageLookupValue(model);

  if (!titleTokens.length || !brandTokens.length || !modelTokens.length) {
    return -1;
  }

  const brandIndex = findEquipmentImageTokenSequenceIndex(
    titleTokens,
    brandTokens,
  );
  if (brandIndex === -1) {
    return -1;
  }

  const fullIndex = findEquipmentImageTokenSequenceIndex(titleTokens, [
    ...brandTokens,
    ...modelTokens,
  ]);

  let score = 45;
  if (fullIndex >= 0) {
    score += 170;
    if (fullIndex === 0) {
      score += 15;
    }
    const trailingTokens = titleTokens.slice(
      fullIndex + brandTokens.length + modelTokens.length,
    );
    const variantPenalty = trailingTokens.filter(
      (token) =>
        !EQUIPMENT_IMAGE_GENERIC_TITLE_TOKENS.has(token) &&
        (EQUIPMENT_IMAGE_VARIANT_TOKENS.has(token) ||
          /^[a-z]$/iu.test(token) ||
          /^\d{2,4}(?:mm|gb|tb)?$/iu.test(token)),
    ).length;
    score -= variantPenalty * 55;
  } else {
    const sharedTokens = modelTokens.filter((token) =>
      titleTokens.includes(token),
    );
    if (sharedTokens.length < Math.max(1, Math.ceil(modelTokens.length * 0.75))) {
      return -1;
    }
    score += sharedTokens.length * 28;
  }

  const resolvedCategory = category || null;
  if (resolvedCategory === "cameras" || resolvedCategory === "video") {
    const leadingTokens =
      fullIndex >= 0
        ? titleTokens.slice(0, fullIndex)
        : titleTokens.slice(0, brandIndex);
    const nonGenericLeadingTokens = leadingTokens.filter(
      (token) => !EQUIPMENT_IMAGE_GENERIC_TITLE_TOKENS.has(token),
    ).length;
    score -= nonGenericLeadingTokens * 45;

    const accessoryPenalty = titleTokens.filter((token) =>
      EQUIPMENT_IMAGE_ACCESSORY_TOKENS.has(token),
    ).length;
    score -= accessoryPenalty * 140;

    if (titleTokens.includes("for")) {
      score -= 80;
    }
  }

  if (titleTokens.includes("kit") && !modelTokens.includes("kit")) {
    score -= 40;
  }

  return score;
};

const fetchFotoNoInstantSearchProducts = async (
  brand: string,
  model: string,
): Promise<FotoNoInstantSearchProduct[]> => {
  const normalizedBrand = normalizeEquipmentImageLookupValue(brand);
  const brandQueries = uniqueStrings([
    ...(FOTO_NO_BRAND_ALIASES[normalizedBrand] || []),
    brand,
  ]);

  for (const brandQuery of brandQueries) {
    const payload = { search: `${brandQuery} ${model}`.trim() };
    const url = new URL(FOTO_NO_INSTANT_SEARCH_ENDPOINT);
    url.searchParams.set("ajax", "true");
    url.searchParams.set("action", "GetInstantSearchResult");
    url.searchParams.set("control", "InstantSearchKnockout");
    url.searchParams.set("data", JSON.stringify(payload));

    const response = await fetch(url.toString(), {
      headers: {
        Accept: "application/json",
        "User-Agent": "Mozilla/5.0 CreatorHub Equipment Resolver",
      },
    });
    if (!response.ok) {
      throw new Error(`Foto.no search failed with ${response.status}`);
    }

    const parsed = (await response.json()) as FotoNoInstantSearchResponse;
    if (Array.isArray(parsed.Products) && parsed.Products.length > 0) {
      return parsed.Products;
    }
  }

  return [];
};

const fetchFotoNoProductImage = async (
  productUrl: string,
): Promise<{
  imageUrl: string | null;
  productUrl: string;
  title: string;
  thumbnailUrl: string | null;
}> => {
  const response = await fetch(productUrl, {
    headers: {
      Accept: "text/html",
      "User-Agent": "Mozilla/5.0 CreatorHub Equipment Resolver",
    },
  });
  if (!response.ok) {
    throw new Error(`Foto.no product page failed with ${response.status}`);
  }

  const html = await response.text();
  const $ = loadHtml(html);
  const title = $("title")
    .first()
    .text()
    .replace(/\s*-\s*Foto\.no\s*$/iu, "")
    .trim();
  const canonicalUrl =
    makeAbsoluteEquipmentSupplierUrl($('link[rel="canonical"]').attr("href")) ||
    productUrl;
  const imageUrl =
    makeAbsoluteEquipmentSupplierUrl(
      $(".lipscore-rating-small").first().attr("ls-image-url"),
    ) ||
    makeAbsoluteEquipmentSupplierUrl(
      $(".d4-instant-search-preview-image img").first().attr("src"),
    ) ||
    makeAbsoluteEquipmentSupplierUrl(
      $(".product-image-container img").first().attr("src"),
    ) ||
    makeAbsoluteEquipmentSupplierUrl($("img[data-plid]").first().attr("src"));

  const thumbnailUrl =
    makeAbsoluteEquipmentSupplierUrl(
      $(".d4-instant-search-preview-image img").first().attr("src"),
    ) || imageUrl;

  return {
    imageUrl,
    productUrl: canonicalUrl,
    title,
    thumbnailUrl,
  };
};

const resolveAuthenticSupplierEquipmentImage = async (
  brand: string,
  model: string,
  category?: CompatCatalogItem["category"] | null,
): Promise<ResolvedSupplierEquipmentImage | null> => {
  const minimumScore = category === "lenses" ? 95 : 120;
  const candidates = (await fetchFotoNoInstantSearchProducts(brand, model))
    .map((candidate) => ({
      candidate,
      score: scoreFotoNoSearchCandidate(candidate, brand, model, category),
    }))
    .filter((entry) => entry.score >= minimumScore)
    .sort((left, right) => right.score - left.score)
    .slice(0, 4);

  for (const entry of candidates) {
    const productUrl = makeAbsoluteEquipmentSupplierUrl(
      entry.candidate.ProduktLink,
    );
    if (!productUrl) {
      continue;
    }

    try {
      const productPage = await fetchFotoNoProductImage(productUrl);
      const pageScore = scoreFotoNoSearchCandidate(
        {
          ProduktDesc1: productPage.title,
          ProduktDesc2: "",
        },
        brand,
        model,
        category,
      );
      if (pageScore < minimumScore) {
        if (
          category === "lenses" &&
          isUsableEquipmentImageUrl(
            makeAbsoluteEquipmentSupplierUrl(entry.candidate.ImageSource),
          )
        ) {
          return {
            imageUrl: makeAbsoluteEquipmentSupplierUrl(
              entry.candidate.ImageSource,
            ) as string,
            productUrl: productPage.productUrl,
            supplier: "Foto.no",
            source: "official_norwegian",
            title:
              productPage.title ||
              [entry.candidate.ProduktDesc1, entry.candidate.ProduktDesc2]
                .map((value) => decodeEquipmentHtmlText(value))
                .filter(Boolean)
                .join(" ")
                .trim(),
            thumbnailUrl: makeAbsoluteEquipmentSupplierUrl(
              entry.candidate.ImageSource,
            ),
            confidence: Number(Math.max(0.7, entry.score / 180).toFixed(2)),
          };
        }
        continue;
      }

      const imageUrl =
        productPage.imageUrl ||
        makeAbsoluteEquipmentSupplierUrl(entry.candidate.ImageSource);
      if (!isUsableEquipmentImageUrl(imageUrl)) {
        continue;
      }

      const confidence = Math.min(
        0.99,
        Math.max(0.72, (entry.score + pageScore) / 260),
      );

      return {
        imageUrl,
        productUrl: productPage.productUrl,
        supplier: "Foto.no",
        source: "official_norwegian",
        title:
          productPage.title ||
          [entry.candidate.ProduktDesc1, entry.candidate.ProduktDesc2]
            .map((value) => decodeEquipmentHtmlText(value))
            .filter(Boolean)
            .join(" ")
            .trim(),
        thumbnailUrl:
          productPage.thumbnailUrl ||
          makeAbsoluteEquipmentSupplierUrl(entry.candidate.ImageSource),
        confidence: Number(confidence.toFixed(2)),
      };
    } catch (error) {
      console.warn("Foto.no equipment image resolution failed:", {
        brand,
        model,
        productUrl,
        error: error instanceof Error ? error.message : error,
      });
    }
  }

  return null;
};

const loadEquipmentImageAttachments = async (
  equipmentIds: number[],
): Promise<EquipmentImageAttachmentRow[]> => {
  if (equipmentIds.length === 0) {
    return [];
  }

  const { rows } = await pool.query<EquipmentImageAttachmentRow>(
    `
      SELECT id, equipment_id, user_id, image_url, image_type, description,
             is_primary, sort_order, created_at, updated_at
      FROM equipment_images
      WHERE equipment_id = ANY($1::int[])
      ORDER BY is_primary DESC NULLS LAST,
               sort_order ASC NULLS LAST,
               id ASC
    `,
    [equipmentIds],
  );

  return rows;
};

const buildEquipmentImageAttachmentMap = (
  rows: EquipmentImageAttachmentRow[],
): Map<number, EquipmentImageAttachmentRow> => {
  const attachments = new Map<number, EquipmentImageAttachmentRow>();
  for (const row of rows) {
    if (!row.equipment_id || attachments.has(row.equipment_id)) {
      continue;
    }
    attachments.set(row.equipment_id, row);
  }
  return attachments;
};

const buildEquipmentImageEnvelope = (
  equipment: EquipmentImageTarget,
  attachment?: EquipmentImageAttachmentRow | null,
): EquipmentImageEnvelope | null => {
  const settings = parseSettings(equipment.settings);
  const imageUrl =
    readString(equipment.imageUrl) ||
    readString(settings.imageUrl) ||
    readString(attachment?.image_url) ||
    null;

  if (!isUsableEquipmentImageUrl(imageUrl)) {
    return null;
  }

  const officialUrl =
    readString(settings.supplierUrl) ||
    extractEquipmentImageSourceUrl(attachment?.description) ||
    null;

  return {
    imageUrl,
    officialUrl,
    source:
      readString(settings.imageSource) ||
      (attachment?.image_type?.includes("official")
        ? "official_norwegian"
        : attachment?.image_type || "inventory"),
    description:
      readString(settings.imageTitle) ||
      readString(attachment?.description) ||
      `${equipment.brand} ${equipment.model}`.trim(),
    createdAt: attachment?.created_at || equipment.createdAt,
    updatedAt: attachment?.updated_at || equipment.updatedAt,
  };
};

const persistResolvedEquipmentImage = async (
  equipment: EquipmentImageTarget,
  resolved: ResolvedSupplierEquipmentImage,
): Promise<EquipmentImageAttachmentRow | null> => {
  const settings = parseSettings(equipment.settings);
  const updatedSettings = {
    ...settings,
    imageUrl: resolved.imageUrl,
    supplierUrl: resolved.productUrl,
    imageSource: resolved.source,
    imageTitle: resolved.title,
    imageConfidence: resolved.confidence,
  };

  await db
    .update(schema.userEquipment)
    .set({
      imageUrl: resolved.imageUrl,
      settings: updatedSettings,
      updatedAt: new Date().toISOString(),
    })
    .where(eq(schema.userEquipment.id, equipment.id));

  const existing = await pool.query<{ id: number }>(
    `
      SELECT id
      FROM equipment_images
      WHERE equipment_id = $1
      ORDER BY is_primary DESC NULLS LAST,
               sort_order ASC NULLS LAST,
               id ASC
      LIMIT 1
    `,
    [equipment.id],
  );

  const description = `${resolved.title} | ${resolved.productUrl}`;

  if (existing.rows[0]?.id) {
    const updated = await pool.query<EquipmentImageAttachmentRow>(
      `
        UPDATE equipment_images
        SET user_id = $2,
            image_url = $3,
            image_type = $4,
            description = $5,
            is_primary = true,
            sort_order = 0,
            updated_at = NOW()
        WHERE id = $1
        RETURNING id, equipment_id, user_id, image_url, image_type, description,
                  is_primary, sort_order, created_at, updated_at
      `,
      [
        existing.rows[0].id,
        equipment.userId,
        resolved.imageUrl,
        "official_foto_no",
        description,
      ],
    );
    return updated.rows[0] || null;
  }

  const inserted = await pool.query<EquipmentImageAttachmentRow>(
    `
      INSERT INTO equipment_images
        (equipment_id, user_id, image_url, image_type, description,
         is_primary, sort_order, created_at, updated_at)
      VALUES ($1, $2, $3, $4, $5, true, 0, NOW(), NOW())
      RETURNING id, equipment_id, user_id, image_url, image_type, description,
                is_primary, sort_order, created_at, updated_at
    `,
    [
      equipment.id,
      equipment.userId,
      resolved.imageUrl,
      "official_foto_no",
      description,
    ],
  );

  return inserted.rows[0] || null;
};

const ensureEquipmentImageEnvelope = async (
  equipment: EquipmentImageTarget,
  attachment?: EquipmentImageAttachmentRow | null,
): Promise<EquipmentImageEnvelope | null> => {
  const existingEnvelope = buildEquipmentImageEnvelope(equipment, attachment);
  if (existingEnvelope?.officialUrl) {
    return existingEnvelope;
  }

  const resolved = await resolveAuthenticSupplierEquipmentImage(
    equipment.brand,
    equipment.model,
    normalizeProductImageCategory(equipment.category || ""),
  );
  if (!resolved) {
    return existingEnvelope;
  }

  const storedAttachment = await persistResolvedEquipmentImage(equipment, resolved);
  return {
    imageUrl: resolved.imageUrl,
    officialUrl: resolved.productUrl,
    source: resolved.source,
    description: resolved.title,
    createdAt: storedAttachment?.created_at || equipment.createdAt,
    updatedAt: storedAttachment?.updated_at || equipment.updatedAt,
  };
};

type InventoryRecommendedMemoryCardSummary = {
  id: string;
  name: string;
  fullName: string;
  category: (typeof MEMORY_CARD_TYPES_DB)[number]["category"];
  commonCapacities: string[];
  videoClass?: string;
  uhsClass?: string;
  description: string;
  color: string;
};

const getSupportedMemoryCardIdsFromCatalogItem = (
  item: CompatCatalogItem | null,
): string[] => {
  if (!item) return [];

  const directIds =
    toFlexibleStringArray(item.specifications.supportedMemoryCardTypes) ??
    toFlexibleStringArray(item.specifications.cardTypeIds);

  if (directIds?.length) {
    return Array.from(
      new Set(
        directIds.filter((cardTypeId) => Boolean(getMemoryCardTypeByIdFromDatabase(cardTypeId))),
      ),
    );
  }

  const labelCandidates =
    toFlexibleStringArray(item.specifications.supportedMemoryCardLabels) ??
    toFlexibleStringArray(item.specifications.cardTypes);

  if (labelCandidates?.length) {
    const mappedIds = labelCandidates
      .map((label) => {
        const normalizedLabel = normalizeModelLookupValue(label);
        return (
          MEMORY_CARD_TYPES_DB.find(
            (card) =>
              normalizeModelLookupValue(card.id) === normalizedLabel ||
              normalizeModelLookupValue(card.name) === normalizedLabel ||
              normalizeModelLookupValue(card.fullName) === normalizedLabel,
          )?.id || null
        );
      })
      .filter((cardTypeId): cardTypeId is string => Boolean(cardTypeId));

    if (mappedIds.length) {
      return Array.from(new Set(mappedIds));
    }
  }

  if (item.category === "cameras" || item.category === "video") {
    return findStrictMemoryCardIdsForCamera(item.id);
  }

  return [];
};

const buildInventoryRecommendedMemoryCards = (
  item: CompatCatalogItem | null,
): InventoryRecommendedMemoryCardSummary[] => {
  const supportedCardIds = getSupportedMemoryCardIdsFromCatalogItem(item);

  return supportedCardIds.reduce<InventoryRecommendedMemoryCardSummary[]>(
    (summaries, cardTypeId) => {
      const card = getMemoryCardTypeByIdFromDatabase(cardTypeId);
      if (!card) return summaries;

      summaries.push({
        id: card.id,
        name: card.name,
        fullName: card.fullName,
        category: card.category,
        commonCapacities: card.commonCapacities,
        videoClass: card.videoClass,
        uhsClass: card.uhsClass,
        description: card.description,
        color: card.color,
      });
      return summaries;
    },
    [],
  );
};

const matchInventoryEquipmentCatalogItem = (
  catalog: CompatCatalogItem[],
  equipment: Pick<EquipmentImageTarget, "brand" | "model" | "category">,
): CompatCatalogItem | null => {
  const normalizedCategory = normalizeProductImageCategory(equipment.category || "");
  return findBestCatalogImageMatch(
    catalog,
    equipment.brand,
    equipment.model,
    normalizedCategory,
  )?.item || null;
};

app.get("/api/equipment/search", async (req, res) => {
  const q =
    typeof req.query.q === "string" ? req.query.q.trim().toLowerCase() : "";
  const brand =
    typeof req.query.brand === "string"
      ? req.query.brand.trim().toLowerCase()
      : "";
  const category = normalizeCatalogCategory(
    typeof req.query.category === "string" ? req.query.category : "",
  );
  const year =
    typeof req.query.year === "string" ? Number(req.query.year) : NaN;
  const limit = parseLimitParam(req.query.limit, 80);
  try {
    const catalog = await loadUnifiedEquipmentCatalog();
    const filtered = catalog
      .filter((item) => {
        if (brand && brand !== "alle" && item.brand.toLowerCase() !== brand)
          return false;
        if (category && item.category !== category) return false;
        if (Number.isFinite(year) && item.releaseYear !== year) return false;
        if (!q) return true;
        return matchesEquipmentSearchQuery(item, q);
      })
      .slice(0, limit);

    const previewEnriched = await Promise.all(
      filtered.map((item, index) =>
        index <
        (category === "lenses"
          ? Math.min(filtered.length, 80)
          : q || brand
            ? Math.min(filtered.length, 24)
            : 16)
          ? enrichCatalogItemWithPreviewImage(item)
          : Promise.resolve(item),
      ),
    );

    res.json({
      success: true,
      source: "unified-catalog",
      total: previewEnriched.length,
      totalAvailable: catalog.length,
      data: previewEnriched,
      results: previewEnriched,
    });
  } catch (error) {
    console.error("Failed to load unified equipment catalog:", error);
    res.status(500).json({ error: "Failed to load equipment catalog" });
  }
});

