async function resolveCompatSubscriptionStatus(
  userId: string,
  email: string | null,
): Promise<CompatSubscriptionStatus> {
  const storedStatus = await readCompatSubscriptionStatus(userId);
  if (storedStatus) {
    return {
      ...storedStatus,
      email: storedStatus.email ?? email ?? null,
    };
  }

  if (userId !== "guest" && (await hasTable("user_subscriptions"))) {
    const result = await pool.query(
      `SELECT plan_id, status, started_at, auto_renew
       FROM user_subscriptions
       WHERE user_id = $1
       ORDER BY started_at DESC NULLS LAST
       LIMIT 1`,
      [userId],
    );
    const row = result.rows[0];
    if (row) {
      const plan = getCompatPlatformSubscriptionPlan(row.plan_id);
      const normalizedStatus = readString(row.status) || "inactive";
      return buildCompatSubscriptionStatus(userId, plan, {
        selectedPlan: plan?.id ?? null,
        planName: plan?.displayName ?? null,
        subscriptionSelected:
          normalizedStatus === "active" || normalizedStatus === "trial",
        paymentCompleted:
          normalizedStatus === "active" || normalizedStatus === "trial",
        memberSince: row.started_at
          ? new Date(row.started_at).toISOString()
          : null,
        nextBillingDate: row.started_at
          ? addDaysIso(new Date(row.started_at).toISOString(), 30)
          : null,
        accessUntil: row.started_at
          ? addDaysIso(new Date(row.started_at).toISOString(), 30)
          : null,
        autoRenew: row.auto_renew !== false,
        email,
        source: "database",
      });
    }
  }

  return buildCompatSubscriptionStatus(userId, null, {
    selectedPlan: null,
    planName: null,
    subscriptionSelected: false,
    paymentCompleted: false,
    memberSince: null,
    nextBillingDate: null,
    accessUntil: null,
    email,
    source: "default",
  });
}

async function buildCompatPaymentHistory(
  userId: string,
  email: string | null,
): Promise<CompatPaymentHistoryItem[]> {
  const storedHistory = await readCompatPaymentHistory(userId);
  const currentSubscription = await resolveCompatSubscriptionStatus(
    userId,
    email,
  );

  if (
    currentSubscription.subscriptionSelected &&
    currentSubscription.selectedPlan
  ) {
    const alreadyTracked = storedHistory.some(
      (item) => item.planId === currentSubscription.selectedPlan,
    );
    if (!alreadyTracked) {
      storedHistory.unshift({
        id: `subscription-${currentSubscription.selectedPlan}-${userId}`,
        type: "subscription",
        planId: currentSubscription.selectedPlan,
        planName: currentSubscription.planName,
        amount: currentSubscription.amount,
        currency: currentSubscription.currency || "NOK",
        status: "active",
        createdAt: currentSubscription.memberSince || new Date().toISOString(),
        currentPeriodStart: currentSubscription.memberSince,
        currentPeriodEnd: currentSubscription.nextBillingDate,
        transactionId: currentSubscription.transactionId,
        isInFiken: false,
        refunded: false,
        refundReason: null,
        refundedAt: null,
        refundRequestId: null,
        refundRequestStatus: null,
        refundRequestedAt: null,
        receiptSentAt: null,
        receiptUrl: null,
        invoiceUrl: null,
      });
    }
  }

  return storedHistory.sort(
    (left, right) =>
      new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime(),
  );
}

function normalizeCompatPaymentMethod(
  value: unknown,
): CompatPaymentStatusRecord["paymentMethod"] {
  const raw = (readString(value) || "card").toLowerCase();
  if (raw === "google-pay" || raw === "googlepay" || raw === "google_pay") {
    return "google-pay";
  }
  if (raw === "vipps") {
    return "vipps";
  }
  if (raw === "stripe") {
    return "stripe";
  }
  return "card";
}

function normalizeCompatAmountMinor(
  value: unknown,
  plan: CompatPlatformSubscriptionPlan | null,
): number {
  const fallback = plan ? Math.round(plan.price * 100) : 0;
  const parsed = readNumber(value);
  if (typeof parsed !== "number" || !Number.isFinite(parsed)) {
    return fallback;
  }
  if (parsed <= 0) {
    return 0;
  }
  if (plan && Math.abs(parsed - plan.price) < 0.0001) {
    return fallback;
  }
  if (parsed < 1000 && fallback >= 1000) {
    return Math.round(parsed * 100);
  }
  return Math.round(parsed);
}

function resolveCompatPaymentUserScope(
  userId: string | null,
  requestId: string | null,
  email: string | null,
): string {
  if (userId && userId !== "guest") {
    return userId;
  }
  if (requestId) {
    return `invite:${requestId}`;
  }
  if (email) {
    return `email:${email.trim().toLowerCase()}`;
  }
  return "guest";
}

function isPersistableCompatUserId(userId: string): boolean {
  return (
    Boolean(userId) &&
    userId !== "guest" &&
    !userId.startsWith("invite:") &&
    !userId.startsWith("email:")
  );
}

function deriveCompatMembershipTier(
  planId: string | null,
): CompatMembershipCardTier {
  switch (normalizeBillingPlanId(planId)) {
    case "enterprise":
      return "PLATINUM";
    case "premium":
      return "GOLD";
    case "professional":
      return "SILVER";
    default:
      return "BRONZE";
  }
}

function deriveCompatMembershipType(planName: string, planId: string | null) {
  const normalizedPlanId = normalizeBillingPlanId(planId);
  if (normalizedPlanId === "prototype") {
    return "Prototype";
  }
  if (normalizedPlanId === "enterprise") {
    return "Enterprise";
  }
  if (normalizedPlanId === "premium") {
    return "Premium";
  }
  if (normalizedPlanId === "professional") {
    return "Professional";
  }
  if (normalizedPlanId === "basic") {
    return "Basic";
  }
  return planName.trim() || "Creator";
}

