const slugifyEvendi = (value: string) =>
  value
    .toLowerCase()
    .replace(/å/g, "a")
    .replace(/æ/g, "ae")
    .replace(/ø/g, "o")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

const resolveEvendiKey = (category: EvendiVendorCategory): string => {
  return (
    category.dashboardKey?.trim() ||
    category.slug?.trim() ||
    slugifyEvendi(category.name)
  );
};

async function fetchEvendiVendorCategories(
  eventType?: string,
): Promise<EvendiVendorCategory[]> {
  if (!EVENDI_API_URL) {
    return [];
  }

  const url = new URL("/api/vendor-categories", EVENDI_API_URL);
  if (eventType) {
    url.searchParams.set("eventType", eventType);
  }

  const response = await fetch(url.toString());
  if (!response.ok) {
    throw new Error(`Evendi vendor categories failed (${response.status})`);
  }
  const data = await response.json();
  return Array.isArray(data) ? data : [];
}

function buildVendorTypePayload(
  category: EvendiVendorCategory,
): VendorTypePayload {
  const key = resolveEvendiKey(category);
  const color = EVENDI_VENDOR_COLORS[key] || "#667eea";
  const overrides = evendiVendorOverrides.get(key);

  return {
    id: key,
    name: category.name,
    nameEnglish: category.name,
    color,
    category: EVENDI_VENDOR_CATEGORIES[key] || "service",
    primaryActions: DEFAULT_VENDOR_ACTIONS,
    quickStats: DEFAULT_VENDOR_STATS,
    supportedFeatures: EVENDI_VENDOR_FEATURES[key] || DEFAULT_VENDOR_FEATURES,
    marketplaceCategory: [key],
    targetCustomers: ["evendi"],
    productCategories: overrides?.productCategories,
    evendiCategory: category,
  };
}

const EVENDI_EVENT_TYPES = new Set([
  "wedding",
  "confirmation",
  "birthday",
  "anniversary",
  "engagement",
  "baby_shower",
  "conference",
  "seminar",
  "kickoff",
  "summer_party",
  "christmas_party",
  "team_building",
  "product_launch",
  "trade_fair",
  "corporate_anniversary",
  "awards_night",
  "employee_day",
  "onboarding_day",
  "corporate_event",
]);

function normalizeEventType(value: unknown): string | null {
  if (typeof value !== "string") return null;
  const normalized = value.trim().toLowerCase();
  if (!normalized) return null;
  return EVENDI_EVENT_TYPES.has(normalized) ? normalized : null;
}

function isValidNorwegianOrgNumber(value: string): boolean {
  if (!/^[0-9]{9}$/.test(value)) return false;
  const digits = value.split("").map((digit) => Number(digit));
  const weights = [3, 2, 7, 6, 5, 4, 3, 2];
  const sum = weights.reduce(
    (total, weight, index) => total + weight * digits[index],
    0,
  );
  const remainder = 11 - (sum % 11);
  if (remainder === 11) return digits[8] === 0;
  if (remainder === 10) return false;
  return digits[8] === remainder;
}

function resolveMimeType(fileName?: string | null): string {
  const fallback = "image/png";
  if (!fileName) return fallback;
  const ext = fileName.split(".").pop()?.toLowerCase();
  switch (ext) {
    case "jpg":
    case "jpeg":
      return "image/jpeg";
    case "svg":
      return "image/svg+xml";
    case "webp":
      return "image/webp";
    case "gif":
      return "image/gif";
    case "png":
      return "image/png";
    default:
      return fallback;
  }
}

function normalizeBase64Upload(payload: string, fileName?: string | null) {
  const trimmed = payload.trim();
  if (trimmed.startsWith("data:")) {
    const match = trimmed.match(/^data:(.+);base64,(.+)$/);
    if (!match) {
      throw new Error("Invalid data URL");
    }
    const [, mimeType, base64Data] = match;
    const buffer = Buffer.from(base64Data, "base64");
    return { dataUrl: trimmed, size: buffer.length, mimeType };
  }

  const mimeType = resolveMimeType(fileName);
  const buffer = Buffer.from(trimmed, "base64");
  return {
    dataUrl: `data:${mimeType};base64,${trimmed}`,
    size: buffer.length,
    mimeType,
  };
}

type BusinessBrandingInfoRecord = {
  businessName?: string | null;
  email?: string | null;
  phone?: string | null;
  businessAddress?: string | null;
  organizationNumber?: string | null;
  website?: string | null;
  vatNumber?: string | null;
  tagline?: string | null;
  brandingColor?: string | null;
  customLogo?: string | null;
  businessDescription?: string | null;
  customFooterText?: string | null;
  profession?: string | null;
};

function normalizeBrandingHexColor(value: unknown): string | null {
  const raw = readString(value);
  if (!raw) return null;
  const normalized = raw.startsWith("#") ? raw.slice(1) : raw;
  if (/^[0-9a-f]{3}$/i.test(normalized)) {
    return `#${normalized
      .split("")
      .map((entry) => `${entry}${entry}`)
      .join("")
      .toLowerCase()}`;
  }
  if (/^[0-9a-f]{6}$/i.test(normalized)) {
    return `#${normalized.toLowerCase()}`;
  }
  return null;
}

function normalizeBusinessBrandingInfo(
  payload: unknown,
): BusinessBrandingInfoRecord {
  const record = normalizeJsonObjectField(payload) || {};
  return {
    businessName:
      readString(record.businessName) ||
      readString(record.companyName) ||
      readString(record.name),
    email: readString(record.email) || readString(record.contactEmail),
    phone: readString(record.phone),
    businessAddress:
      readString(record.businessAddress) || readString(record.address),
    organizationNumber:
      readString(record.organizationNumber) || readString(record.orgNumber),
    website: readString(record.website),
    vatNumber: readString(record.vatNumber) || readString(record.taxId),
    tagline: readString(record.tagline),
    brandingColor:
      normalizeBrandingHexColor(record.brandingColor) ||
      normalizeBrandingHexColor(record.brandColor) ||
      normalizeBrandingHexColor(record.primaryColor),
    customLogo:
      readString(record.customLogo) ||
      readString(record.logoUrl) ||
      readString(record.logo),
    businessDescription:
      readString(record.businessDescription) || readString(record.description),
    customFooterText:
      readString(record.customFooterText) || readString(record.footerText),
    profession: readString(record.profession),
  };
}

function toBusinessBrandingResponse(
  branding: DocumentBrandingProfile,
  overrides?: BusinessBrandingInfoRecord | null,
) {
  return {
    businessName: overrides?.businessName ?? branding.businessName ?? "",
    email: overrides?.email ?? branding.email ?? "",
    phone: overrides?.phone ?? branding.phone ?? "",
    businessAddress:
      overrides?.businessAddress ?? branding.businessAddress ?? "",
    organizationNumber:
      overrides?.organizationNumber ?? branding.organizationNumber ?? "",
    website: overrides?.website ?? branding.website ?? "",
    vatNumber: overrides?.vatNumber ?? branding.vatNumber ?? "",
    tagline: overrides?.tagline ?? branding.tagline ?? "",
    brandingColor: overrides?.brandingColor ?? branding.accentColor ?? "",
    customLogo: overrides?.customLogo ?? branding.logoUrl ?? "",
    businessDescription:
      overrides?.businessDescription ?? branding.businessDescription ?? "",
    customFooterText:
      overrides?.customFooterText ?? branding.customFooterText ?? "",
    profession: overrides?.profession ?? "",
  };
}

function brandingSettingsStoreKey(userId: string) {
  return dbLegacySettingKey(userId, BUSINESS_BRANDING_SETTINGS_NAMESPACE);
}

function userSettingsStoreKey(userId: string) {
  return dbLegacySettingKey(userId, "creatorhub_user_settings");
}

function normalizeBrandingProfession(
  profession: string | null | undefined,
): string {
  const normalized = readString(profession)?.toLowerCase();
  if (!normalized) return "other";
  if (normalized === "music_producer") return "musician";
  if (normalized === "enterprise") return "other";
  return normalized;
}

function omitNilValues(record: Record<string, unknown>) {
  return Object.fromEntries(
    Object.entries(record).filter(
      ([, value]) => value !== undefined && value !== null && value !== "",
    ),
  );
}

async function getStoredBusinessBrandingInfo(
  userId: string,
): Promise<BusinessBrandingInfoRecord> {
  const entry = await compatStoreGet<LegacySettingEntry>(
    brandingSettingsStoreKey(userId),
  );
  return normalizeBusinessBrandingInfo(entry?.data);
}

async function syncBrandingIntoUserSettings(
  userId: string,
  businessInfo: BusinessBrandingInfoRecord,
): Promise<void> {
  try {
    const existingEntry = await compatStoreGet<LegacySettingEntry>(
      userSettingsStoreKey(userId),
    );
    const existingData = normalizeJsonObjectField(existingEntry?.data) || {};
    const existingUi = normalizeJsonObjectField(existingData.ui) || {};
    const nextUi = {
      ...existingUi,
      ...(businessInfo.brandingColor
        ? {
            accentColor: businessInfo.brandingColor,
            primaryColor:
              readString(existingUi.primaryColor) || businessInfo.brandingColor,
          }
        : {}),
    };

    const nextEntry: LegacySettingEntry = {
      userId,
      projectId: existingEntry?.projectId,
      namespace: "creatorhub_user_settings",
      data: {
        ...existingData,
        ui: nextUi,
      },
    };

    await compatStoreSet(userSettingsStoreKey(userId), nextEntry);
  } catch (error) {
    console.warn("Unable to mirror branding into user settings:", error);
  }
}

async function mirrorBusinessBrandingToProfiles(
  userId: string,
  profession: string | null | undefined,
  businessInfo: BusinessBrandingInfoRecord,
): Promise<void> {
  const vendorType = normalizeBrandingProfession(
    profession || businessInfo.profession,
  );
  const vendorName = businessInfo.businessName || "CreatorHub";
  const now = new Date().toISOString();
  const businessInfoPatch = omitNilValues({
    businessName: businessInfo.businessName,
    companyName: businessInfo.businessName,
    email: businessInfo.email,
    contactEmail: businessInfo.email,
    phone: businessInfo.phone,
    website: businessInfo.website,
    businessAddress: businessInfo.businessAddress,
    organizationNumber: businessInfo.organizationNumber,
    orgNumber: businessInfo.organizationNumber,
    vatNumber: businessInfo.vatNumber,
    tagline: businessInfo.tagline,
    brandingColor: businessInfo.brandingColor,
    customLogo: businessInfo.customLogo,
    logoUrl: businessInfo.customLogo,
    businessDescription: businessInfo.businessDescription,
    description: businessInfo.businessDescription,
    customFooterText: businessInfo.customFooterText,
    updatedFromBrandingSettingsAt: now,
  });
  const contactInfoPatch = omitNilValues({
    email: businessInfo.email,
    phone: businessInfo.phone,
    website: businessInfo.website,
    address: businessInfo.businessAddress,
  });

  if (Object.prototype.hasOwnProperty.call(businessInfo, "customLogo")) {
    businessInfoPatch.customLogo = businessInfo.customLogo ?? null;
    businessInfoPatch.logoUrl = businessInfo.customLogo ?? null;
  }
  if (Object.prototype.hasOwnProperty.call(businessInfo, "brandingColor")) {
    businessInfoPatch.brandingColor = businessInfo.brandingColor ?? null;
  }
  if (Object.prototype.hasOwnProperty.call(businessInfo, "customFooterText")) {
    businessInfoPatch.customFooterText = businessInfo.customFooterText ?? null;
  }
  if (
    Object.prototype.hasOwnProperty.call(businessInfo, "businessDescription")
  ) {
    businessInfoPatch.businessDescription =
      businessInfo.businessDescription ?? null;
    businessInfoPatch.description = businessInfo.businessDescription ?? null;
  }

  if (await hasTable("vendors")) {
    try {
      const vendorColumns = await getTableColumns("vendors");
      if (vendorColumns.has("user_id")) {
        const selectFragments = ["id"];
        if (vendorColumns.has("business_info"))
          selectFragments.push("business_info");
        if (vendorColumns.has("contact_info"))
          selectFragments.push("contact_info");

        const existingVendor = await pool.query(
          `SELECT ${selectFragments.join(", ")}
             FROM vendors
            WHERE user_id = $1
            ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
            LIMIT 1`,
          [userId],
        );

        if (existingVendor.rows[0]?.id) {
          const mergedBusinessInfo = vendorColumns.has("business_info")
            ? {
                ...(normalizeJsonObjectField(
                  existingVendor.rows[0].business_info,
                ) || {}),
                ...businessInfoPatch,
              }
            : null;
          const mergedContactInfo = vendorColumns.has("contact_info")
            ? {
                ...(normalizeJsonObjectField(
                  existingVendor.rows[0].contact_info,
                ) || {}),
                ...contactInfoPatch,
              }
            : null;

          const assignments: string[] = [];
          const values: unknown[] = [existingVendor.rows[0].id];
          let parameterIndex = values.length + 1;

          if (vendorColumns.has("vendor_name")) {
            assignments.push(`vendor_name = $${parameterIndex++}`);
            values.push(vendorName);
          }
          if (vendorColumns.has("vendor_type")) {
            assignments.push(`vendor_type = $${parameterIndex++}`);
            values.push(vendorType);
          }
          if (vendorColumns.has("business_info")) {
            assignments.push(`business_info = $${parameterIndex++}::jsonb`);
            values.push(JSON.stringify(mergedBusinessInfo));
          }
          if (vendorColumns.has("contact_info")) {
            assignments.push(`contact_info = $${parameterIndex++}::jsonb`);
            values.push(JSON.stringify(mergedContactInfo));
          }
          if (vendorColumns.has("business_name")) {
            assignments.push(`business_name = $${parameterIndex++}`);
            values.push(businessInfo.businessName ?? vendorName);
          }
          if (vendorColumns.has("organization_number")) {
            assignments.push(`organization_number = $${parameterIndex++}`);
            values.push(businessInfo.organizationNumber ?? null);
          }
          if (vendorColumns.has("description")) {
            assignments.push(`description = $${parameterIndex++}`);
            values.push(businessInfo.businessDescription ?? null);
          }
          if (vendorColumns.has("phone")) {
            assignments.push(`phone = $${parameterIndex++}`);
            values.push(businessInfo.phone ?? null);
          }
          if (vendorColumns.has("website")) {
            assignments.push(`website = $${parameterIndex++}`);
            values.push(businessInfo.website ?? null);
          }
          if (vendorColumns.has("image_url")) {
            assignments.push(`image_url = $${parameterIndex++}`);
            values.push(businessInfo.customLogo ?? null);
          }
          if (vendorColumns.has("updated_at")) {
            assignments.push("updated_at = NOW()");
          }

          if (assignments.length > 0) {
            await pool.query(
              `UPDATE vendors SET ${assignments.join(", ")} WHERE id = $1`,
              values,
            );
          }
        } else {
          const insertColumns = ["id", "user_id"];
          const insertValues: unknown[] = [crypto.randomUUID(), userId];
          const insertFragments = ["$1", "$2"];
          let parameterIndex = insertValues.length + 1;

          if (vendorColumns.has("vendor_name")) {
            insertColumns.push("vendor_name");
            insertValues.push(vendorName);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("vendor_type")) {
            insertColumns.push("vendor_type");
            insertValues.push(vendorType);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("contact_info")) {
            insertColumns.push("contact_info");
            insertValues.push(JSON.stringify(contactInfoPatch));
            insertFragments.push(`$${parameterIndex++}::jsonb`);
          }
          if (vendorColumns.has("business_info")) {
            insertColumns.push("business_info");
            insertValues.push(JSON.stringify(businessInfoPatch));
            insertFragments.push(`$${parameterIndex++}::jsonb`);
          }
          if (vendorColumns.has("business_name")) {
            insertColumns.push("business_name");
            insertValues.push(businessInfo.businessName ?? vendorName);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("organization_number")) {
            insertColumns.push("organization_number");
            insertValues.push(businessInfo.organizationNumber ?? null);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("description")) {
            insertColumns.push("description");
            insertValues.push(businessInfo.businessDescription ?? null);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("phone")) {
            insertColumns.push("phone");
            insertValues.push(businessInfo.phone ?? null);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("website")) {
            insertColumns.push("website");
            insertValues.push(businessInfo.website ?? null);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("image_url")) {
            insertColumns.push("image_url");
            insertValues.push(businessInfo.customLogo ?? null);
            insertFragments.push(`$${parameterIndex++}`);
          }
          if (vendorColumns.has("created_at")) {
            insertColumns.push("created_at");
            insertFragments.push("NOW()");
          }
          if (vendorColumns.has("updated_at")) {
            insertColumns.push("updated_at");
            insertFragments.push("NOW()");
          }

          await pool.query(
            `INSERT INTO vendors (${insertColumns.join(", ")}) VALUES (${insertFragments.join(", ")})`,
            insertValues,
          );
        }
      }
    } catch (error) {
      if (!isUndefinedTableError(error, "vendors")) {
        console.warn("Unable to mirror business branding to vendors:", error);
      }
    }
  }

  if (await hasTable("vendor_onboarding_profiles")) {
    try {
      const existingProfile = await pool.query(
        `SELECT id, business_info
           FROM vendor_onboarding_profiles
          WHERE user_id = $1
          ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
          LIMIT 1`,
        [userId],
      );

      if (existingProfile.rows[0]?.id) {
        const mergedBusinessInfo = {
          ...(normalizeJsonObjectField(existingProfile.rows[0].business_info) ||
            {}),
          ...businessInfoPatch,
        };

        await pool.query(
          `UPDATE vendor_onboarding_profiles
              SET vendor_name = COALESCE($2, vendor_name),
                  vendor_type = COALESCE($3, vendor_type),
                  business_info = $4::jsonb,
                  updated_at = NOW()
            WHERE id = $1`,
          [
            existingProfile.rows[0].id,
            vendorName,
            vendorType,
            JSON.stringify(mergedBusinessInfo),
          ],
        );
      } else {
        await pool.query(
          `INSERT INTO vendor_onboarding_profiles (
             id, user_id, vendor_type, vendor_name, business_info, vendor_specific_data,
             is_complete, completed_at, created_at, updated_at
           ) VALUES (
             $1, $2, $3, $4, $5::jsonb, '{}'::jsonb, false, NULL, NOW(), NOW()
           )`,
          [
            crypto.randomUUID(),
            userId,
            vendorType,
            vendorName,
            JSON.stringify(businessInfoPatch),
          ],
        );
      }
    } catch (error) {
      if (!isUndefinedTableError(error, "vendor_onboarding_profiles")) {
        console.warn(
          "Unable to mirror business branding to onboarding profiles:",
          error,
        );
      }
    }
  }
}

async function persistBusinessBrandingInfo(
  userId: string,
  businessInfo: BusinessBrandingInfoRecord,
): Promise<BusinessBrandingInfoRecord> {
  const existing = await getStoredBusinessBrandingInfo(userId);
  const next: BusinessBrandingInfoRecord = {
    ...existing,
    ...businessInfo,
  };

  const entry: LegacySettingEntry = {
    userId,
    namespace: BUSINESS_BRANDING_SETTINGS_NAMESPACE,
    data: next,
  };

  await compatStoreSet(brandingSettingsStoreKey(userId), entry);
  await syncBrandingIntoUserSettings(userId, next);
  await mirrorBusinessBrandingToProfiles(userId, next.profession, next);
  return next;
}

async function persistBrandingLogoAsset(params: {
  userId: string;
  fileName: string;
  dataUrl: string;
  mimeType: string;
  size: number;
}) {
  if (!(await hasTable("user_files"))) {
    return;
  }

  try {
    const columns = await getTableColumns("user_files");
    const insertColumns = [
      "id",
      "user_id",
      "file_name",
      "file_path",
      "file_type",
      "file_size",
      "mime_type",
      "metadata",
    ].filter((column) => columns.has(column));

    if (columns.has("file_url")) {
      insertColumns.splice(4, 0, "file_url");
    }

    if (insertColumns.length === 0) {
      return;
    }

    const values = insertColumns.map((column) => {
      switch (column) {
        case "id":
          return crypto.randomUUID();
        case "user_id":
          return params.userId;
        case "file_name":
          return params.fileName;
        case "file_path":
          return `branding-logos/${params.userId}/${Date.now()}-${params.fileName}`;
        case "file_url":
          return params.dataUrl;
        case "file_type":
          return "branding_logo";
        case "file_size":
          return String(params.size);
        case "mime_type":
          return params.mimeType;
        case "metadata":
          return JSON.stringify({ source: "branding-settings" });
        default:
          return null;
      }
    });

    const placeholders = insertColumns
      .map((_, index) => `$${index + 1}`)
      .join(", ");
    await pool.query(
      `INSERT INTO user_files (${insertColumns.join(", ")}) VALUES (${placeholders})`,
      values,
    );
  } catch (error) {
    console.warn("Unable to persist branding logo asset:", error);
  }
}

function normalizeEquipmentType(raw?: string | null): EquipmentType {
  const value = (raw || "").toLowerCase();
  if (value.includes("camera")) return "camera";
  if (value.includes("lens")) return "lens";
  if (value.includes("audio") || value.includes("microphone")) return "audio";
  if (value.includes("software")) return "software";
  if (
    value.includes("computer") ||
    value.includes("laptop") ||
    value.includes("pc")
  )
    return "computer";
  if (value.includes("light")) return "lighting";
  if (
    value.includes("memory") ||
    value.includes("card") ||
    value.includes("storage")
  )
    return "memory";
  if (value.includes("tripod")) return "tripod";
  if (value.includes("slider")) return "slider";
  if (value.includes("flash") || value.includes("strobe")) return "flash";
  if (value.includes("accessory") || value.includes("tilbehor"))
    return "accessory";
  return "accessory";
}

function normalizeCondition(raw?: string | null): EquipmentCondition {
  const value = (raw || "").toLowerCase();
  if (value.includes("excellent") || value.includes("ny")) return "excellent";
  if (value.includes("good") || value.includes("bra")) return "good";
  if (value.includes("fair") || value.includes("ok")) return "fair";
  if (value.includes("poor") || value.includes("darlig")) return "poor";
  if (value.includes("critical") || value.includes("kritisk"))
    return "critical";
  return "good";
}

function normalizeTaskType(raw?: string | null): MaintenanceTaskType {
  const value = (raw || "").toLowerCase();
  if (value.includes("clean")) return "cleaning";
  if (value.includes("calib")) return "calibration";
  if (value.includes("repair") || value.includes("service")) return "repair";
  if (value.includes("replace")) return "replacement";
  if (value.includes("upgrade")) return "upgrade";
  return "inspection";
}

function normalizePriority(raw?: string | null): MaintenancePriority {
  const value = (raw || "").toLowerCase();
  if (value.includes("critical") || value.includes("kritisk"))
    return "critical";
  if (value.includes("high") || value.includes("hoy")) return "high";
  if (value.includes("low") || value.includes("lav")) return "low";
  return "medium";
}

function normalizeStatus(raw?: string | null): MaintenanceStatus | null {
  const value = (raw || "").toLowerCase();
  if (value === "scheduled" || value === "planlagt") return "scheduled";
  if (value === "in_progress" || value === "paagar") return "in_progress";
  if (value === "completed" || value === "fullfort") return "completed";
  if (value === "cancelled" || value === "avbrutt") return "cancelled";
  if (value === "overdue" || value === "forsinket") return "overdue";
  return null;
}

function toIsoString(value: unknown): string | null {
  if (!value) return null;
  if (value instanceof Date)
    return Number.isNaN(value.getTime()) ? null : value.toISOString();
  if (typeof value === "string") {
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime())) return parsed.toISOString();
  }
  return null;
}

function toDateOnly(value: string | Date): string {
  const parsed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return new Date().toISOString().slice(0, 10);
  }
  return parsed.toISOString().slice(0, 10);
}

function addMonths(date: Date, months: number): Date {
  const result = new Date(date.getTime());
  result.setMonth(result.getMonth() + months);
  return result;
}

type DateRange = { start: Date; end: Date };

const monthLabels = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
];

function parseRangeParam(range?: string | null): DateRange {
  const now = new Date();
  const match = range ? /^([0-9]+)([dmy])$/i.exec(range) : null;
  const value = match ? Number(match[1]) : 12;
  const unit = match ? match[2].toLowerCase() : "m";
  const start = new Date(now.getTime());
  if (unit === "d") {
    start.setDate(start.getDate() - value);
  } else if (unit === "y") {
    start.setFullYear(start.getFullYear() - value);
  } else {
    start.setMonth(start.getMonth() - value);
  }
  return { start, end: now };
}

function toNumberValue(value: unknown, fallback = 0): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value === "string" && value.trim() !== "") {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }
  return fallback;
}

function toDateOrNull(value: unknown): Date | null {
  if (!value) return null;
  if (value instanceof Date)
    return Number.isNaN(value.getTime()) ? null : value;
  if (typeof value === "string") {
    const parsed = new Date(value);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }
  return null;
}

function monthKey(date: Date): string {
  return `${date.getFullYear()}-${date.getMonth() + 1}`;
}

function buildMonthlyBuckets(start: Date, end: Date) {
  const buckets: Array<{ key: string; label: string; date: Date }> = [];
  const cursor = new Date(start.getFullYear(), start.getMonth(), 1);
  const endCursor = new Date(end.getFullYear(), end.getMonth(), 1);
  while (cursor <= endCursor) {
    const key = monthKey(cursor);
    const label = `${monthLabels[cursor.getMonth()]} ${String(cursor.getFullYear()).slice(2)}`;
    buckets.push({ key, label, date: new Date(cursor.getTime()) });
    cursor.setMonth(cursor.getMonth() + 1);
  }
  return buckets;
}

function buildProjectFilter(userId?: string, profession?: string) {
  const hasUser = Boolean(userId);
  const hasProfession = Boolean(profession);
  if (hasUser && hasProfession) {
    return and(
      eq(schema.projects.userId, userId as string),
      eq(schema.projects.profession, profession as string),
    );
  }
  if (hasUser) return eq(schema.projects.userId, userId as string);
  if (hasProfession)
    return eq(schema.projects.profession, profession as string);
  return undefined;
}

function buildFeedbackFilter(userId?: string) {
  if (!userId) return undefined;
  return eq(schema.clientFeedbacks.userId, userId);
}

const audioStorageDir = path.resolve(process.cwd(), "tmp", "audio-files");
const audioFileStore = new Map<
  string,
  {
    filePath: string;
    mime: string;
    name: string;
    size: number;
    createdAt: number;
  }
>();

async function ensureAudioStorageDir() {
  await fs.mkdir(audioStorageDir, { recursive: true });
}

function fileExtensionFromName(name: string | undefined, mime: string) {
  if (name && name.includes(".")) return `.${name.split(".").pop()}`;
  if (mime === "audio/mpeg") return ".mp3";
  if (mime === "audio/wav" || mime === "audio/x-wav") return ".wav";
  if (mime === "audio/flac") return ".flac";
  if (mime === "audio/aac") return ".aac";
  if (mime === "audio/ogg") return ".ogg";
  if (mime === "audio/mp4") return ".m4a";
  if (mime === "audio/webm") return ".webm";
  return "";
}

async function storeAudioFile(buffer: Buffer, name: string, mime: string) {
  await ensureAudioStorageDir();
  const id = crypto.randomUUID();
  const ext = fileExtensionFromName(name, mime);
  const filePath = path.join(audioStorageDir, `${id}${ext}`);
  await fs.writeFile(filePath, buffer);
  audioFileStore.set(id, {
    filePath,
    mime,
    name,
    size: buffer.length,
    createdAt: Date.now(),
  });
  return { id, url: `/api/audio/file/${id}` };
}

async function getAudioBufferFromUrl(audioUrl: string) {
  const normalizedSource = normalizeVideoSourcePath(audioUrl);
  if (!normalizedSource) {
    throw new Error("Missing audio source");
  }

  const storedMatch = normalizedSource.match(/\/api\/audio\/file\/(.+)$/);
  if (storedMatch) {
    const stored = audioFileStore.get(storedMatch[1]);
    if (stored) {
      const buffer = await fs.readFile(stored.filePath);
      return { buffer, size: stored.size, mime: stored.mime };
    }
  }

  if (isHttpUrl(normalizedSource)) {
    const response = await fetch(normalizedSource);
    if (!response.ok) {
      throw new Error("Failed to fetch audio");
    }
    const arrayBuffer = await response.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);
    return {
      buffer,
      size: buffer.length,
      mime: response.headers.get("content-type") || "audio/mpeg",
    };
  }

  let localPath = normalizedSource;
  if (localPath.startsWith("file://")) {
    localPath = fileURLToPath(localPath);
  }
  if (!path.isAbsolute(localPath)) {
    localPath = path.resolve(process.cwd(), localPath);
  }

  const buffer = await fs.readFile(localPath);
  const extension = path.extname(localPath).toLowerCase();
  const mimeByExtension: Record<string, string> = {
    ".wav": "audio/wav",
    ".wave": "audio/wav",
    ".mp3": "audio/mpeg",
    ".m4a": "audio/mp4",
    ".aac": "audio/aac",
    ".flac": "audio/flac",
    ".ogg": "audio/ogg",
    ".webm": "audio/webm",
  };
  const mime = mimeByExtension[extension] || "audio/mpeg";
  return { buffer, size: buffer.length, mime };
}

function seedFromString(value: string) {
  let hash = 0;
  for (let i = 0; i < value.length; i += 1) {
    hash = (hash * 31 + value.charCodeAt(i)) % 2147483647;
  }
  return hash || 1;
}

function seededRandom(seed: number) {
  let value = seed;
  return () => {
    value = (value * 48271) % 2147483647;
    return value / 2147483647;
  };
}

function generateWaveform(samples: number, seed: number) {
  const rand = seededRandom(seed);
  return Array.from({ length: samples }, (_, i) => {
    const noise = rand() * 0.2;
    const wave = Math.sin(i / 10) * 0.6 + Math.sin(i / 30) * 0.3;
    return Math.min(1, Math.max(0, Math.abs(wave) + noise));
  });
}

function generateSpectrum(bins: number, seed: number) {
  const rand = seededRandom(seed);
  return Array.from({ length: bins }, (_, i) => {
    const base = Math.exp(-i / (bins / 3));
    const jitter = rand() * 0.2;
    return Number(((base + jitter) * -60 + 60).toFixed(2));
  });
}

type EquipmentRow = typeof schema.userEquipment.$inferSelect;
type MaintenanceRow = typeof schema.equipmentMaintenance.$inferSelect;

type MaintenanceMetadata = {
  partsRequired?: string[];
  safetyRequirements?: string[];
  reminderSent?: boolean;
  automatedBooking?: boolean;
  technicianContact?: string;
  priority?: string;
  status?: string;
  title?: string;
  actualCost?: number;
  actualDuration?: number;
};

function parseMaintenanceMetadata(value: unknown): MaintenanceMetadata {
  if (!value) return {};
  if (Array.isArray(value)) {
    return { partsRequired: readStringArray(value) };
  }
  if (typeof value !== "object") return {};
  const record = value as Record<string, unknown>;
  return {
    partsRequired: readStringArray(record.partsRequired ?? record.parts),
    safetyRequirements: readStringArray(record.safetyRequirements),
    reminderSent: readBoolean(record.reminderSent) ?? undefined,
    automatedBooking: readBoolean(record.automatedBooking) ?? undefined,
    technicianContact: readString(record.technicianContact) ?? undefined,
    priority: readString(record.priority) ?? undefined,
    status: readString(record.status) ?? undefined,
    title: readString(record.title) ?? undefined,
    actualCost: readNumber(record.actualCost) ?? undefined,
    actualDuration: readNumber(record.actualDuration) ?? undefined,
  };
}

function resolveScheduledDate(row: MaintenanceRow): string {
  const scheduled = toIsoString(row.scheduledDate);
  if (scheduled) return scheduled;
  const nextScheduled = toIsoString(row.nextScheduledDate);
  if (nextScheduled) return nextScheduled;
  const created = toIsoString(row.createdAt);
  return created || new Date().toISOString();
}

function mapMaintenanceRow(
  row: MaintenanceRow,
  equipmentMap: Map<string, EquipmentRow>,
) {
  const metadata = parseMaintenanceMetadata(row.partsReplaced);
  const scheduledDate = resolveScheduledDate(row);
  const completedDate = toIsoString(row.completedDate);
  const isCompleted = Boolean(completedDate);
  const scheduledTime = new Date(scheduledDate).getTime();
  const isOverdue =
    !isCompleted &&
    Number.isFinite(scheduledTime) &&
    scheduledTime < Date.now();
  const statusFromMetadata = normalizeStatus(metadata.status || null);
  const status: MaintenanceStatus = isCompleted
    ? "completed"
    : isOverdue
      ? "overdue"
      : statusFromMetadata || "scheduled";

  const priority = normalizePriority(metadata.priority || null);
  const equipment = equipmentMap.get(row.equipmentId);
  const equipmentName = equipment
    ? `${equipment.brand} ${equipment.model}`.trim()
    : "Ukjent utstyr";

  return {
    id: row.id,
    equipmentId: row.equipmentId,
    equipmentName,
    taskType: normalizeTaskType(row.maintenanceType),
    title: metadata.title || row.description,
    description: row.description,
    priority,
    scheduledDate,
    estimatedDuration: readNumber(row.laborHours) ?? 1,
    estimatedCost: readNumber(row.cost) ?? 0,
    assignedTechnician: row.serviceProvider || "",
    technicianContact: metadata.technicianContact || "",
    status,
    completedDate,
    actualCost: metadata.actualCost ?? null,
    actualDuration: metadata.actualDuration ?? null,
    notes: row.serviceNotes || "",
    partsRequired: metadata.partsRequired || [],
    safetyRequirements: metadata.safetyRequirements || [],
    reminderSent: metadata.reminderSent ?? false,
    automatedBooking: metadata.automatedBooking ?? false,
  };
}

async function loadFirmwareDevices(
  userId?: string | null,
  profession?: string | null,
) {
  const conditions = [];
  if (userId) {
    conditions.push(eq(schema.userEquipment.userId, userId));
  }
  if (profession) {
    conditions.push(eq(schema.userEquipment.userType, profession));
  }

  const rows = await db
    .select()
    .from(schema.userEquipment)
    .where(conditions.length ? and(...conditions) : sql`true`);

  return rows.map((row) => {
    const settings = parseSettings(row.settings);
    return {
      id: row.id,
      brand: row.brand,
      model: row.model,
      type: row.category || "accessory",
      currentFirmware: row.firmwareVersion || null,
      serialNumber: row.serialNumber || null,
      purchaseDate: row.purchaseDate || null,
      lastChecked:
        typeof settings.lastFirmwareCheck === "string"
          ? settings.lastFirmwareCheck
          : null,
      autoUpdateEnabled:
        typeof settings.autoUpdateEnabled === "boolean"
          ? settings.autoUpdateEnabled
          : true,
      updateChannel:
        typeof settings.updateChannel === "string"
          ? settings.updateChannel
          : "stable",
      criticalUpdatesOnly:
        typeof settings.criticalUpdatesOnly === "boolean"
          ? settings.criticalUpdatesOnly
          : false,
      maintenanceMode:
        typeof settings.maintenanceMode === "boolean"
          ? settings.maintenanceMode
          : false,
    };
  });
}

async function loadFirmwareUpdates(
  userId?: string | null,
  profession?: string | null,
) {
  if (!(await hasTable("firmware_updates"))) return [];
  await ensureFirmwareUpdatesCompatibilityColumns();
  const devices = await loadFirmwareDevices(userId, profession);
  if (devices.length === 0) return [];

  const deviceFilters = devices.map((device) =>
    and(
      sql`regexp_replace(lower(coalesce(${schema.firmwareUpdates.brand}, '')), '[^a-z0-9]+', '', 'g') =
          regexp_replace(lower(${device.brand}), '[^a-z0-9]+', '', 'g')`,
      sql`regexp_replace(lower(coalesce(${schema.firmwareUpdates.model}, '')), '[^a-z0-9]+', '', 'g') =
          regexp_replace(lower(${device.model}), '[^a-z0-9]+', '', 'g')`,
    ),
  );

  const firmwareRows = await db
    .select()
    .from(schema.firmwareUpdates)
    .where(or(...deviceFilters));

  const latestByDevice = new Map<string, (typeof firmwareRows)[number]>();
  firmwareRows.forEach((row) => {
    const key = toFirmwareDeviceKey(row.brand, row.model);
    const existing = latestByDevice.get(key);
    if (!existing) {
      latestByDevice.set(key, row);
      return;
    }
    if (row.isLatest && !existing.isLatest) {
      latestByDevice.set(key, row);
      return;
    }

    const existingDate = new Date(
      existing.releaseDate || existing.createdAt || 0,
    );
    const rowDate = new Date(row.releaseDate || row.createdAt || 0);
    if (rowDate > existingDate) {
      latestByDevice.set(key, row);
    }
  });

  const updates = devices
    .map((device) => {
      const key = toFirmwareDeviceKey(device.brand, device.model);
      const firmware = latestByDevice.get(key);
      if (!firmware) return null;

      const currentVersion = device.currentFirmware || null;
      if (
        currentVersion &&
        compareVersions(firmware.version, currentVersion) <= 0
      ) {
        return null;
      }

      const releaseNotes = normalizeNotes(firmware.releaseNotes);
      const newFeatures = releaseNotes.filter((note) =>
        /ny|forbedret|stotte|støtte/i.test(note),
      );
      const bugFixes = releaseNotes.filter((note) =>
        /bug|feil|fikset/i.test(note),
      );
      const securityUpdates = releaseNotes.filter((note) =>
        /sikker/i.test(note),
      );
      const canonicalProfile = resolveCanonicalFirmwareProfileByDevice(
        device.brand,
        device.model,
        device.type,
      );
      const genericModelSupportReleaseDate =
        canonicalProfile?.urlKind === "model-support" &&
        firmware.version === "1.0.0";
      const resolvedReleaseDate = genericModelSupportReleaseDate
        ? firmware.lastChecked ||
          firmware.updatedAt ||
          firmware.createdAt ||
          firmware.releaseDate ||
          new Date().toISOString()
        : firmware.releaseDate ||
          firmware.createdAt ||
          new Date().toISOString();

      return {
        id: firmware.id,
        deviceBrand: firmware.brand,
        deviceModel: firmware.model,
        deviceType: device.type,
        currentVersion: currentVersion || "Ukjent",
        latestVersion: firmware.version,
        releaseDate: resolvedReleaseDate,
        priority: mapImportance(firmware.importance),
        updateSize: null,
        description:
          firmware.description || "Firmware-oppdatering tilgjengelig",
        releaseNotes,
        bugFixes,
        newFeatures,
        securityUpdates,
        compatibility: [],
        downloadUrl: firmware.downloadUrl || firmware.sourceUrl || "",
        urlKind: canonicalProfile?.urlKind || "brand-portal",
        installationTime: estimateInstallMinutes(device.type, null),
        status: "available",
        autoUpdate: device.autoUpdateEnabled ?? true,
        backupRequired: device.type !== "software",
        restartRequired: true,
      };
    })
    .filter(Boolean);

  return updates;
}

async function loadFirmwareHistory(
  userId?: string | null,
  profession?: string | null,
) {
  const history: any[] = [];
  const conditions = [];
  if (userId) {
    conditions.push(eq(schema.userEquipment.userId, userId));
  }
  if (profession) {
    conditions.push(eq(schema.userEquipment.userType, profession));
  }

  const rawRows = await db
    .select({
      id: schema.userEquipment.id,
      settings: schema.userEquipment.settings,
    })
    .from(schema.userEquipment)
    .where(conditions.length ? and(...conditions) : sql`true`);

  rawRows.forEach((row) => {
    const settings = parseSettings(row.settings);
    const entries = Array.isArray(settings.firmwareUpdateHistory)
      ? settings.firmwareUpdateHistory
      : [];
    entries.forEach((entry) => history.push(entry));
  });

  history.sort((a, b) => {
    const aDate = new Date(a.completedAt || 0).getTime();
    const bDate = new Date(b.completedAt || 0).getTime();
    return bDate - aDate;
  });

  return history;
}

// Helper function to calculate comprehensive contract hash for verification
function calculateContractHash(contract: any): string {
  // Include all critical contract fields to detect tampering
  const hashData = [
    contract.id,
    contract.clientName,
    contract.clientEmail,
    contract.projectDescription,
    contract.totalAmount,
    contract.eventDate,
    contract.eventLocation,
    contract.contractType,
    contract.contractTitle,
    contract.customerType,
    contract.organizationNumber,
    contract.organizationName,
    JSON.stringify(contract.sections || []), // Include all sections
    contract.signerName,
    contract.signedAt,
  ].join("|||");

  return crypto.createHash("sha256").update(hashData).digest("hex");
}

const serverStartedAt = new Date().toISOString();

// ── Public client-gallery viewer endpoints ──────────────────────────────
//
// Unauthenticated — the accessToken IS the auth. Every request re-signs
// Capture-sourced image URLs so the gallery keeps working past R2's
// 7-day signed-URL ceiling.

// Slice 9X.82 (Bjarne) — Video-timecode-kommentarer (Frame.io-stil)
// Klient kan kommentere på et spesifikt tidspunkt i video-leveransen.
async function ensureVideoTimecodeCommentsSchema(): Promise<void> {
  try {
    await pool.query(`
      CREATE TABLE IF NOT EXISTS video_timecode_comments (
        id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        gallery_id      VARCHAR(64) NOT NULL,
        chapter_id      VARCHAR(64),
        timecode_sec    NUMERIC(10,3) NOT NULL,
        comment         TEXT NOT NULL,
        client_email    VARCHAR(255) NOT NULL,
        client_name     VARCHAR(255),
        status          VARCHAR(32) NOT NULL DEFAULT 'open',
        resolved_at     TIMESTAMPTZ,
        resolved_by     VARCHAR(64),
        created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );
      CREATE INDEX IF NOT EXISTS idx_video_timecode_comments_gallery
        ON video_timecode_comments (gallery_id, chapter_id, timecode_sec);
      -- Slice 9X.82 edit-feedback: range, category, priority
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS end_timecode_sec NUMERIC(10,3);
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS category VARCHAR(32) DEFAULT 'other';
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS priority VARCHAR(16) DEFAULT 'suggestion';
      -- Slice 9X.82 music-suggestion på timecode
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS suggested_media_url TEXT;
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS suggested_media_label VARCHAR(255);
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS suggested_media_from_sec NUMERIC(10,3);
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS suggested_media_to_sec NUMERIC(10,3);
      -- Slice 9X.86 threading/replies
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS parent_id UUID
          REFERENCES video_timecode_comments(id) ON DELETE CASCADE;
      ALTER TABLE video_timecode_comments
        ADD COLUMN IF NOT EXISTS author_kind VARCHAR(20) NOT NULL DEFAULT 'client';
      CREATE INDEX IF NOT EXISTS idx_video_timecode_comments_parent
        ON video_timecode_comments (parent_id);
    `);
  } catch (e: any) {
    console.warn('[video-comments] schema-ensure failed:', e.message);
  }
}

function requireUserSession(
  req: express.Request,
  res: express.Response,
): { userId: string; email: string; name: string; role: string } | null {
  const session = getActiveSessionFromRequest(req);
  if (!session) {
    res.status(401).json({ error: "auth_required" });
    return null;
  }
  return session;
}

// ── Slice 9.6 — gallery email notifications ────────────────────────────
// Fire-and-forget dispatchers for the two highest-signal client events:
// new comment posted, selection submitted. Sent to the photographer's
// email so they know the client is active without having to refresh
// the dashboard. Best-effort: any failure (no SMTP config, lookup miss,
// SMTP timeout) logs + swallows so the originating POST always 2xx's.
//
// Why not session_notifications + cron-poll: that table targets the
// older client_gallery_sessions flow (separate from photographer_
// client_galleries that the iPad bridge uses). Direct dispatch here
// keeps the surface tight; richer queueing (deadline reminders,
// open-rate tracking) can land in Slice 12 alongside the engagement
// dashboard.

interface GalleryNotificationPayload {
  galleryId: string;
  galleryTitle: string | null;
  shareUrl: string;
  clientName: string;
  clientEmail: string;
  // Free-form per-event details surfaced in the email body.
  details: Record<string, unknown>;
}

type GalleryNotificationType =
  | 'comment_created'
  | 'selection_submitted'
  // Slice 9X.15 — project milestone reached, notify the CLIENT
  // (not the photographer) that their gallery has progress.
  | 'project_milestone';

async function lookupPhotographerEmail(photographerId: string): Promise<string | null> {
  if (!photographerId) return null;
  try {
    const r = await pool.query(`SELECT email FROM users WHERE id = $1 LIMIT 1`, [photographerId]);
    const email = r.rows[0]?.email;
    return typeof email === 'string' && email.includes('@') ? email : null;
  } catch (err) {
    console.warn('[gallery-notify] photographer email lookup failed:', err);
    return null;
  }
}

function buildGalleryNotificationEmail(
  type: GalleryNotificationType,
  payload: GalleryNotificationPayload,
): { subject: string; text: string; html: string } {
  const title = payload.galleryTitle || 'Galleri';
  const safeShareUrl = payload.shareUrl.replace(/[<>'"]/g, '');
  const clientLabel = `${payload.clientName} (${payload.clientEmail})`;

  if (type === 'comment_created') {
    const comment = String(payload.details.comment ?? '').slice(0, 500);
    return {
      subject: `${title}: ny kommentar fra ${payload.clientName}`,
      text: `${clientLabel} skrev en kommentar i galleriet "${title}":\n\n"${comment}"\n\nÅpne galleriet: ${safeShareUrl}`,
      html: `<p><strong>${clientLabel}</strong> skrev en kommentar i galleriet <em>${title}</em>:</p>
        <blockquote style="border-left:3px solid #ddd; padding:8px 12px; color:#333;">${comment.replace(/</g, '&lt;')}</blockquote>
        <p><a href="${safeShareUrl}" style="color:#0066cc;">Åpne galleriet</a></p>
        <hr style="border:none; border-top:1px solid #eee; margin:24px 0;">
        <p style="font-size:12px; color:#888;">Sendt automatisk fra CreatorHub. Du mottar dette fordi du eier galleriet.</p>`,
    };
  }

  if (type === 'project_milestone') {
    // Client-bound. Subject + body talk TO the client, not about them.
    const milestone = String(payload.details.milestone ?? 'oppdatering');
    const photographerName = String(payload.details.photographerName ?? 'Fotografen');
    const friendlyMilestone =
      milestone === 'completed'
        ? 'er ferdigstilt'
        : milestone === 'ready_for_review'
        ? 'er klar for din gjennomgang'
        : milestone === 'editing'
        ? 'er under redigering'
        : `har en ny status (${milestone})`;
    return {
      subject: `${title}: ${friendlyMilestone}`,
      text: `Hei ${payload.clientName},\n\nProsjektet "${title}" ${friendlyMilestone}.\n\nÅpne galleriet: ${safeShareUrl}\n\nMvh,\n${photographerName}`,
      html: `<p>Hei <strong>${payload.clientName}</strong>,</p>
        <p>Prosjektet <em>${title}</em> ${friendlyMilestone}.</p>
        <p><a href="${safeShareUrl}" style="color:#0066cc; font-size:16px; padding:12px 24px; background:#f5f5f5; border-radius:6px; text-decoration:none;">Åpne ditt galleri →</a></p>
        <p style="margin-top:24px;">Mvh,<br>${photographerName}</p>
        <hr style="border:none; border-top:1px solid #eee; margin:24px 0;">
        <p style="font-size:12px; color:#888;">Sendt automatisk fra CreatorHub.</p>`,
    };
  }

  // selection_submitted
  const selectedCount = Number(payload.details.selectedCount ?? 0);
  const totalAmount = Number(payload.details.totalAmount ?? 0);
  const currency = String(payload.details.currency ?? 'NOK');
  const requiresPayment = Boolean(payload.details.requiresPayment);
  return {
    subject: `${title}: ${payload.clientName} har valgt ${selectedCount} bilder`,
    text: `${clientLabel} har submittet sitt utvalg i galleriet "${title}".\n\nValgte bilder: ${selectedCount}\n${requiresPayment ? `Sum å betale: ${totalAmount} ${currency} (klient må betale ekstra-bilder før download låses opp)` : 'Alt innenfor inkluderte bilder — ingen ekstra-betaling kreves.'}\n\nÅpne galleriet: ${safeShareUrl}`,
    html: `<p><strong>${clientLabel}</strong> har submittet sitt utvalg i galleriet <em>${title}</em>.</p>
      <ul>
        <li>Valgte bilder: <strong>${selectedCount}</strong></li>
        ${requiresPayment
          ? `<li>Sum å betale: <strong>${totalAmount} ${currency}</strong> (klient må betale ekstra-bilder før download låses opp)</li>`
          : '<li>Alt innenfor inkluderte bilder — ingen ekstra-betaling kreves.</li>'}
      </ul>
      <p><a href="${safeShareUrl}" style="color:#0066cc;">Åpne galleriet</a></p>
      <hr style="border:none; border-top:1px solid #eee; margin:24px 0;">
      <p style="font-size:12px; color:#888;">Sendt automatisk fra CreatorHub. Du mottar dette fordi du eier galleriet.</p>`,
  };
}

/// Fire-and-forget dispatcher. Caller awaits nothing — call it via
/// setImmediate / Promise without await so the originating route's
/// response is never blocked on SMTP latency.
async function dispatchGalleryNotification(
  type: GalleryNotificationType,
  photographerId: string,
  payload: GalleryNotificationPayload,
): Promise<void> {
  try {
    const transporter = getRoleRoomEducationInquiryMailer();
    if (!transporter) {
      // SMTP not configured (dev / test / Render env without GMAIL_*).
      // Skip silently — same posture other notification paths take.
      return;
    }
    const photographerEmail = await lookupPhotographerEmail(photographerId);
    if (!photographerEmail) return;

    const fromAddress =
      process.env.GMAIL_USER ||
      process.env.GOOGLE_WORKSPACE_EMAIL ||
      process.env.GOOGLE_ADMIN_EMAIL ||
      'noreply@creatorhubn.com';

    const { subject, text, html } = buildGalleryNotificationEmail(type, payload);
    await transporter.sendMail({
      from: `CreatorHub <${fromAddress}>`,
      to: photographerEmail,
      replyTo: payload.clientEmail,
      subject,
      text,
      html,
    });
  } catch (err) {
    console.warn(`[gallery-notify] dispatch ${type} failed:`, err);
  }
}

// Slice 9X.15 — client-bound dispatcher. Same signature as the
// photographer-side one but sends to payload.clientEmail and uses
// the photographer's name as the From (so the client recognises the
// sender). Falls back to silent no-op when SMTP isn't configured —
// project updates must never fail because email infrastructure is
// flaky.
async function dispatchClientGalleryNotification(
  type: GalleryNotificationType,
  photographerId: string,
  payload: GalleryNotificationPayload,
): Promise<void> {
  try {
    const transporter = getRoleRoomEducationInquiryMailer();
    if (!transporter) return;
    if (!payload.clientEmail || !payload.clientEmail.includes('@')) return;
    const photographerEmail = await lookupPhotographerEmail(photographerId);
    const fromAddress =
      photographerEmail ||
      process.env.GMAIL_USER ||
      process.env.GOOGLE_WORKSPACE_EMAIL ||
      'noreply@creatorhubn.com';
    const photographerName = String(payload.details.photographerName ?? 'CreatorHub');
    const { subject, text, html } = buildGalleryNotificationEmail(type, payload);
    await transporter.sendMail({
      from: `${photographerName} <${fromAddress}>`,
      to: payload.clientEmail,
      replyTo: photographerEmail || undefined,
      subject,
      text,
      html,
    });
  } catch (err) {
    console.warn(`[client-gallery-notify] dispatch ${type} failed:`, err);
  }
}

