const toStorageGigabytes = (bytes: number): number =>
  Number((bytes / 1024 ** 3).toFixed(3));
const GOOGLE_CONTACTS_READ_SCOPES = [
  "https://www.googleapis.com/auth/contacts.readonly",
  "https://www.googleapis.com/auth/contacts",
] as const;
const GOOGLE_CONTACTS_WRITE_SCOPES = [
  "https://www.googleapis.com/auth/contacts",
] as const;
const GOOGLE_DRIVE_FOLDER_MIME = "application/vnd.google-apps.folder";
const GOOGLE_WORKSPACE_BACKUP_ROOT = path.join(
  os.tmpdir(),
  "creatorhub-google-workspace-backups",
);


const readGrantedGoogleScopes = (value: unknown): string[] => {
  if (Array.isArray(value)) {
    return [
      ...new Set(
        value.filter(
          (entry): entry is string =>
            typeof entry === "string" && entry.trim().length > 0,
        ),
      ),
    ];
  }
  if (typeof value === "string" && value.trim().length > 0) {
    return [
      ...new Set(
        value
          .split(/\s+/)
          .map((entry) => entry.trim())
          .filter(Boolean),
      ),
    ];
  }
  return [];
};

const hasAnyGrantedScope = (
  grantedScopes: string[],
  acceptableScopes: readonly string[],
): boolean => {
  const normalized = new Set(grantedScopes.map((scope) => scope.toLowerCase()));
  return acceptableScopes.some((scope) => normalized.has(scope.toLowerCase()));
};

const sanitizeBackupFileSegment = (
  value: string | null | undefined,
  fallback: string,
): string => {
  const normalized = readString(value) || fallback;
  const sanitized = normalized
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 64);
  return sanitized || fallback;
};

const getGoogleWorkspaceBackupDir = (userId: string) =>
  path.join(GOOGLE_WORKSPACE_BACKUP_ROOT, userId);
const getGoogleWorkspaceLatestBackupPath = (userId: string) =>
  path.join(getGoogleWorkspaceBackupDir(userId), "latest.json");
const getGoogleWorkspaceLatestBackupMetaPath = (userId: string) =>
  path.join(getGoogleWorkspaceBackupDir(userId), "latest-meta.json");

const ensureGoogleWorkspaceBackupDir = async (userId: string) => {
  const directory = getGoogleWorkspaceBackupDir(userId);
  await fs.mkdir(directory, { recursive: true });
  return directory;
};

async function buildGooglePhotosStatusSnapshot(): Promise<GooglePhotosStatusSnapshot> {
  try {
    const result = await pool.query(
      `SELECT COUNT(*)::int AS items, MAX(last_synced) AS last_synced
       FROM google_photos`,
    );

    const items = Number(result.rows[0]?.items || 0);
    const lastSynced = readOptionalIsoDate(result.rows[0]?.last_synced);
    if (items === 0) {
      return {
        connected: false,
        status: "disconnected",
        itemsSynced: 0,
        lastSynced: null,
      };
    }

    return {
      connected: true,
      status: "connected",
      itemsSynced: items,
      lastSynced,
    };
  } catch (error) {
    if (isMissingRelationError(error)) {
      return {
        connected: false,
        status: "unavailable",
        itemsSynced: 0,
        lastSynced: null,
      };
    }
    console.error("Google Photos status check failed:", error);
    return {
      connected: false,
      status: "error",
      itemsSynced: 0,
      lastSynced: null,
    };
  }
}

async function buildGoogleContactsStatusSnapshot(
  userId: string,
  preferredOauthApps: GoogleWorkspaceOauthApp[] = ["creatorhub", "role_room"],
): Promise<GoogleContactsStatusSnapshot> {
  await ensureGoogleWorkspaceConnectionsSchema(pool);

  const normalizedUserId = readString(userId) || "guest";
  if (normalizedUserId === "guest") {
    return {
      connected: false,
      status: "disconnected",
      readEnabled: false,
      writeEnabled: false,
      accountEmail: null,
      scopes: [],
      lastChecked: new Date().toISOString(),
      message: "Ingen bruker valgt for Google Contacts.",
    };
  }

  try {
    const result = await pool.query(
      `SELECT google_email, scopes, updated_at
       FROM role_room_google_connections
       WHERE connection_state = 'connected'
         AND (refresh_token_encrypted IS NOT NULL OR access_token_encrypted IS NOT NULL)
         AND user_id = $1
       ORDER BY CASE WHEN oauth_app = 'creatorhub' THEN 0 WHEN oauth_app = 'role_room' THEN 1 ELSE 2 END,
                last_used_at DESC NULLS LAST, updated_at DESC NULLS LAST, created_at DESC NULLS LAST
       LIMIT 1`,
      [normalizedUserId],
    );

    const row = (result.rows[0] ?? null) as Record<string, unknown> | null;
    if (!row) {
      return {
        connected: false,
        status: "disconnected",
        readEnabled: false,
        writeEnabled: false,
        accountEmail: null,
        scopes: [],
        lastChecked: new Date().toISOString(),
        message: "Google Workspace er ikke koblet til denne brukeren.",
      };
    }

    const scopes = readGrantedGoogleScopes(row.scopes);
    const readEnabled = hasAnyGrantedScope(scopes, GOOGLE_CONTACTS_READ_SCOPES);
    const writeEnabled = hasAnyGrantedScope(
      scopes,
      GOOGLE_CONTACTS_WRITE_SCOPES,
    );

    try {
      const authorized = await resolveRoleRoomGoogleConnection(
        pool,
        normalizedUserId,
        { preferredOauthApps },
      );
      return {
        connected: readEnabled,
        status: readEnabled ? "connected" : "missing_scope",
        readEnabled,
        writeEnabled,
        accountEmail:
          authorized.connection.googleEmail ||
          readString(row.google_email) ||
          null,
        scopes,
        lastChecked: new Date().toISOString(),
        message: readEnabled ? null : "Google-kontoen mangler Contacts-scope.",
      };
    } catch (error) {
      return {
        connected: false,
        status: "error",
        readEnabled,
        writeEnabled,
        accountEmail: readString(row.google_email) || null,
        scopes,
        lastChecked: new Date().toISOString(),
        message:
          error instanceof Error
            ? error.message
            : "Kunne ikke verifisere Google Contacts-tilkoblingen.",
      };
    }
  } catch (error) {
    console.error("Google Contacts status check failed:", error);
    return {
      connected: false,
      status: "error",
      readEnabled: false,
      writeEnabled: false,
      accountEmail: null,
      scopes: [],
      lastChecked: new Date().toISOString(),
      message:
        error instanceof Error
          ? error.message
          : "Kunne ikke lese Google Contacts-status.",
    };
  }
}

const ensureGoogleDriveBackupFolder = async (
  driveApi: ReturnType<typeof google.drive>,
): Promise<{ id: string; name: string; webViewLink: string | null }> => {
  const existing = await driveApi.files.list({
    q: [
      `mimeType = '${GOOGLE_DRIVE_FOLDER_MIME}'`,
      `name = 'CreatorHub Backups'`,
      "trashed = false",
    ].join(" and "),
    pageSize: 1,
    supportsAllDrives: true,
    includeItemsFromAllDrives: true,
    fields: "files(id,name,webViewLink)",
  });

  const existingFolder = Array.isArray(existing.data.files)
    ? existing.data.files[0]
    : null;
  const existingId = readString(existingFolder?.id);
  if (existingId) {
    return {
      id: existingId,
      name: readString(existingFolder?.name) || "CreatorHub Backups",
      webViewLink: readString(existingFolder?.webViewLink),
    };
  }

  const created = await driveApi.files.create({
    requestBody: {
      name: "CreatorHub Backups",
      mimeType: GOOGLE_DRIVE_FOLDER_MIME,
    },
    supportsAllDrives: true,
    fields: "id,name,webViewLink",
  });

  return {
    id: readString(created.data.id) || crypto.randomUUID(),
    name: readString(created.data.name) || "CreatorHub Backups",
    webViewLink: readString(created.data.webViewLink),
  };
};

const readGoogleWorkspaceBackupStatus = async (
  userId: string,
): Promise<GoogleWorkspaceBackupStatus> => {
  const metaPath = getGoogleWorkspaceLatestBackupMetaPath(userId);
  if (!existsSync(metaPath)) {
    return {
      available: false,
      lastBackup: null,
      fileName: null,
      driveFileId: null,
      driveWebViewLink: null,
      profession: null,
      projectId: null,
      projectName: null,
      customerId: null,
      customerName: null,
      companyName: null,
    };
  }

  try {
    const raw = await fs.readFile(metaPath, "utf8");
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    return {
      available: true,
      lastBackup: readOptionalIsoDate(parsed.createdAt),
      fileName: readString(parsed.fileName),
      driveFileId: readString(parsed.driveFileId),
      driveWebViewLink: readString(parsed.driveWebViewLink),
      profession: readString(parsed.profession),
      projectId: readString(parsed.projectId),
      projectName: readString(parsed.projectName),
      customerId: readString(parsed.customerId),
      customerName: readString(parsed.customerName),
      companyName: readString(parsed.companyName),
    };
  } catch (error) {
    console.error("Could not read Google Workspace backup status:", error);
    return {
      available: false,
      lastBackup: null,
      fileName: null,
      driveFileId: null,
      driveWebViewLink: null,
      profession: null,
      projectId: null,
      projectName: null,
      customerId: null,
      customerName: null,
      companyName: null,
    };
  }
};

async function buildGoogleWorkspaceStorageSnapshot(
  userId: string,
  preferredOauthApps: GoogleWorkspaceOauthApp[] = ["creatorhub", "role_room"],
): Promise<GoogleWorkspaceStorageSnapshot> {
  await ensureGoogleWorkspaceConnectionsSchema(pool);

  const normalizedUserId = readString(userId) || "guest";

  const [
    driveUsageResult,
    driveConnectionCountResult,
    driveConnectionDetailsResult,
    photosCountResult,
    emailCountResult,
    // Slice 9X.80 — også sjekk role_room_google_connections-state så badge
    // kan vise "Trenger oppmerksomhet" når Phase 3 markerte needs_reauth
    roleRoomConnectionStateResult,
  ] = await Promise.all([
    pool
      .query(
        `SELECT
           COALESCE(SUM(file_size), 0)::bigint AS total_bytes,
           COALESCE(SUM(CASE WHEN mime_type LIKE 'image/%' THEN file_size ELSE 0 END), 0)::bigint AS image_bytes
         FROM google_drive_files
         WHERE user_id = $1`,
        [normalizedUserId],
      )
      .catch(() => ({ rows: [{ total_bytes: 0, image_bytes: 0 }] })),
    pool
      .query(
        `SELECT COUNT(*)::int AS connections
         FROM google_drive_connections
         WHERE user_id = $1 AND connection_status = 'connected'`,
        [normalizedUserId],
      )
      .catch(() => ({ rows: [{ connections: 0 }] })),
    pool
      .query(
        `SELECT google_account_email, connection_status, sync_enabled, last_sync, updated_at
         FROM google_drive_connections
         WHERE user_id = $1
         ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
         LIMIT 1`,
        [normalizedUserId],
      )
      .catch(() => ({ rows: [] })),
    pool
      .query(`SELECT COUNT(*)::int AS photos FROM google_photos`)
      .catch(() => ({ rows: [{ photos: 0 }] })),
    pool
      .query(
        `SELECT COUNT(*)::int AS emails
         FROM project_emails
         WHERE user_id = $1`,
        [normalizedUserId],
      )
      .catch(() => ({ rows: [{ emails: 0 }] })),
    pool
      .query(
        `SELECT connection_state, last_error
         FROM role_room_google_connections
         WHERE user_id = $1
         ORDER BY updated_at DESC NULLS LAST
         LIMIT 1`,
        [normalizedUserId],
      )
      .catch(() => ({ rows: [] as Array<{ connection_state?: string; last_error?: string }> })),
  ]);

  const driveBytes = Number(driveUsageResult.rows[0]?.total_bytes || 0);
  const imageBytesFromDrive = Number(
    driveUsageResult.rows[0]?.image_bytes || 0,
  );
  const photosCount = Number(photosCountResult.rows[0]?.photos || 0);
  const estimatedPhotosBytes = photosCount * 4 * 1024 * 1024;
  const photosBytes = Math.max(imageBytesFromDrive, estimatedPhotosBytes);
  const emailCount = Number(emailCountResult.rows[0]?.emails || 0);
  const gmailBytes = emailCount * 75 * 1024;
  const connections = Number(
    driveConnectionCountResult.rows[0]?.connections || 0,
  );
  const connectionRow = (driveConnectionDetailsResult.rows[0] ?? {}) as Record<
    string,
    unknown
  >;

  const storageQuotaType: "personal" | "business" | "enterprise" =
    connections >= 3
      ? "enterprise"
      : connections >= 1
        ? "business"
        : "personal";

  let totalStorageGB =
    storageQuotaType === "enterprise"
      ? 2048
      : storageQuotaType === "business"
        ? 100
        : 15;
  let usedStorageGB = Number(
    ((driveBytes + photosBytes + gmailBytes) / 1024 ** 3).toFixed(3),
  );
  let driveUsageGB = toStorageGigabytes(driveBytes);
  let photosUsageGB = toStorageGigabytes(photosBytes);
  let gmailUsageGB = toStorageGigabytes(gmailBytes);
  let availableStorageGB = Math.max(
    0,
    Number((totalStorageGB - usedStorageGB).toFixed(3)),
  );
  let usagePercentage =
    totalStorageGB > 0
      ? Number(((usedStorageGB / totalStorageGB) * 100).toFixed(2))
      : 0;
  let googleDriveConnected = connections > 0;
  let driveSyncEnabled = Boolean(connectionRow.sync_enabled);
  let driveConnectionStatus =
    readString(connectionRow.connection_status) ||
    (googleDriveConnected ? "connected" : "disconnected");
  let driveAccountEmail =
    readString(connectionRow.google_account_email) || null;
  let lastDriveSyncAt = readOptionalIsoDate(
    connectionRow.last_sync ?? connectionRow.updated_at,
  );
  let dataSource: "live-drive" | "database-estimate" = "database-estimate";
  let workspaceWarning: string | null = null;

  // Slice 9X.80 — surface needs_reauth fra role_room_google_connections
  // (Phase 3 setter denne ved invalid_grant). Badge'en viser "Trenger
  // oppmerksomhet" + Re-koble-knapp basert på workspaceWarning.
  const roleRoomConnRow = (roleRoomConnectionStateResult.rows[0] ?? {}) as {
    connection_state?: string;
    last_error?: string;
  };
  if (roleRoomConnRow.connection_state === 'needs_reauth') {
    workspaceWarning = 'Google krever ny innlogging — klikk for å re-koble';
    // Tving connected=false så knappen sier "Aktiver Google-SSO" istedenfor "Forny SSO"
    googleDriveConnected = false;
  }

  if (normalizedUserId !== "guest") {
    try {
      const authorized = await resolveRoleRoomGoogleConnection(
        pool,
        normalizedUserId,
        { preferredOauthApps },
      );
      const driveApi = google.drive({
        version: "v3",
        auth: authorized.oauthClient,
      });
      const aboutResponse = await driveApi.about.get({
        fields:
          "storageQuota(limit,usage,usageInDrive,usageInDriveTrash),user(emailAddress)",
      });

      const quota = aboutResponse.data.storageQuota;
      const quotaLimitBytes = Number(quota?.limit ?? 0);
      const quotaUsageBytes = Number(quota?.usage ?? 0);
      const quotaUsageInDriveBytes = Number(quota?.usageInDrive ?? 0);
      const quotaUsageInDriveTrashBytes = Number(quota?.usageInDriveTrash ?? 0);
      const liveDriveUsageGB = toStorageGigabytes(
        quotaUsageInDriveBytes + quotaUsageInDriveTrashBytes,
      );

      if (quotaLimitBytes > 0) {
        totalStorageGB = toStorageGigabytes(quotaLimitBytes);
      }

      usedStorageGB =
        quotaUsageBytes >= 0
          ? toStorageGigabytes(quotaUsageBytes)
          : usedStorageGB;
      availableStorageGB = Math.max(
        0,
        Number((totalStorageGB - usedStorageGB).toFixed(3)),
      );
      usagePercentage =
        totalStorageGB > 0
          ? Number(((usedStorageGB / totalStorageGB) * 100).toFixed(2))
          : 0;

      const estimatedBreakdownTotal =
        liveDriveUsageGB + photosUsageGB + gmailUsageGB;
      if (estimatedBreakdownTotal > 0 && usedStorageGB > 0) {
        const scaleFactor = usedStorageGB / estimatedBreakdownTotal;
        driveUsageGB = Number((liveDriveUsageGB * scaleFactor).toFixed(3));
        photosUsageGB = Number((photosUsageGB * scaleFactor).toFixed(3));
        gmailUsageGB = Math.max(
          0,
          Number((usedStorageGB - driveUsageGB - photosUsageGB).toFixed(3)),
        );
      } else if (usedStorageGB > 0) {
        driveUsageGB = usedStorageGB;
        photosUsageGB = 0;
        gmailUsageGB = 0;
      }

      googleDriveConnected = true;
      driveSyncEnabled = Boolean(connectionRow.sync_enabled ?? true);
      driveConnectionStatus = driveSyncEnabled
        ? "connected"
        : driveConnectionStatus || "connected";
      driveAccountEmail =
        readString(aboutResponse.data.user?.emailAddress) ||
        authorized.connection.googleEmail ||
        driveAccountEmail;
      dataSource = "live-drive";
    } catch (error) {
      workspaceWarning =
        error instanceof Error
          ? error.message
          : "Kunne ikke hente live lagringsdata fra Google Drive.";
    }
  }

  return {
    totalStorageGB,
    usedStorageGB,
    availableStorageGB,
    usagePercentage,
    storageQuotaType,
    driveUsageGB,
    photosUsageGB,
    gmailUsageGB,
    lastUpdated: new Date().toISOString(),
    googleDriveConnected,
    driveSyncEnabled,
    driveConnectionStatus,
    driveAccountEmail,
    lastDriveSyncAt,
    dataSource,
    workspaceWarning,
  };
}

