app.post("/api/backup/create", async (req, res) => {
  try {
    const userId =
      readString(req.body?.userId) ||
      readString(req.headers["x-user-id"]) ||
      "guest";
    if (userId === "guest") {
      return res
        .status(400)
        .json({ error: "Bruker-ID kreves for å opprette backup." });
    }

    const profession = readString(req.body?.profession) || "general";
    const projectId = readString(req.body?.projectId);
    const projectName = readString(req.body?.projectName);
    const customerId = readString(req.body?.customerId);
    const customerName = readString(req.body?.customerName);
    const companyName = readString(req.body?.companyName);

    const preferredOauthApps = derivePreferredGoogleWorkspaceOauthApps(req);
    const storageSnapshot = await buildGoogleWorkspaceStorageSnapshot(
      userId,
      preferredOauthApps,
    );
    if (!storageSnapshot.googleDriveConnected) {
      return res.status(409).json({
        error:
          "Google Workspace må være koblet til før backup kan lagres i Google Drive.",
      });
    }

    const [contactsSnapshot, photosSnapshot, existingBackupStatus] =
      await Promise.all([
        buildGoogleContactsStatusSnapshot(userId, preferredOauthApps),
        buildGooglePhotosStatusSnapshot(),
        readGoogleWorkspaceBackupStatus(userId),
      ]);

    const backupCreatedAt = new Date().toISOString();
    const backupManifest = {
      version: 1,
      createdAt: backupCreatedAt,
      userId,
      profession,
      project: {
        projectId,
        projectName,
        customerId,
        customerName,
        companyName,
      },
      previousBackup: existingBackupStatus.available
        ? existingBackupStatus
        : null,
      workspace: {
        storage: storageSnapshot,
        contacts: contactsSnapshot,
        photos: photosSnapshot,
      },
    };

    const authorized = await resolveRoleRoomGoogleConnection(pool, userId, {
      preferredOauthApps,
    });
    const driveApi = google.drive({
      version: "v3",
      auth: authorized.oauthClient,
    });
    const backupFolder = await ensureGoogleDriveBackupFolder(driveApi);
    const timestampToken = backupCreatedAt.replace(/[:.]/g, "-");
    const professionToken = sanitizeBackupFileSegment(profession, "workspace");
    const projectToken = sanitizeBackupFileSegment(projectName, "general");
    const backupFileName = `${professionToken}-${projectToken}-backup-${timestampToken}.json`;
    const serializedManifest = JSON.stringify(backupManifest, null, 2);

    const driveFile = await driveApi.files.create({
      requestBody: {
        name: backupFileName,
        parents: [backupFolder.id],
        description: [
          "CreatorHub Google Workspace backup",
          projectName || null,
          customerName || companyName || null,
        ]
          .filter(Boolean)
          .join(" • "),
      },
      media: {
        mimeType: "application/json",
        body: Readable.from([serializedManifest]),
      },
      supportsAllDrives: true,
      fields: "id,name,webViewLink,modifiedTime,size",
    });

    const backupDirectory = await ensureGoogleWorkspaceBackupDir(userId);
    const latestPath = getGoogleWorkspaceLatestBackupPath(userId);
    const latestMetaPath = getGoogleWorkspaceLatestBackupMetaPath(userId);
    const versionedPath = path.join(backupDirectory, backupFileName);

    await Promise.all([
      fs.writeFile(versionedPath, serializedManifest, "utf8"),
      fs.writeFile(latestPath, serializedManifest, "utf8"),
      fs.writeFile(
        latestMetaPath,
        JSON.stringify(
          {
            createdAt: backupCreatedAt,
            fileName: backupFileName,
            driveFileId: readString(driveFile.data.id),
            driveWebViewLink: readString(driveFile.data.webViewLink),
            profession,
            projectId,
            projectName,
            customerId,
            customerName,
            companyName,
          },
          null,
          2,
        ),
        "utf8",
      ),
    ]);

    return res.status(201).json({
      success: true,
      createdAt: backupCreatedAt,
      fileName: backupFileName,
      localPath: versionedPath,
      driveFolderId: backupFolder.id,
      driveFolderName: backupFolder.name,
      driveFolderWebViewLink: backupFolder.webViewLink,
      driveFileId: readString(driveFile.data.id),
      driveFileWebViewLink: readString(driveFile.data.webViewLink),
      downloadUrl: `/api/backup/download/latest?userId=${encodeURIComponent(userId)}`,
    });
  } catch (error) {
    console.error("Error creating Google Workspace backup:", error);
    res.status(500).json({
      error:
        error instanceof Error
          ? error.message
          : "Could not create Google Workspace backup",
    });
  }
});

app.get("/api/backup/download/latest", async (req, res) => {
  try {
    const userId =
      readString(req.query.userId) ||
      readString(req.headers["x-user-id"]) ||
      "guest";
    if (userId === "guest") {
      return res
        .status(400)
        .json({ error: "Bruker-ID kreves for å laste ned backup." });
    }

    const latestPath = getGoogleWorkspaceLatestBackupPath(userId);
    const status = await readGoogleWorkspaceBackupStatus(userId);
    if (!existsSync(latestPath) || !status.available) {
      return res
        .status(404)
        .json({ error: "Fant ingen lagret backup for denne brukeren." });
    }

    const payload = await fs.readFile(latestPath, "utf8");
    const fileName =
      status.fileName || `creatorhub-google-workspace-backup-${userId}.json`;
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
    return res.send(payload);
  } catch (error) {
    console.error("Error downloading latest backup:", error);
    res.status(500).json({ error: "Could not download latest backup" });
  }
});


app.post("/api/platform/billing/checkout-session", async (req, res) => {
  try {
    await ensureCompatPlatformSubscriptionPlanOverridesLoaded();
    const body = isRecord(req.body) ? req.body : {};
    const email =
      compatHeaderString(body.email ?? body.userEmail ?? body.user_email) ||
      compatResolveUserEmail(req);
    const requestId =
      compatHeaderString(body.requestId ?? body.request_id) || null;
    const userId = resolveCompatPaymentUserScope(
      compatHeaderString(body.userId ?? body.user_id) || compatResolveUserId(req),
      requestId,
      email,
    );
    const profession = readString(body.profession);
    const paymentMethod = normalizeCompatPaymentMethod(
      body.paymentMethod ?? body.payment_method,
    );
    const planId = normalizeBillingPlanId(body.planId ?? body.plan_id);
    const plan = getCompatPlatformSubscriptionPlan(planId);
    const billingCycle = normalizeCreatorHubBillingCycle(
      body.billingCycle ?? body.billing_cycle,
    );

    if (!plan || !plan.isActive) {
      return res.status(400).json({
        error: "Velg en gyldig abonnementsplan før du fortsetter.",
      });
    }

    if (plan.contactSalesOnly) {
      return res.status(400).json({
        error:
          "Enterprise settes opp sammen med CreatorHub. Kontakt hello@creatorhubn.com for demo og tilbud.",
        contactSales: true,
        email: "hello@creatorhubn.com",
      });
    }

    if (paymentMethod !== "stripe") {
      return res.status(400).json({
        error: "CreatorHub Checkout støtter foreløpig bare Stripe.",
      });
    }

    if (plan.price <= 0) {
      const createdAt = new Date().toISOString();
      const record: CompatPaymentStatusRecord = {
        id: `pay_${crypto.randomUUID()}`,
        transactionId: `free_${crypto.randomUUID()}`,
        userId,
        email,
        requestId,
        planId: plan.id,
        planName: plan.displayName,
        amountMinor: 0,
        amountMajor: 0,
        currency: plan.currency,
        paymentMethod: "stripe",
        status: "completed",
        createdAt,
        completedAt: createdAt,
        provider: "compat",
        metadata: {
          profession,
          requestId,
          flow: "creatorhub_free_plan",
        },
        receiptSentAt: null,
        membershipCard: null,
      };

      await recordCompatPaymentCompletion(record);

      return res.status(200).json({
        success: true,
        alreadyPaid: true,
        freePlan: true,
        planId: plan.id,
        planName: plan.displayName,
        amount: record.amountMinor,
        currency: record.currency,
        transactionId: record.transactionId,
        paymentCompleted: true,
      });
    }

    const stripe = getCreatorHubStripeClient();
    if (!stripe) {
      return res.status(503).json({
        error:
          "Stripe Checkout er ikke konfigurert for CreatorHub. Legg inn STRIPE_SECRET_KEY før du fortsetter.",
      });
    }

    const browserOrigin = normalizeCreatorHubBrowserOrigin(body.browserOrigin);
    const returnPath =
      typeof body.returnPath === "string"
        ? body.returnPath
        : "/subscription-selection";
    const successUrl = buildCreatorHubCheckoutReturnUrl({
      browserOrigin,
      returnPath,
      status: "success",
      includeSessionId: true,
    });
    const cancelUrl = buildCreatorHubCheckoutReturnUrl({
      browserOrigin,
      returnPath,
      status: "cancel",
      includeSessionId: false,
    });

    const configuredPriceId = hasCompatPlatformSubscriptionPlanPriceOverride(
      plan.id,
      billingCycle,
    )
      ? null
      : getCreatorHubStripePriceId(plan.id, billingCycle);
    const amountMajor = getCreatorHubPlanAmountMajor(plan, billingCycle);
    const amountMinor = Math.round(amountMajor * 100);
    const session = await stripe.checkout.sessions.create({
      mode: "subscription",
      success_url: successUrl,
      cancel_url: cancelUrl,
      customer_email: email || undefined,
      billing_address_collection: "auto",
      allow_promotion_codes: true,
      locale: "nb",
      client_reference_id: [
        plan.id,
        billingCycle,
        userId,
        requestId || email || "creatorhub",
      ]
        .filter(Boolean)
        .join(":"),
      line_items: [
        configuredPriceId
          ? {
              quantity: 1,
              price: configuredPriceId,
            }
          : {
              quantity: 1,
              price_data: {
                currency: plan.currency.toLowerCase(),
                unit_amount: amountMinor,
                recurring: {
                  interval: billingCycle === "yearly" ? "year" : "month",
                },
                product_data: {
                  name: `CreatorHub — ${plan.displayName}`,
                  description: plan.description,
                },
              },
            },
      ],
      metadata: {
        ch_user_id: userId,
        ch_email: email || "",
        ch_request_id: requestId || "",
        ch_profession: profession || "",
        ch_plan_id: plan.id,
        ch_plan_name: plan.displayName,
        ch_billing_cycle: billingCycle,
        ch_amount_minor: String(amountMinor),
        ch_currency: plan.currency,
      },
      subscription_data: {
        metadata: {
          ch_user_id: userId,
          ch_email: email || "",
          ch_request_id: requestId || "",
          ch_profession: profession || "",
          ch_plan_id: plan.id,
          ch_plan_name: plan.displayName,
          ch_billing_cycle: billingCycle,
          ch_amount_minor: String(amountMinor),
          ch_currency: plan.currency,
        },
      },
    });

    if (!session.url) {
      throw new Error("Stripe Checkout returnerte ingen checkout-url.");
    }

    const nowIso = new Date().toISOString();
    await writeCreatorHubStripeCheckoutSessionRecord({
      sessionId: session.id,
      userId,
      email,
      requestId,
      profession,
      planId: plan.id,
      planName: plan.displayName,
      billingCycle,
      amountMinor,
      amountMajor: Number(amountMajor.toFixed(2)),
      currency: plan.currency,
      paymentCompleted: false,
      checkoutStatus: "created",
      paymentTimestamp: null,
      transactionId: null,
      stripeSubscriptionId: null,
      stripeCustomerId: getStripeCheckoutSessionCustomerId(session) || null,
      createdAt: nowIso,
      updatedAt: nowIso,
    });

    return res.status(201).json({
      success: true,
      checkoutUrl: session.url,
      sessionId: session.id,
      planId: plan.id,
      planName: plan.displayName,
      amount: amountMinor,
      currency: plan.currency,
      billingCycle,
      paymentMethod: "stripe",
    });
  } catch (error) {
    console.error("Error creating CreatorHub Stripe checkout session:", error);
    return res.status(500).json({
      error: "Kunne ikke starte Stripe Checkout for CreatorHub.",
    });
  }
});

app.get("/api/platform/billing/session-status", async (req, res) => {
  try {
    const sessionId = normalizeMailConfigValue(req.query?.sessionId);
    if (!sessionId) {
      return res.status(400).json({
        error: "sessionId er påkrevd.",
      });
    }

    const stripe = getCreatorHubStripeClient();
    if (!stripe) {
      return res.status(503).json({
        error:
          "Stripe Checkout er ikke konfigurert for CreatorHub. Legg inn STRIPE_SECRET_KEY før du fortsetter.",
      });
    }

    const session = await stripe.checkout.sessions.retrieve(sessionId, {
      expand: ["subscription"],
    });
    const syncedRecord =
      (await syncCreatorHubStripeCheckoutSession(session)) ||
      (await readCreatorHubStripeCheckoutSessionRecord(sessionId));
    const createdAt =
      syncedRecord?.createdAt ||
      new Date((session.created || Math.floor(Date.now() / 1000)) * 1000).toISOString();
    const status = syncedRecord?.paymentCompleted
      ? "completed"
      : syncedRecord?.checkoutStatus === "payment_failed" ||
          syncedRecord?.checkoutStatus === "expired"
        ? "failed"
        : "pending";

    return res.json({
      success: true,
      id: syncedRecord?.sessionId || session.id,
      sessionId,
      status,
      amount: syncedRecord?.amountMinor || 0,
      currency: syncedRecord?.currency || "NOK",
      paymentMethod: "stripe",
      transactionId:
        syncedRecord?.transactionId || getStripeCheckoutSessionTransactionId(session),
      planId: syncedRecord?.planId || null,
      planName: syncedRecord?.planName || null,
      billingCycle: syncedRecord?.billingCycle || "monthly",
      createdAt,
      completedAt: syncedRecord?.paymentTimestamp || null,
      paymentCompleted: Boolean(syncedRecord?.paymentCompleted),
      checkoutStatus: session.status,
      paymentStatus: session.payment_status,
    });
  } catch (error) {
    console.error("Error reading CreatorHub Stripe checkout session:", error);
    return res.status(500).json({
      error: "Kunne ikke lese Stripe Checkout-status for CreatorHub.",
    });
  }
});



function canAccessCompatPaymentDocument(
  req: express.Request,
  record: CompatPaymentStatusRecord,
) {
  const session = getActiveSessionFromRequest(req);
  if (session) {
    const normalizedRole = String(session.role || "").trim().toLowerCase();
    if (ADMIN_SESSION_ROLES.has(normalizedRole)) {
      return true;
    }
  }

  const requestUserId = compatResolveUserId(req);
  const requestEmail =
    normalizeMailConfigValue(compatResolveUserEmail(req)).toLowerCase() || null;
  const recordEmail =
    normalizeMailConfigValue(record.email).toLowerCase() || null;

  return Boolean(
    (requestUserId && record.userId && requestUserId === record.userId) ||
      (requestEmail && recordEmail && requestEmail === recordEmail),
  );
}

function formatCompatPaymentDocumentAmount(amountMajor: number, currency: string) {
  try {
    return new Intl.NumberFormat("nb-NO", {
      style: "currency",
      currency: currency || "NOK",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }).format(amountMajor);
  } catch {
    return `${amountMajor.toFixed(2)} ${currency || "NOK"}`;
  }
}

function formatCompatPaymentDocumentDate(value: string | null | undefined) {
  if (!value) {
    return "Ikke tilgjengelig";
  }
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return "Ikke tilgjengelig";
  }
  return parsed.toLocaleString("nb-NO");
}

function buildCompatPaymentDocumentHtml(input: {
  title: string;
  subtitle: string;
  record: CompatPaymentStatusRecord;
  historyEntry: CompatPaymentHistoryItem | null;
  accountingReady?: boolean;
}) {
  const { title, subtitle, record, historyEntry, accountingReady = false } = input;
  const amountLabel = formatCompatPaymentDocumentAmount(
    record.amountMajor,
    record.currency,
  );
  const statusLabel =
    record.status === "completed"
      ? "Betalt"
      : record.status === "refunded"
        ? "Refundert"
        : record.status === "failed"
          ? "Betaling feilet"
          : "Venter betaling";

  return `<!doctype html>
<html lang="nb">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>${escapeHtml(title)}</title>
    <style>
      body{font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f6f2ea;color:#111827;margin:0;padding:32px}
      .sheet{max-width:820px;margin:0 auto;background:#fff;border:1px solid #e5e7eb;border-radius:24px;overflow:hidden;box-shadow:0 24px 60px rgba(15,23,42,.08)}
      .hero{padding:32px;background:linear-gradient(135deg,#18130f 0%,#2b1d16 55%,#1f1722 100%);color:#fff}
      .label{font-size:12px;letter-spacing:.18em;text-transform:uppercase;color:#ffba6c;font-weight:700;margin:0 0 10px}
      h1{margin:0;font-size:32px;line-height:1.1}
      .sub{margin:12px 0 0;color:rgba(255,255,255,.76);font-size:16px;line-height:1.6}
      .body{padding:28px}
      .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}
      .card{border:1px solid #e5e7eb;border-radius:18px;padding:18px;background:#fff}
      .k{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:#64748b;font-weight:700;margin:0 0 8px}
      .v{font-size:18px;font-weight:700;color:#0f172a;margin:0}
      .muted{margin:8px 0 0;color:#475569;font-size:14px;line-height:1.6}
      .footer{padding:0 28px 28px;color:#64748b;font-size:13px}
    </style>
  </head>
  <body>
    <div class="sheet">
      <div class="hero">
        <p class="label">CreatorHub betaling</p>
        <h1>${escapeHtml(title)}</h1>
        <p class="sub">${escapeHtml(subtitle)}</p>
      </div>
      <div class="body">
        <div class="grid">
          <div class="card">
            <p class="k">Plan</p>
            <p class="v">${escapeHtml(record.planName || "CreatorHub-abonnement")}</p>
            <p class="muted">Transaksjon ${escapeHtml(record.transactionId || record.id)}</p>
          </div>
          <div class="card">
            <p class="k">Beløp</p>
            <p class="v">${escapeHtml(amountLabel)}</p>
            <p class="muted">Betalingsmetode: ${escapeHtml(record.paymentMethod)}</p>
          </div>
          <div class="card">
            <p class="k">Status</p>
            <p class="v">${escapeHtml(statusLabel)}</p>
            <p class="muted">Registrert ${escapeHtml(formatCompatPaymentDocumentDate(record.completedAt || record.createdAt))}</p>
          </div>
          <div class="card">
            <p class="k">Tilgang / periode</p>
            <p class="v">${escapeHtml(formatCompatPaymentDocumentDate(historyEntry?.currentPeriodEnd || null))}</p>
            <p class="muted">Startet ${escapeHtml(formatCompatPaymentDocumentDate(historyEntry?.currentPeriodStart || record.createdAt))}</p>
          </div>
        </div>
        <div class="card" style="margin-top:16px">
          <p class="k">Regnskapsstatus</p>
          <p class="v">${accountingReady ? "Klar for regnskap" : "Kun kjøpskvittering"}</p>
          <p class="muted">${
            accountingReady
              ? "Kjøpet er registrert videre og kan brukes som grunnlag for Fiken eller Tripletex."
              : "Kjøpet har kvittering i historikken. Faktura eller bokføringsbilag kommer når regnskapsintegrasjonen er aktiv."
          }</p>
        </div>
      </div>
      <div class="footer">
        Dette dokumentet er generert fra betalingshistorikken i CreatorHub.
      </div>
    </div>
  </body>
</html>`;
}

