async function getCompatUiPreferences(
  userId: string,
): Promise<Record<string, unknown>> {
  const existing = compatUiPreferencesStore.get(userId);
  if (existing) return existing;

  const dbEntry = await compatStoreGet<Record<string, unknown>>(
    dbCompatUiPreferencesKey(userId),
  );
  if (dbEntry && typeof dbEntry === "object") {
    compatUiPreferencesStore.set(userId, dbEntry);
    return dbEntry;
  }

  const defaults: Record<string, unknown> = {
    i18n_language: "nb",
    theme_config: {
      mode: "light",
      primaryColor: "#ff8c00",
      secondaryColor: "#9333ea",
    },
    chat_widget: {
      size: { width: 360, height: 520 },
      position: { x: 24, y: 24 },
    },
    autoRedirectToDashboard: false,
    updatedAt: new Date().toISOString(),
  };
  compatUiPreferencesStore.set(userId, defaults);
  await compatStoreSet(dbCompatUiPreferencesKey(userId), defaults);
  return defaults;
}



const compatUserPreferenceKey = (sessionId: string, profession: string) =>
  `${sessionId}::${profession}`;

async function getCompatUserPreference(
  sessionId: string,
  profession: string,
): Promise<Record<string, unknown>> {
  const key = compatUserPreferenceKey(sessionId, profession);
  const existing = compatUserPreferencesStore.get(key);
  if (existing) return existing;

  const dbEntry = await compatStoreGet<Record<string, unknown>>(
    dbCompatUserPreferencesKey(sessionId, profession),
  );
  if (dbEntry && typeof dbEntry === "object") {
    compatUserPreferencesStore.set(key, dbEntry);
    return dbEntry;
  }

  const fallback = {
    sessionId,
    profession,
    hiddenActions: [],
    speedDialOrder: [],
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  compatUserPreferencesStore.set(key, fallback);
  await compatStoreSet(
    dbCompatUserPreferencesKey(sessionId, profession),
    fallback,
  );
  return fallback;
}


// User KV store with persistent in-memory values (session-scoped by userId + key)
function collectCompatUserKvFromMemory(
  userId: string,
): Record<string, unknown> {
  const prefix = `${userId}::`;
  const data: Record<string, unknown> = {};
  for (const [scopedKey, entry] of compatUserKvStore.entries()) {
    if (!scopedKey.startsWith(prefix)) continue;
    const key = scopedKey.slice(prefix.length);
    data[key] = entry.value;
  }
  return data;
}

function readCompatUserKvParamKey(rawValue: unknown): string | null {
  const rawKey = readString(rawValue);
  if (!rawKey) return null;
  try {
    return decodeURIComponent(rawKey);
  } catch {
    return rawKey;
  }
}

function isProtectedAcademyKvKey(rawKey: unknown): boolean {
  const normalizedKey = readString(rawKey)?.trim().toLowerCase();
  return Boolean(normalizedKey && normalizedKey.startsWith("academy"));
}

function resolveUserKvScope(req: express.Request): {
  userId: string;
  authenticated: boolean;
} {
  const session = getActiveSessionFromRequest(req);
  if (session?.userId) {
    return {
      userId: session.userId,
      authenticated: true,
    };
  }

  return {
    userId: "guest",
    authenticated: false,
  };
}





