async function getCompatUserProjectTypes(userId: string): Promise<
  Array<{
    id: number;
    userId: number;
    name: string;
    icon: string;
    category: string;
    description: string;
    usageCount: number;
    isGlobal: boolean;
    isTrending: boolean;
    createdAt: string;
    updatedAt: string;
  }>
> {
  const existing = compatProjectTypesStore.get(userId);
  if (existing) return existing;

  const dbEntry = await compatStoreGet<
    Array<{
      id: number;
      userId: number;
      name: string;
      icon: string;
      category: string;
      description: string;
      usageCount: number;
      isGlobal: boolean;
      isTrending: boolean;
      createdAt: string;
      updatedAt: string;
    }>
  >(dbCompatProjectTypesKey(userId));
  if (Array.isArray(dbEntry)) {
    compatProjectTypesStore.set(userId, dbEntry);
    return dbEntry;
  }

  const seed = seedFromString(userId);
  const defaults = getCompatDefaultProjectTypes().map((entry, idx) => ({
    ...entry,
    id: entry.id + (idx + 1) * 1000,
    userId: Number.isFinite(Number(userId)) ? Number(userId) : 0,
    isGlobal: false,
    isTrending: idx === 0,
    usageCount: seed % (idx + 4),
  }));
  compatProjectTypesStore.set(userId, defaults);
  await compatStoreSet(dbCompatProjectTypesKey(userId), defaults);
  return defaults;
}

