function parseRoleRoomCommercialAccessSnapshot(
  value: unknown,
): RoleRoomCommercialAccessSnapshot | null {
  if (!value) {
    return null;
  }

  let parsed: unknown = value;
  if (typeof value === "string") {
    const trimmed = value.trim();
    if (!trimmed.startsWith("{")) {
      return null;
    }
    try {
      parsed = JSON.parse(trimmed);
    } catch {
      return null;
    }
  }

  if (!parsed || typeof parsed !== "object") {
    return null;
  }

  const record = parsed as Record<string, unknown>;
  if (toAdminString(record.kind) !== "role_room_commercial_access") {
    return null;
  }

  const members = Array.isArray(record.members)
    ? record.members
        .map((entry) => {
          if (!entry || typeof entry !== "object") {
            return null;
          }
          const memberRecord = entry as Record<string, unknown>;
          const email = toAdminString(memberRecord.email)?.trim().toLowerCase() || "";
          if (!email) {
            return null;
          }

          return {
            name: toAdminString(memberRecord.name) || email,
            email,
            roleId: toAdminString(memberRecord.roleId) || "",
            roleLabel: toAdminString(memberRecord.roleLabel),
            isLeader: memberRecord.isLeader === true,
          };
        })
        .filter(
          (entry): entry is RoleRoomCommercialAccessMemberSnapshot =>
            Boolean(entry),
        )
    : [];

  return {
    kind: "role_room_commercial_access",
    persona: toAdminString(record.persona),
    personaLabel: toAdminString(record.personaLabel),
    subscriptionType: toAdminString(record.subscriptionType),
    subscriptionLabel: toAdminString(record.subscriptionLabel),
    billingStatus:
      record.billingStatus === "pending_payment" ||
      record.billingStatus === "active" ||
      record.billingStatus === "payment_failed"
        ? record.billingStatus
        : null,
    companyName: toAdminString(record.companyName),
    organizationNumber: toAdminString(record.organizationNumber),
    teamLeadName: toAdminString(record.teamLeadName),
    teamLeadEmail: toAdminString(record.teamLeadEmail)?.trim().toLowerCase() || null,
    teamSize: readNumber(record.teamSize),
    seatPriceExVat: readNumber(record.seatPriceExVat),
    monthlyTotalExVat: readNumber(record.monthlyTotalExVat),
    taxMode: toAdminString(record.taxMode),
    stripeSubscriptionId: toAdminString(record.stripeSubscriptionId),
    stripeCustomerId: toAdminString(record.stripeCustomerId),
    latestInvoiceId: toAdminString(record.latestInvoiceId),
    latestInvoiceStatus: toAdminString(record.latestInvoiceStatus),
    paymentFailedAt: toAdminString(record.paymentFailedAt),
    paymentFailureMessage: toAdminString(record.paymentFailureMessage),
    members,
    memberName: toAdminString(record.memberName),
    memberEmail: toAdminString(record.memberEmail)?.trim().toLowerCase() || null,
    memberRoleId: toAdminString(record.memberRoleId),
    memberRoleLabel: toAdminString(record.memberRoleLabel),
    memberIsLeader: record.memberIsLeader === true,
    paymentPendingSince: toAdminString(record.paymentPendingSince),
    paymentReminderCount: Math.max(0, readNumber(record.paymentReminderCount) || 0),
    paymentReminderLastSentAt: toAdminString(record.paymentReminderLastSentAt),
    paymentReminderProvider: toAdminString(record.paymentReminderProvider),
    paymentReminderMessageId: toAdminString(record.paymentReminderMessageId),
    activationStatus:
      record.activationStatus === "pending_approval" ||
      record.activationStatus === "approved"
        ? record.activationStatus
        : null,
    activationTokenHash: toAdminString(record.activationTokenHash),
    activationTokenExpiresAt: toAdminString(record.activationTokenExpiresAt),
    activationApprovedAt: toAdminString(record.activationApprovedAt),
    activationEmailSentAt: toAdminString(record.activationEmailSentAt),
    activationEmailProvider: toAdminString(record.activationEmailProvider),
    activationEmailMessageId: toAdminString(record.activationEmailMessageId),
    activationReminderCount:
      Math.max(0, readNumber(record.activationReminderCount) || 0),
    activationReminderLastSentAt: toAdminString(
      record.activationReminderLastSentAt,
    ),
    activationReminderProvider: toAdminString(record.activationReminderProvider),
    activationReminderMessageId: toAdminString(
      record.activationReminderMessageId,
    ),
  };
}

async function listAdminUsersSnapshot(): Promise<Record<string, unknown>[]> {
  const inviteTableExists = await hasTable("invite_requests");
  const inviteColumns = inviteTableExists
    ? await getTableColumns("invite_requests")
    : null;
  const inviteSelects = inviteTableExists
    ? [
        "id::text AS id",
        "email",
        inviteColumns?.has("first_name")
          ? "first_name"
          : "NULL::text AS first_name",
        inviteColumns?.has("last_name")
          ? "last_name"
          : "NULL::text AS last_name",
        inviteColumns?.has("profession")
          ? "profession"
          : "NULL::text AS profession",
        inviteColumns?.has("company_name")
          ? "company_name"
          : "NULL::text AS company_name",
        inviteColumns?.has("organization_number")
          ? "organization_number"
          : "NULL::text AS organization_number",
        inviteColumns?.has("status") ? "status" : "NULL::text AS status",
        inviteColumns?.has("message")
          ? "message"
          : "NULL::text AS message",
        inviteColumns?.has("source") ? "source" : "NULL::text AS source",
        inviteColumns?.has("created_at")
          ? "created_at"
          : "NOW() AS created_at",
        inviteColumns?.has("updated_at")
          ? "updated_at"
          : "NOW() AS updated_at",
        inviteColumns?.has("processed_at")
          ? "processed_at"
          : "NULL::timestamp AS processed_at",
        inviteColumns?.has("processed_by")
          ? "processed_by"
          : "NULL::text AS processed_by",
        inviteColumns?.has("user_journey_status")
          ? "user_journey_status"
          : "NULL::text AS user_journey_status",
        inviteColumns?.has("registered_user_id")
          ? "registered_user_id"
          : "NULL::text AS registered_user_id",
        inviteColumns?.has("payment_completed")
          ? "payment_completed"
          : "NULL::boolean AS payment_completed",
        inviteColumns?.has("selected_plan")
          ? "selected_plan"
          : "NULL::text AS selected_plan",
        inviteColumns?.has("plan_name")
          ? "plan_name"
          : "NULL::text AS plan_name",
        inviteColumns?.has("plan_price")
          ? "plan_price"
          : "NULL::numeric AS plan_price",
        inviteColumns?.has("payment_amount")
          ? "payment_amount"
          : "NULL::numeric AS payment_amount",
        inviteColumns?.has("payment_timestamp")
          ? "payment_timestamp"
          : "NULL::timestamp AS payment_timestamp",
      ]
    : [];
  const inviteRows =
    inviteTableExists && inviteSelects.length > 0
      ? (
          await pool.query(
            `SELECT ${inviteSelects.join(", ")}
             FROM invite_requests
             ORDER BY created_at DESC, email ASC`,
          )
        ).rows
      : [];

  const usersTableExists = await hasTable("users");
  const userColumns = usersTableExists ? await getTableColumns("users") : null;
  const accountSelects = usersTableExists
    ? [
        "id::text AS id",
        "email",
        userColumns?.has("username") ? "username" : "NULL::text AS username",
        userColumns?.has("first_name")
          ? "first_name"
          : "NULL::text AS first_name",
        userColumns?.has("last_name") ? "last_name" : "NULL::text AS last_name",
        userColumns?.has("role") ? "role" : "NULL::text AS role",
        userColumns?.has("profession")
          ? "profession"
          : "NULL::text AS profession",
        userColumns?.has("company_name")
          ? "company_name"
          : "NULL::text AS company_name",
        userColumns?.has("organization_number")
          ? "organization_number"
          : "NULL::text AS organization_number",
        userColumns?.has("is_active")
          ? "is_active"
          : "NULL::boolean AS is_active",
        userColumns?.has("profile_image_url")
          ? "profile_image_url"
          : "NULL::text AS profile_image_url",
        userColumns?.has("created_at")
          ? "created_at"
          : "NOW() AS created_at",
        userColumns?.has("updated_at")
          ? "updated_at"
          : "NOW() AS updated_at",
      ]
    : [];
  const accountRows =
    usersTableExists && accountSelects.length > 0
      ? (
          await pool.query(
            `SELECT ${accountSelects.join(", ")}
             FROM users
             ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST, email ASC`,
          )
        ).rows
      : [];

  const accountById = new Map(
    accountRows.map((row) => [String(row.id), row as Record<string, unknown>]),
  );
  const accountByEmail = new Map(
    accountRows.map((row) => [
      String(row.email || "").trim().toLowerCase(),
      row as Record<string, unknown>,
    ]),
  );
  const matchedAccountIds = new Set<string>();
  const merged: Record<string, unknown>[] = [];

  for (const inviteRow of inviteRows as Record<string, unknown>[]) {
    const email = String(inviteRow.email || "").trim().toLowerCase();
    const roleRoomAccess =
      parseRoleRoomCommercialAccessSnapshot(inviteRow.message) || null;
    const roleRoomMember =
      roleRoomAccess?.members.find((member) => member.email === email) || null;
    const accountUserId = toAdminString(inviteRow.registered_user_id);
    const matchedAccount =
      (accountUserId ? accountById.get(accountUserId) : null) ||
      accountByEmail.get(email) ||
      null;

    if (matchedAccount?.id) {
      matchedAccountIds.add(String(matchedAccount.id));
    }

    const roleId = normalizeAdminRoleId(
      matchedAccount?.role || inferAdminRoleFromProfession(inviteRow.profession),
    );
    const roleEntry = buildAdminRoleEntry(roleId);
    const accessProfile = buildAdminAccessProfile(roleId, roleEntry.permissions);
    const approvedByUserId = toAdminString(inviteRow.processed_by);
    const approvedByAccount = approvedByUserId
      ? accountById.get(approvedByUserId)
      : null;

    merged.push({
      id: String(matchedAccount?.id || inviteRow.id),
      inviteRequestId: String(inviteRow.id),
      accountUserId: matchedAccount?.id
        ? String(matchedAccount.id)
        : accountUserId,
      canImpersonate: Boolean(matchedAccount?.id || accountUserId),
      email: toAdminString(matchedAccount?.email) || String(inviteRow.email || ""),
      firstName:
        toAdminString(matchedAccount?.first_name) ||
        toAdminString(inviteRow.first_name) ||
        "",
      lastName:
        toAdminString(matchedAccount?.last_name) ||
        toAdminString(inviteRow.last_name) ||
        "",
      profileImageUrl: toAdminString(matchedAccount?.profile_image_url),
      createdAt: matchedAccount?.created_at || inviteRow.created_at || null,
      updatedAt: matchedAccount?.updated_at || inviteRow.updated_at || null,
      approvedAt: inviteRow.processed_at || null,
      lastLoginAt: matchedAccount?.updated_at || inviteRow.updated_at || null,
      profession:
        toAdminString(matchedAccount?.profession) ||
        toAdminString(inviteRow.profession),
      businessName:
        toAdminString(matchedAccount?.company_name) ||
        toAdminString(inviteRow.company_name),
      companyName:
        toAdminString(matchedAccount?.company_name) ||
        toAdminString(inviteRow.company_name),
      organizationNumber:
        toAdminString(matchedAccount?.organization_number) ||
        toAdminString(inviteRow.organization_number),
      role: roleId,
      roleLabel: roleEntry.name,
      permissions: roleEntry.permissions,
      accessScope: accessProfile.scopeId,
      accessScopeLabel: accessProfile.scopeLabel,
      accessDescription: accessProfile.description,
      accessSortOrder: accessProfile.sortOrder,
      isPlatformAdmin: accessProfile.isPlatformAdmin,
      isAcademyAdmin: accessProfile.isAcademyAdmin,
      isActive:
        typeof matchedAccount?.is_active === "boolean"
          ? Boolean(matchedAccount.is_active)
          : String(inviteRow.status || "").toLowerCase() === "approved",
      status: toAdminString(inviteRow.status) || "approved",
      onboardingStatus: toAdminString(inviteRow.user_journey_status),
      paymentCompleted: Boolean(inviteRow.payment_completed),
      selectedPlan: toAdminString(inviteRow.selected_plan),
      planName: toAdminString(inviteRow.plan_name),
      planPrice:
        inviteRow.plan_price != null ? Number(inviteRow.plan_price) : null,
      paymentAmount:
        inviteRow.payment_amount != null
          ? Number(inviteRow.payment_amount)
          : null,
      paymentTimestamp: inviteRow.payment_timestamp || null,
      source: toAdminString(inviteRow.source),
      roleRoomAccess:
        roleRoomAccess
          ? {
              ...roleRoomAccess,
              isTeamLeader: Boolean(
                roleRoomMember?.isLeader ||
                  (roleRoomAccess.teamLeadEmail &&
                    roleRoomAccess.teamLeadEmail === email),
              ),
              memberRoleId:
                roleRoomMember?.roleId || toAdminString(inviteRow.profession),
              memberRoleLabel:
                roleRoomMember?.roleLabel ||
                roleRoomMember?.roleId ||
                toAdminString(inviteRow.profession),
            }
          : null,
      approvedByUserId,
      approvedBy: formatAdminUserIdentity(approvedByAccount) || approvedByUserId,
    });
  }

  for (const accountRow of accountRows as Record<string, unknown>[]) {
    const accountId = String(accountRow.id);
    if (matchedAccountIds.has(accountId)) continue;

    const roleId = normalizeAdminRoleId(
      accountRow.role || inferAdminRoleFromProfession(accountRow.profession),
    );
    const roleEntry = buildAdminRoleEntry(roleId);
    const accessProfile = buildAdminAccessProfile(roleId, roleEntry.permissions);

    merged.push({
      id: accountId,
      inviteRequestId: null,
      accountUserId: accountId,
      canImpersonate: true,
      email: toAdminString(accountRow.email) || "",
      firstName: toAdminString(accountRow.first_name) || "",
      lastName: toAdminString(accountRow.last_name) || "",
      profileImageUrl: toAdminString(accountRow.profile_image_url),
      createdAt: accountRow.created_at || null,
      updatedAt: accountRow.updated_at || null,
      approvedAt: null,
      lastLoginAt: accountRow.updated_at || null,
      profession: toAdminString(accountRow.profession),
      businessName: toAdminString(accountRow.company_name),
      companyName: toAdminString(accountRow.company_name),
      organizationNumber: toAdminString(accountRow.organization_number),
      role: roleId,
      roleLabel: roleEntry.name,
      permissions: roleEntry.permissions,
      accessScope: accessProfile.scopeId,
      accessScopeLabel: accessProfile.scopeLabel,
      accessDescription: accessProfile.description,
      accessSortOrder: accessProfile.sortOrder,
      isPlatformAdmin: accessProfile.isPlatformAdmin,
      isAcademyAdmin: accessProfile.isAcademyAdmin,
      isActive:
        typeof accountRow.is_active === "boolean"
          ? Boolean(accountRow.is_active)
          : true,
      status:
        typeof accountRow.is_active === "boolean" && !accountRow.is_active
          ? "inactive"
          : "approved",
      onboardingStatus: null,
      paymentCompleted: false,
      selectedPlan: null,
      planName: null,
    });
  }

  return merged.sort(sortAdminUsersByRecency);
}

async function findAdminInviteRequest(
  identifier: string,
  emailHint?: string | null,
): Promise<Record<string, unknown> | null> {
  if (!(await hasTable("invite_requests"))) return null;

  const inviteResult = await pool.query(
    `SELECT *
     FROM invite_requests
     WHERE id::text = $1 OR LOWER(email) = LOWER($2)
     ORDER BY created_at DESC
     LIMIT 1`,
    [identifier, emailHint || identifier],
  );

  return (inviteResult.rows[0] as Record<string, unknown> | undefined) || null;
}

async function findAdminAccountUser(
  identifier: string,
  emailHint?: string | null,
): Promise<Record<string, unknown> | null> {
  if (!(await hasTable("users"))) return null;

  const accountResult = await pool.query(
    `SELECT *
     FROM users
     WHERE id::text = $1 OR LOWER(email) = LOWER($2)
     LIMIT 1`,
    [identifier, emailHint || identifier],
  );

  return (accountResult.rows[0] as Record<string, unknown> | undefined) || null;
}

function normalizeSessionPermissions(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }

  return Array.from(
    new Set(
      value
        .map((entry) => toAdminString(entry)?.trim().toLowerCase() || null)
        .filter((entry): entry is string => Boolean(entry)),
    ),
  );
}

async function buildSessionUserFromActiveSession(session: ActiveSessionData) {
  const accountUser = await findAdminAccountUser(session.userId, session.email).catch(
    () => null,
  );
  const sessionRoleId = normalizeAdminRoleId(
    session.role || inferAdminRoleFromProfession(session.profession),
  );
  const accountRoleId = accountUser
    ? normalizeAdminRoleId(
        accountUser.role || inferAdminRoleFromProfession(accountUser.profession),
      )
    : "user";
  const roleId =
    sessionRoleId === "user" && accountRoleId !== "user"
      ? accountRoleId
      : sessionRoleId || accountRoleId;
  const roleEntry = buildAdminRoleEntry(roleId);
  const permissions = (() => {
    const normalized = normalizeSessionPermissions(session.permissions);
    return normalized.length > 0 ? normalized : roleEntry.permissions;
  })();
  const profession =
    normalizeAdminProfession(session.profession, roleId) ||
    normalizeAdminProfession(accountUser?.profession, roleId) ||
    undefined;
  const displayName =
    toAdminString(session.displayName) ||
    formatAdminUserIdentity(accountUser) ||
    session.name ||
    session.email;
  const accessProfile = buildAdminAccessProfile(roleId, permissions);

  return {
    id: session.userId,
    email: session.email,
    name: session.name,
    displayName,
    role: roleId,
    roleLabel: toAdminString(session.roleLabel) || roleEntry.name,
    profession,
    userType: toAdminString(session.userType) || profession,
    permissions,
    requestedRole: toAdminString(session.requestedRole) || null,
    loginAs: toAdminString(session.loginAs) || undefined,
    isAdmin: session.isAdmin === true || ADMIN_SESSION_ROLES.has(roleId),
    isPlatformAdmin: accessProfile.isPlatformAdmin,
    isAcademyAdmin: accessProfile.isAcademyAdmin,
    accessScope: accessProfile.scopeId,
    accessScopeLabel: accessProfile.scopeLabel,
    accessDescription: accessProfile.description,
    vendorId: toAdminString(session.vendorId) || undefined,
    businessName:
      toAdminString(session.businessName) ||
      toAdminString(accountUser?.company_name) ||
      undefined,
    coupleProfileId: toAdminString(session.coupleProfileId) || undefined,
    picture: toAdminString(session.picture) || undefined,
    verified_email: session.verified_email === true,
    impersonatedByAdmin: session.impersonatedByAdmin === true,
    loginAt: session.loginAt,
  };
}

type AcademySessionRequirement = "authenticated" | "instructor";

async function requireAcademySession(
  req: express.Request,
  res: express.Response,
  requirement: AcademySessionRequirement = "authenticated",
): Promise<
  | {
      session: ActiveSessionData;
      user: Awaited<ReturnType<typeof buildSessionUserFromActiveSession>>;
      roleId: string;
      isInstructor: boolean;
    }
  | null
> {
  const querySessionToken =
    readString(req.query?.sessionToken) || readString(req.query?.token);
  const session =
    getActiveSessionFromRequest(req) ||
    (querySessionToken
      ? activeSessions.get(querySessionToken) ||
        getLocalDevelopmentSession(querySessionToken)
      : null);

  if (!session) {
    res.status(401).json({ error: "Academy-innlogging kreves" });
    return null;
  }

  const user = await buildSessionUserFromActiveSession(session);
  const roleId = normalizeAdminRoleId(user.role);
  const permissionSet = new Set(normalizeSessionPermissions(user.permissions));
  const isInstructor =
    ADMIN_SESSION_ROLES.has(roleId) ||
    ACADEMY_ADMIN_ROLES.has(roleId) ||
    roleId === "instructor" ||
    permissionSet.has("academy:admin") ||
    permissionSet.has("academy:write");

  if (requirement === "instructor" && !isInstructor) {
    res.status(403).json({ error: "Instruktør- eller admin-tilgang kreves" });
    return null;
  }

  return {
    session,
    user,
    roleId,
    isInstructor,
  };
}

async function upsertAdminAccountUser(input: {
  email: string;
  firstName?: string | null;
  lastName?: string | null;
  role?: string | null;
  profession?: string | null;
  businessName?: string | null;
  organizationNumber?: string | null;
  isActive?: boolean;
}) {
  if (!(await hasTable("users"))) return null;

  const userColumns = await getTableColumns("users");
  const existingUser = await findAdminAccountUser(input.email);
  const normalizedRole = normalizeAdminRoleId(input.role);
  const normalizedProfession = normalizeAdminProfession(
    input.profession,
    normalizedRole,
  );

  if (existingUser?.id) {
    const updates: string[] = [];
    const values: unknown[] = [];
    const pushValue = (column: string, value: unknown) => {
      values.push(value);
      updates.push(`${column} = $${values.length}`);
    };

    if (userColumns.has("first_name") && input.firstName !== undefined) {
      pushValue("first_name", input.firstName);
    }
    if (userColumns.has("last_name") && input.lastName !== undefined) {
      pushValue("last_name", input.lastName);
    }
    if (userColumns.has("role") && input.role !== undefined) {
      pushValue("role", normalizedRole);
    }
    if (userColumns.has("profession") && input.profession !== undefined) {
      pushValue("profession", normalizedProfession);
    }
    if (userColumns.has("company_name") && input.businessName !== undefined) {
      pushValue("company_name", input.businessName);
    }
    if (
      userColumns.has("organization_number") &&
      input.organizationNumber !== undefined
    ) {
      pushValue("organization_number", input.organizationNumber);
    }
    if (userColumns.has("is_active") && input.isActive !== undefined) {
      pushValue("is_active", input.isActive);
    }
    if (userColumns.has("updated_at")) {
      pushValue("updated_at", new Date());
    }

    if (updates.length === 0) {
      return existingUser;
    }

    values.push(existingUser.id);
    const result = await pool.query(
      `UPDATE users
       SET ${updates.join(", ")}
       WHERE id = $${values.length}
       RETURNING *`,
      values,
    );
    return result.rows[0] || existingUser;
  }

  const insertColumns: string[] = [];
  const placeholders: string[] = [];
  const values: unknown[] = [];
  const pushInsert = (column: string, value: unknown) => {
    insertColumns.push(column);
    values.push(value);
    placeholders.push(`$${values.length}`);
  };

  pushInsert("email", input.email.toLowerCase());
  if (userColumns.has("username")) {
    pushInsert("username", adminUsernameFromEmail(input.email));
  }
  if (userColumns.has("password")) {
    pushInsert("password", "");
  }
  if (userColumns.has("first_name")) {
    pushInsert("first_name", input.firstName || null);
  }
  if (userColumns.has("last_name")) {
    pushInsert("last_name", input.lastName || null);
  }
  if (userColumns.has("role")) {
    pushInsert("role", normalizedRole);
  }
  if (userColumns.has("profession")) {
    pushInsert("profession", normalizedProfession);
  }
  if (userColumns.has("company_name")) {
    pushInsert("company_name", input.businessName || null);
  }
  if (userColumns.has("organization_number")) {
    pushInsert("organization_number", input.organizationNumber || null);
  }
  if (userColumns.has("is_active")) {
    pushInsert("is_active", input.isActive ?? true);
  }
  if (userColumns.has("created_at")) {
    pushInsert("created_at", new Date());
  }
  if (userColumns.has("updated_at")) {
    pushInsert("updated_at", new Date());
  }

  const result = await pool.query(
    `INSERT INTO users (${insertColumns.join(", ")})
     VALUES (${placeholders.join(", ")})
     RETURNING *`,
    values,
  );
  return result.rows[0] || null;
}

