// Helper: extract userId from request headers
function getUserIdFromAuth(req: any): string | null {
  // Check X-User-Id header first (explicit user identification)
  const userId = req.headers["x-user-id"];
  if (userId) return userId;
  // Fallback: try Authorization header
  const auth = req.headers.authorization;
  if (auth?.startsWith("Bearer ")) return auth.substring(7);
  return null;
}

// Helper: map projects row to camelCase ProjectData
function mapProjectRow(r: any) {
  return {
    id: r.id,
    name: r.name || r.title || "",
    title: r.title || r.name || "",
    description: r.description || "",
    clientName: r.client_name || r.client_email || "",
    clientEmail: r.client_email || "",
    clientPhone: r.client_phone || "",
    eventDate: r.event_date || r.date || "",
    location: r.location || "",
    projectType: r.category || r.profession || "",
    profession: r.profession || "",
    status: r.status || "draft",
    priority: r.priority || "medium",
    budget: r.budget ? parseFloat(r.budget) : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    createdBy: r.user_id || "",
    userId: r.user_id || "",
    settings: r.settings || {},
    metadata: r.metadata || {},
    integrations: {
      googleDrive: r.drive_backup_enabled || false,
      googlePhotos: false,
      weddingTimeline: false,
      showcase: false,
      worklog: false,
    },
    coverImage: r.cover_image || null,
    slug: r.slug || null,
    estimatedHours: r.estimated_hours || 0,
    actualHours: r.actual_hours || 0,
    expenses: r.expenses || 0,
    featured: r.featured || false,
    published: r.published || false,
    customerId: r.customer_id || null,
  };
}

// GET /api/projects — list projects for user

// POST /api/projects/:projectId/shots/:shotId/link-asset — mark a shot
// in the shot list as captured by linking it to an uploaded asset.
// Used by the iPad (Phase 2B Lag D follow-up) and can also be called
// from the web review surface.
app.post(
  "/api/projects/:projectId/shots/:shotId/link-asset",
  async (req, res) => {
    try {
      const { projectId, shotId } = req.params;
      const userId = getUserIdFromAuth(req);
      if (!userId) {
        return res.status(401).json({ error: "unauthorized" });
      }
      const capturedAssetId =
        typeof req.body?.capturedAssetId === "string" && req.body.capturedAssetId
          ? req.body.capturedAssetId
          : req.body?.capturedAssetId === null
            ? null
            : undefined;
      if (capturedAssetId === undefined) {
        return res
          .status(400)
          .json({ error: "capturedAssetId is required (use null to unlink)" });
      }
      const result = await linkShotToAsset(
        db as any,
        userId,
        projectId,
        shotId,
        capturedAssetId,
      );
      if (!result.ok) {
        return res.status(404).json({ error: result.error });
      }
      // Push the link change to every iPad/web surface signed in as
      // this photographer so their Live Set dashboards swap the
      // missing-tile for a thumbnail without polling. Best-effort.
      broadcastUserEvent(userId, {
        kind: "shot.captured",
        projectId,
        shotId,
        capturedAssetId,
        timestamp: new Date().toISOString(),
      });
      res.json({ success: true, data: result.data });
    } catch (error) {
      console.error("Error linking shot to asset:", error);
      res.status(500).json({ error: "Kunne ikke knytte shot til asset" });
    }
  },
);

