// Backward-compat middleware: /api/wedflow/* → rewrite to /api/evendi/*
// so legacy clients that still call /api/wedflow/* continue to work.
// All canonical routes are now registered under /api/evendi/*.
app.use("/api/wedflow", (req, _res, next) => {
  const originalUrl = req.originalUrl;
  req.url = originalUrl.replace("/api/wedflow", "/api/evendi");
  next("route");
});
app.all("/api/wedflow/*", (req, res, next) => {
  req.url = req.url.replace("/api/wedflow", "/api/evendi");
  req.originalUrl = req.originalUrl.replace("/api/wedflow", "/api/evendi");
  (req.app as any).handle(req, res, next);
});

const CREATORHUB_API_KEY = process.env.CREATORHUB_API_KEY || "";
const EVENDI_SMOKE_SECRET =
  process.env.EVENDI_ADMIN_SECRET ||
  process.env.WEDFLOW_ADMIN_SECRET ||
  process.env.EXPO_PUBLIC_ADMIN_SECRET ||
  "";

const isEvendiSmokeAuthorized = (req: any) => {
  if (!EVENDI_SMOKE_SECRET) return false;
  const header = req.get("x-admin-secret") || req.get("x-evendi-admin-secret");
  return header && header === EVENDI_SMOKE_SECRET;
};

async function runEvendiSmoke(path: string) {
  const url = `${EVENDI_API_URL}${path}`;
  const response = await fetch(url, {
    headers: {
      "Content-Type": "application/json",
      "X-API-Key": CREATORHUB_API_KEY,
    },
  });
  const contentType = response.headers.get("content-type") || "";
  const payload = contentType.includes("application/json")
    ? await response.json()
    : await response.text();

  return {
    status: response.status,
    ok: response.ok,
    data: payload,
  };
}

// ── Couple Planning Timelines (MUST be registered BEFORE the wildcard proxy) ──

// Helper: resolve :coupleId param — accepts UUID, email, or resolves from project
async function resolveCoupleId(coupleIdParam: string): Promise<string | null> {
  // If it's already a UUID, verify it exists
  const uuidRegex =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (uuidRegex.test(coupleIdParam)) {
    const r = await pool.query("SELECT id FROM couple_profiles WHERE id = $1", [
      coupleIdParam,
    ]);
    return r.rowCount && r.rowCount > 0 ? r.rows[0].id : null;
  }
  // Try by email
  const byEmail = await pool.query(
    "SELECT id FROM couple_profiles WHERE email = $1",
    [coupleIdParam],
  );
  if (byEmail.rowCount && byEmail.rowCount > 0) return byEmail.rows[0].id;
  // Try by display_name (partial)
  const byName = await pool.query(
    "SELECT id FROM couple_profiles WHERE LOWER(display_name) LIKE $1 LIMIT 1",
    [`%${coupleIdParam.toLowerCase()}%`],
  );
  if (byName.rowCount && byName.rowCount > 0) return byName.rows[0].id;
  return null;
}

