// Helper: get vendor ID from session
async function getVendorFromSession(
  req: any,
  res: any,
): Promise<{ id: string; business_name: string } | null> {
  const token = req.headers.authorization?.replace("Bearer ", "");
  const session = token ? activeSessions.get(token) : null;
  if (!session) {
    res.status(401).json({ error: "Ikke autentisert" });
    return null;
  }
  const result = await pool.query(
    "SELECT id, business_name FROM vendors WHERE LOWER(email) = LOWER($1) LIMIT 1",
    [session.email],
  );
  if (!result.rows.length) {
    res.status(404).json({ error: "Ingen vendor-profil funnet" });
    return null;
  }
  return result.rows[0];
}

