// Generic Evendi API proxy — forwards /api/evendi/* → Evendi API /api/*
// Legacy /api/wedflow/* is rewritten to /api/evendi/* by the backward-compat middleware above
// MUST be AFTER all specific /api/evendi/planning/* routes to avoid shadowing
const localEvendiRoutes = new Set([
  "/api/evendi/bookings",
  "/api/evendi/analytics/summary",
]);

app.all("/api/evendi/*", async (req, res, next) => {
  if (localEvendiRoutes.has(req.path)) {
    return next();
  }

  try {
    const evendiPath = req.path.replace("/api/evendi", "/api");
    const url = `${EVENDI_API_URL}${evendiPath}`;

    const fetchOpts: any = {
      method: req.method,
      headers: {
        "Content-Type": "application/json",
        "X-API-Key": CREATORHUB_API_KEY,
      },
    };
    if (["POST", "PUT", "PATCH"].includes(req.method) && req.body) {
      fetchOpts.body = JSON.stringify(req.body);
    }

    const response = await fetch(url, fetchOpts);
    const contentType = response.headers.get("content-type") || "";

    if (contentType.includes("application/json")) {
      const data = await response.json();
      res.status(response.status).json(data);
    } else {
      const text = await response.text();
      // If Evendi returned HTML (404 page), return JSON error
      if (text.includes("<!DOCTYPE") || text.includes("<html")) {
        res.status(response.status).json({
          error: "Evendi endpoint not found",
          path: evendiPath,
          status: response.status,
        });
      } else {
        res.status(response.status).send(text);
      }
    }
  } catch (error: any) {
    console.error("Evendi proxy error:", error.message);
    res
      .status(502)
      .json({ error: "Kunne ikke nå Evendi API", details: error.message });
  }
});

