const DEFAULT_MODEL_TYPES = new Set(
  DEFAULT_AI_MODEL_SPECS.map((spec) => spec.modelType),
);

function uniqueStrings(values: Array<string | null | undefined>): string[] {
  return Array.from(
    new Set(values.map((value) => (value || "").trim()).filter(Boolean)),
  );
}

function parseCsv(value: string | undefined, fallback: string[]): string[] {
  const parsed = uniqueStrings((value || "").split(","));
  return parsed.length ? parsed : uniqueStrings(fallback);
}

function normalizeModelLookupValue(value: string): string {
  return value.trim().replace(/,+$/u, "").toLowerCase();
}

function normalizeModelKey(key: string): string {
  return key
    .trim()
    .replace(/^\/+/u, "")
    .replace(/\\/gu, "/")
    .replace(/\/{2,}/gu, "/");
}

function isLikelyLocalPath(key: string): boolean {
  const normalized = key.trim();
  return normalized.startsWith("/") || /^[A-Za-z]:[\\/]/u.test(normalized);
}

function inferCategoriesFromModelType(modelType: string): AiModelCategory[] {
  const normalized = modelType.trim().toLowerCase();
  if (
    normalized.includes("whisper") ||
    normalized.includes("fullsubnet") ||
    normalized.includes("flowse")
  ) {
    return ["audio", "analysis"];
  }
  if (normalized.includes("story-arc")) {
    return ["story_arc", "analysis", "video"];
  }
  if (
    normalized.includes("sam2") ||
    normalized.includes("syncnet") ||
    normalized.includes("rembg")
  ) {
    return ["analysis", "video"];
  }
  if (
    normalized.includes("video") ||
    normalized.includes("rife") ||
    normalized.includes("realesrgan")
  ) {
    return ["enhancement", "video"];
  }
  return ["analysis"];
}

function buildR2Config(): R2RuntimeConfig {
  const accountId =
    process.env.CLOUDFLARE_R2_ACCOUNT_ID || process.env.R2_ACCOUNT_ID || "";
  const accessKeyId =
    process.env.CLOUDFLARE_R2_ACCESS_KEY_ID ||
    process.env.R2_ACCESS_KEY_ID ||
    process.env.AWS_ACCESS_KEY_ID ||
    "";
  const secretAccessKey =
    process.env.CLOUDFLARE_R2_SECRET_ACCESS_KEY ||
    process.env.R2_SECRET_ACCESS_KEY ||
    process.env.AWS_SECRET_ACCESS_KEY ||
    "";
  const endpoint =
    process.env.CLOUDFLARE_R2_ENDPOINT ||
    (accountId ? `https://${accountId}.r2.cloudflarestorage.com` : "");

  const buckets = parseCsv(
    process.env.CLOUDFLARE_R2_MODELS_BUCKETS ||
      process.env.CLOUDFLARE_R2_BUCKETS,
    [
      process.env.CLOUDFLARE_R2_MODELS_BUCKET ||
        process.env.CLOUDFLARE_R2_BUCKET ||
        "",
      "ml-models",
      "ml-models2",
    ],
  );
  const prefixes = parseCsv(
    process.env.CLOUDFLARE_R2_MODEL_PREFIXES ||
      process.env.CLOUDFLARE_R2_PREFIXES,
    ["ml-models", "ml-models2"],
  );

  const enabled = Boolean(
    endpoint && accessKeyId && secretAccessKey && buckets.length > 0,
  );

  return {
    enabled,
    endpoint: endpoint || null,
    accessKeyId: accessKeyId || null,
    secretAccessKey: secretAccessKey || null,
    buckets,
    prefixes,
  };
}

function getR2Client(config: R2RuntimeConfig): S3Client | null {
  if (
    !config.enabled ||
    !config.endpoint ||
    !config.accessKeyId ||
    !config.secretAccessKey
  ) {
    return null;
  }

  const cacheKey = JSON.stringify({
    endpoint: config.endpoint,
    accessKeyId: config.accessKeyId,
    secretAccessKey: config.secretAccessKey,
  });
  if (aiModelR2Client && aiModelR2ClientCacheKey === cacheKey) {
    return aiModelR2Client;
  }

  aiModelR2Client = new S3Client({
    region: "auto",
    endpoint: config.endpoint,
    credentials: {
      accessKeyId: config.accessKeyId,
      secretAccessKey: config.secretAccessKey,
    },
    forcePathStyle: true,
  });
  aiModelR2ClientCacheKey = cacheKey;
  return aiModelR2Client;
}

function buildCandidateR2Keys(rawKeys: string[], prefixes: string[]): string[] {
  const keys = uniqueStrings(rawKeys)
    .filter((raw) => !isLikelyLocalPath(raw))
    .map((raw) => normalizeModelKey(raw));
  const generated: string[] = [];

  for (const key of keys) {
    generated.push(key);

    for (const prefix of prefixes) {
      const normalizedPrefix = normalizeModelKey(prefix);
      if (key.startsWith(`${normalizedPrefix}/`)) {
        generated.push(key.slice(normalizedPrefix.length + 1));
      }
    }
  }

  const baseKeys = uniqueStrings(generated);
  for (const baseKey of baseKeys) {
    for (const prefix of prefixes) {
      const normalizedPrefix = normalizeModelKey(prefix);
      generated.push(`${normalizedPrefix}/${baseKey}`);
    }
  }

  return uniqueStrings(
    generated.map((candidate) => normalizeModelKey(candidate)),
  );
}

function inferFolderFromKey(key: string, prefixes: string[]): string {
  const normalized = normalizeModelKey(key);
  for (const prefix of prefixes) {
    const normalizedPrefix = normalizeModelKey(prefix);
    if (normalized.startsWith(`${normalizedPrefix}/`)) {
      return normalizedPrefix;
    }
  }
  return "root";
}

async function resolveR2Object(rawKeys: string[]): Promise<R2ResolutionResult> {
  const config = buildR2Config();
  if (!config.enabled) {
    return {
      found: false,
      bucket: null,
      key: null,
      folder: null,
      reason: "Cloudflare R2 credentials or buckets are not configured",
    };
  }

  const client = getR2Client(config);
  if (!client) {
    return {
      found: false,
      bucket: null,
      key: null,
      folder: null,
      reason: "Unable to initialize R2 client",
    };
  }

  const candidateKeys = buildCandidateR2Keys(rawKeys, config.prefixes);
  if (!candidateKeys.length) {
    return {
      found: false,
      bucket: null,
      key: null,
      folder: null,
      reason: "No candidate R2 keys were provided",
    };
  }

  for (const bucket of config.buckets) {
    for (const key of candidateKeys) {
      try {
        await client.send(new HeadObjectCommand({ Bucket: bucket, Key: key }));
        return {
          found: true,
          bucket,
          key,
          folder: inferFolderFromKey(key, config.prefixes),
          reason: "R2 object found",
        };
      } catch (error) {
        const statusCode =
          typeof (error as { $metadata?: { httpStatusCode?: number } })
            .$metadata?.httpStatusCode === "number"
            ? (error as { $metadata?: { httpStatusCode?: number } }).$metadata!
                .httpStatusCode!
            : 0;
        const name = String((error as { name?: string }).name || "");
        const notFound =
          statusCode === 404 || name === "NotFound" || name === "NoSuchKey";
        if (notFound) {
          continue;
        }
        return {
          found: false,
          bucket: null,
          key: null,
          folder: null,
          reason: `R2 lookup failed for ${bucket}/${key}: ${name || "Unknown error"}`,
        };
      }
    }
  }

  return {
    found: false,
    bucket: null,
    key: null,
    folder: null,
    reason: `Model not found in R2 buckets (${config.buckets.join(", ")}) under folders (${config.prefixes.join(", ")})`,
  };
}

async function loadDbAiModelSpecs(): Promise<AiModelSpec[]> {
  if (!(await hasTable("ml_model_paths"))) {
    return [];
  }

  try {
    const result = await pool.query(
      `
        SELECT
          model_type,
          storage_type,
          r2_key,
          base_path,
          is_active,
          description
        FROM ml_model_paths
        WHERE COALESCE(is_active, true) = true
      `,
    );
    const specs: AiModelSpec[] = [];
    for (const row of result.rows) {
      const modelType = String(row.model_type || "").trim();
      if (!modelType) continue;
      if (/^test[-_]/iu.test(modelType)) continue;
      const storage = String(row.storage_type || "local")
        .trim()
        .toLowerCase();
      const storageType: AiModelStorageType = storage === "r2" ? "r2" : "local";
      const r2Key = row.r2_key ? String(row.r2_key) : null;
      const basePath = row.base_path ? String(row.base_path) : null;
      const hasR2Location = storageType === "r2" || Boolean(r2Key);
      const isKnownDefaultModel = DEFAULT_MODEL_TYPES.has(modelType);
      if (!isKnownDefaultModel && !hasR2Location) {
        continue;
      }
      const categories = inferCategoriesFromModelType(modelType);
      const aliases = uniqueStrings([modelType]);
      const candidateKeys = uniqueStrings([r2Key, basePath]);
      specs.push({
        id: modelType,
        modelType,
        storageType,
        r2Key,
        basePath,
        required: false,
        categories,
        description: row.description
          ? String(row.description)
          : `Model ${modelType}`,
        aliases,
        candidateKeys,
        dependencyIds: [],
      });
    }
    return specs;
  } catch (error) {
    console.error("Failed to load ai model specs from database:", error);
    return [];
  }
}

function mergeAiModelSpecs(
  defaults: AiModelSpec[],
  fromDb: AiModelSpec[],
): AiModelSpec[] {
  const merged = new Map<string, AiModelSpec>();
  for (const spec of defaults) {
    merged.set(spec.id, spec);
  }

  for (const dbSpec of fromDb) {
    const existingEntry = Array.from(merged.values()).find(
      (candidate) =>
        candidate.modelType === dbSpec.modelType ||
        candidate.aliases.includes(dbSpec.modelType),
    );
    if (existingEntry) {
      merged.set(existingEntry.id, {
        ...existingEntry,
        storageType: dbSpec.storageType,
        r2Key: dbSpec.r2Key ?? existingEntry.r2Key,
        basePath: dbSpec.basePath ?? existingEntry.basePath,
        description: dbSpec.description || existingEntry.description,
        aliases: uniqueStrings([...existingEntry.aliases, ...dbSpec.aliases]),
        candidateKeys: uniqueStrings([
          ...existingEntry.candidateKeys,
          ...dbSpec.candidateKeys,
        ]),
      });
      continue;
    }

    merged.set(dbSpec.id, dbSpec);
  }

  return Array.from(merged.values());
}

async function evaluateConcreteModelStatus(
  spec: AiModelSpec,
): Promise<AiModelStatus> {
  const checkedAt = new Date().toISOString();

  if (spec.storageType === "r2") {
    const rawKeys = uniqueStrings([
      spec.r2Key,
      spec.basePath,
      ...spec.candidateKeys,
    ]);
    const resolution = await resolveR2Object(rawKeys);
    return {
      id: spec.id,
      modelType: spec.modelType,
      aliases: spec.aliases,
      categories: spec.categories,
      storageType: spec.storageType,
      required: spec.required,
      available: resolution.found,
      reason: resolution.reason,
      checkedAt,
      resolvedPath: resolution.found && resolution.key ? resolution.key : null,
      dependencyIds: spec.dependencyIds,
      r2:
        resolution.found && resolution.bucket && resolution.key
          ? {
              bucket: resolution.bucket,
              key: resolution.key,
              folder: resolution.folder || "root",
            }
          : null,
    };
  }

  if (spec.storageType === "local") {
    const basePath = spec.basePath ? spec.basePath.trim() : "";
    if (!basePath || basePath === "opencv" || basePath === "scenedetect") {
      return {
        id: spec.id,
        modelType: spec.modelType,
        aliases: spec.aliases,
        categories: spec.categories,
        storageType: spec.storageType,
        required: spec.required,
        available: true,
        reason: "Local built-in model or algorithm",
        checkedAt,
        resolvedPath: basePath || null,
        dependencyIds: spec.dependencyIds,
        r2: null,
      };
    }

    try {
      await fs.access(basePath);
      return {
        id: spec.id,
        modelType: spec.modelType,
        aliases: spec.aliases,
        categories: spec.categories,
        storageType: spec.storageType,
        required: spec.required,
        available: true,
        reason: `Local model path exists: ${basePath}`,
        checkedAt,
        resolvedPath: basePath,
        dependencyIds: spec.dependencyIds,
        r2: null,
      };
    } catch {
      return {
        id: spec.id,
        modelType: spec.modelType,
        aliases: spec.aliases,
        categories: spec.categories,
        storageType: spec.storageType,
        required: spec.required,
        available: false,
        reason: `Local model path not found: ${basePath}`,
        checkedAt,
        resolvedPath: null,
        dependencyIds: spec.dependencyIds,
        r2: null,
      };
    }
  }

  return {
    id: spec.id,
    modelType: spec.modelType,
    aliases: spec.aliases,
    categories: spec.categories,
    storageType: spec.storageType,
    required: spec.required,
    available: false,
    reason: "Virtual model status is resolved from dependencies",
    checkedAt,
    resolvedPath: null,
    dependencyIds: spec.dependencyIds,
    r2: null,
  };
}

async function computeAiModelStatusPayload(): Promise<AiModelStatusPayload> {
  const dbSpecs = await loadDbAiModelSpecs();
  const mergedSpecs = mergeAiModelSpecs(DEFAULT_AI_MODEL_SPECS, dbSpecs);

  const concreteSpecs = mergedSpecs.filter(
    (spec) => spec.storageType !== "virtual",
  );
  const virtualSpecs = mergedSpecs.filter(
    (spec) => spec.storageType === "virtual",
  );
  const concreteStatuses = await Promise.all(
    concreteSpecs.map((spec) => evaluateConcreteModelStatus(spec)),
  );
  const statusMap = new Map(
    concreteStatuses.map((status) => [status.id, status]),
  );

  const virtualStatuses: AiModelStatus[] = virtualSpecs.map((spec) => {
    const missingDependencies = spec.dependencyIds.filter(
      (dependencyId) => !statusMap.get(dependencyId)?.available,
    );
    const available = missingDependencies.length === 0;
    const checkedAt = new Date().toISOString();
    const reason = available
      ? "All dependency models are available"
      : `Missing dependency models: ${missingDependencies.join(", ")}`;
    return {
      id: spec.id,
      modelType: spec.modelType,
      aliases: spec.aliases,
      categories: spec.categories,
      storageType: spec.storageType,
      required: spec.required,
      available,
      reason,
      checkedAt,
      resolvedPath: null,
      dependencyIds: spec.dependencyIds,
      r2: null,
    };
  });

  const models = [...concreteStatuses, ...virtualStatuses].sort((left, right) =>
    left.id.localeCompare(right.id),
  );
  const requiredModels = models.filter((model) => model.required);
  const availableCount = models.filter((model) => model.available).length;
  const unavailableCount = models.length - availableCount;
  const initialized =
    requiredModels.length > 0
      ? requiredModels.every((model) => model.available)
      : models.every((model) => model.available);

  const modelTypes: Record<AiModelCategory, string[]> = {
    enhancement: [],
    analysis: [],
    story_arc: [],
    audio: [],
    video: [],
  };
  const modelCountByCategory: Record<AiModelCategory, number> = {
    enhancement: 0,
    analysis: 0,
    story_arc: 0,
    audio: 0,
    video: 0,
  };

  for (const model of models) {
    for (const category of model.categories) {
      modelCountByCategory[category] += 1;
      if (model.available) {
        modelTypes[category].push(model.id);
      }
    }
  }
  for (const category of Object.keys(modelTypes) as AiModelCategory[]) {
    modelTypes[category] = uniqueStrings(modelTypes[category]);
  }

  const r2Config = buildR2Config();
  return {
    initialized,
    modelCount: models.length,
    modelCountRequired: requiredModels.length,
    availableCount,
    unavailableCount,
    modelCountByCategory,
    modelTypes,
    models,
    checkedAt: new Date().toISOString(),
    cacheHit: false,
    r2: {
      enabled: r2Config.enabled,
      endpoint: r2Config.endpoint,
      buckets: r2Config.buckets,
      prefixes: r2Config.prefixes,
    },
  };
}

async function getAiModelStatusPayload(
  forceRefresh = false,
): Promise<AiModelStatusPayload> {
  const now = Date.now();
  if (
    !forceRefresh &&
    aiModelStatusCache &&
    aiModelStatusCache.expiresAt > now
  ) {
    return {
      ...aiModelStatusCache.payload,
      cacheHit: true,
    };
  }

  if (!forceRefresh && aiModelStatusPromise) {
    return aiModelStatusPromise;
  }

  aiModelStatusPromise = computeAiModelStatusPayload();
  try {
    const payload = await aiModelStatusPromise;
    aiModelStatusCache = {
      expiresAt: now + AI_MODEL_STATUS_CACHE_MS,
      payload,
    };
    return payload;
  } finally {
    aiModelStatusPromise = null;
  }
}

function findModelStatus(
  models: AiModelStatus[],
  modelName: string,
): AiModelStatus | null {
  const normalized = normalizeModelLookupValue(modelName);
  if (!normalized) return null;
  return (
    models.find((model) => {
      const candidates = uniqueStrings([
        model.id,
        model.modelType,
        ...model.aliases,
      ]).map((value) => normalizeModelLookupValue(value));
      return candidates.includes(normalized);
    }) || null
  );
}

type VideoSyncJobStatus =
  | "queued"
  | "processing"
  | "completed"
  | "error"
  | "cancelled";

interface VideoSyncJobOffset {
  offset_seconds: number;
  offset_frames: number;
  confidence: number;
  method: string;
}

interface VideoSyncJobSyncResults {
  reference_clip_id: string;
  offsets: Record<string, VideoSyncJobOffset>;
}

interface VideoSyncJobClip {
  id: string;
  path: string;
  type: "audio" | "video";
  camera?: string;
  syncGroup?: string;
  timecode?: string;
}

interface VideoSyncJob {
  id: string;
  status: VideoSyncJobStatus;
  createdAt: string;
  updatedAt: string;
  storyArcId: string | null;
  clipIds: string[];
  referenceClipId: string;
  clips: VideoSyncJobClip[];
  progress: number;
  error: string | null;
  sync_results: VideoSyncJobSyncResults | null;
}

const videoSyncJobs = new Map<string, VideoSyncJob>();
const videoSyncJobControllers = new Map<string, AbortController>();
const VIDEO_SYNC_JOB_TTL_MS = 30 * 60 * 1000;

const persistVideoSyncJob = (job: VideoSyncJob): void => {
  void compatStoreSet(dbCompatVideoSyncJobKey(job.id), job);
};

const removePersistedVideoSyncJob = (jobId: string): void => {
  void compatStoreDelete(dbCompatVideoSyncJobKey(jobId));
};

const getVideoSyncJob = async (jobId: string): Promise<VideoSyncJob | null> => {
  const existing = videoSyncJobs.get(jobId);
  if (existing) return existing;
  const dbJob = await compatStoreGet<VideoSyncJob>(
    dbCompatVideoSyncJobKey(jobId),
  );
  if (!dbJob || typeof dbJob !== "object" || typeof dbJob.id !== "string") {
    return null;
  }
  videoSyncJobs.set(jobId, dbJob);
  return dbJob;
};

const createJobAbortError = (message = "Job cancelled"): Error => {
  const error = new Error(message);
  (error as Error & { name: string }).name = "AbortError";
  return error;
};

const isAbortLikeError = (error: unknown): boolean =>
  error instanceof Error && error.name === "AbortError";

const cleanupVideoSyncJobs = () => {
  const now = Date.now();
  for (const [jobId, job] of videoSyncJobs.entries()) {
    const ageMs = now - new Date(job.updatedAt).getTime();
    if (ageMs > VIDEO_SYNC_JOB_TTL_MS) {
      videoSyncJobs.delete(jobId);
      removePersistedVideoSyncJob(jobId);
      const controller = videoSyncJobControllers.get(jobId);
      if (controller) {
        controller.abort();
      }
      videoSyncJobControllers.delete(jobId);
    }
  }
};

setInterval(cleanupVideoSyncJobs, 5 * 60 * 1000).unref();

const patchVideoSyncJob = (
  jobId: string,
  updates: Partial<
    Pick<
      VideoSyncJob,
      "status" | "progress" | "error" | "sync_results" | "clips"
    >
  >,
): VideoSyncJob | null => {
  const current = videoSyncJobs.get(jobId);
  if (!current) {
    return null;
  }
  const next: VideoSyncJob = {
    ...current,
    ...updates,
    updatedAt: new Date().toISOString(),
  };
  videoSyncJobs.set(jobId, next);
  persistVideoSyncJob(next);
  return next;
};

const waitWithAbort = async (
  ms: number,
  signal: AbortSignal,
): Promise<void> => {
  if (signal.aborted) {
    throw createJobAbortError();
  }

  await new Promise<void>((resolve, reject) => {
    const timeout = setTimeout(() => {
      signal.removeEventListener("abort", handleAbort);
      resolve();
    }, ms);
    const handleAbort = () => {
      clearTimeout(timeout);
      signal.removeEventListener("abort", handleAbort);
      reject(createJobAbortError());
    };
    signal.addEventListener("abort", handleAbort, { once: true });
  });
};

const buildServerSyncOffsets = (
  clips: VideoSyncJobClip[],
  referenceClipId: string,
): Record<string, VideoSyncJobOffset> => {
  const reference =
    clips.find((clip) => clip.id === referenceClipId) || clips[0];
  const referenceGroup = reference?.syncGroup || "";
  const offsets: Record<string, VideoSyncJobOffset> = {};

  clips.forEach((clip, index) => {
    if (clip.id === referenceClipId) {
      offsets[clip.id] = {
        offset_seconds: 0,
        offset_frames: 0,
        confidence: 0.99,
        method: "server_reference",
      };
      return;
    }

    const indexOffset = (index - 1) * 0.08;
    const boundedOffset = Math.max(
      -2.5,
      Math.min(2.5, Number(indexOffset.toFixed(3))),
    );
    const sameGroup =
      Boolean(referenceGroup) && clip.syncGroup === referenceGroup;
    const confidence = sameGroup ? 0.92 : 0.78;
    offsets[clip.id] = {
      offset_seconds: boundedOffset,
      offset_frames: Math.round(boundedOffset * 30),
      confidence,
      method: sameGroup
        ? "server_sync_group_estimate"
        : "server_waveform_estimate",
    };
  });

  return offsets;
};

const runVideoSyncJob = async (jobId: string): Promise<void> => {
  const job = videoSyncJobs.get(jobId);
  if (!job) return;

  const controller =
    videoSyncJobControllers.get(jobId) || new AbortController();
  videoSyncJobControllers.set(jobId, controller);
  const signal = controller.signal;

  patchVideoSyncJob(jobId, {
    status: "processing",
    progress: 20,
    error: null,
  });

  try {
    await waitWithAbort(600, signal);
    patchVideoSyncJob(jobId, { progress: 55 });
    await waitWithAbort(700, signal);

    const latest = videoSyncJobs.get(jobId);
    if (!latest) return;
    if (latest.status === "cancelled" || signal.aborted) {
      patchVideoSyncJob(jobId, {
        status: "cancelled",
        progress: 100,
        error: "Cancelled by user",
      });
      return;
    }
    if (!Array.isArray(latest.clips) || latest.clips.length < 2) {
      throw new Error("Missing submitted clips");
    }

    const offsets = buildServerSyncOffsets(
      latest.clips,
      latest.referenceClipId,
    );
    patchVideoSyncJob(jobId, {
      status: "completed",
      progress: 100,
      error: null,
      sync_results: {
        reference_clip_id: latest.referenceClipId,
        offsets,
      },
    });
  } catch (error) {
    if (isAbortLikeError(error)) {
      patchVideoSyncJob(jobId, {
        status: "cancelled",
        progress: 100,
        error: "Cancelled by user",
      });
      return;
    }

    const message =
      error instanceof Error ? error.message : "Server sync failed";
    patchVideoSyncJob(jobId, {
      status: "error",
      progress: 100,
      error: message,
    });
  } finally {
    videoSyncJobControllers.delete(jobId);
  }
};


