let videoAnalysisStateWritePromise: Promise<void> = Promise.resolve();

const persistVideoAnalysisJob = (job: VideoAnalysisJob): void => {
  void compatStoreSet(dbCompatVideoAnalysisJobKey(job.id), job);
};

const removePersistedVideoAnalysisJob = (jobId: string): void => {
  void compatStoreDelete(dbCompatVideoAnalysisJobKey(jobId));
};

const getVideoAnalysisJob = async (
  jobId: string,
): Promise<VideoAnalysisJob | null> => {
  const existing = videoAnalysisJobs.get(jobId);
  if (existing) return existing;
  const dbJob = await compatStoreGet<VideoAnalysisJob>(
    dbCompatVideoAnalysisJobKey(jobId),
  );
  if (!dbJob || typeof dbJob !== "object" || typeof dbJob.id !== "string") {
    return null;
  }
  videoAnalysisJobs.set(jobId, dbJob);
  return dbJob;
};

const VIDEO_SOURCE_ALLOWED_EXTENSIONS = new Set([
  ".mp4",
  ".mov",
  ".m4v",
  ".webm",
  ".mkv",
  ".avi",
  ".mpeg",
  ".mpg",
  ".m2ts",
  ".mts",
  ".ts",
  ".wmv",
  ".flv",
  ".3gp",
  ".3g2",
  ".ogv",
  ".mp3",
  ".wav",
  ".aac",
  ".m4a",
  ".flac",
  ".ogg",
  ".opus",
]);

const videoSourceUpload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: MAX_VIDEO_SOURCE_BYTES,
  },
  fileFilter: (_req, file, cb) => {
    const mimetype = (file.mimetype || "").toLowerCase();
    const extension = path.extname(file.originalname || "").toLowerCase();
    const hasKnownExtension = VIDEO_SOURCE_ALLOWED_EXTENSIONS.has(extension);
    const hasAllowedMime =
      mimetype.startsWith("video/") ||
      mimetype.startsWith("audio/") ||
      mimetype === "application/octet-stream" ||
      mimetype === "binary/octet-stream" ||
      mimetype === "application/mp4" ||
      mimetype === "";
    const hasBlobFilename = (file.originalname || "").toLowerCase() === "blob";

    if (hasAllowedMime || hasKnownExtension || hasBlobFilename) {
      cb(null, true);
      return;
    }
    console.warn("Rejected video-analysis upload", {
      mimetype: file.mimetype,
      originalname: file.originalname,
    });
    cb(new Error("Invalid video format"));
  },
});

const ffmpegStaticPath = (() => {
  try {
    const resolved = _require("ffmpeg-static");
    return typeof resolved === "string" ? resolved : "";
  } catch {
    return "";
  }
})();

const ffprobeStaticPath = (() => {
  try {
    const resolved = _require("ffprobe-static") as { path?: unknown };
    return typeof resolved?.path === "string" ? resolved.path : "";
  } catch {
    return "";
  }
})();

const FFMPEG_BINARY =
  readString(process.env.FFMPEG_PATH) || ffmpegStaticPath || "ffmpeg";

const FFPROBE_BINARY =
  readString(process.env.FFPROBE_PATH) || ffprobeStaticPath || "ffprobe";
const TESSERACT_BINARY = readString(process.env.TESSERACT_PATH) || "tesseract";

const cleanupVideoAnalysisJobs = () => {
  const now = Date.now();
  let removed = false;
  for (const [jobId, job] of videoAnalysisJobs.entries()) {
    const ageMs = now - new Date(job.updatedAt).getTime();
    if (ageMs > VIDEO_ANALYSIS_JOB_TTL_MS) {
      videoAnalysisJobs.delete(jobId);
      removePersistedVideoAnalysisJob(jobId);
      const controller = videoAnalysisJobControllers.get(jobId);
      if (controller) {
        controller.abort();
      }
      videoAnalysisJobControllers.delete(jobId);
      removed = true;
    }
  }
  if (removed) {
    void persistVideoAnalysisJobsToDisk();
  }
};

setInterval(cleanupVideoAnalysisJobs, 5 * 60 * 1000).unref();

const persistVideoAnalysisJobsToDisk = (): Promise<void> => {
  const snapshot = Array.from(videoAnalysisJobs.values()).map((job) => ({
    ...job,
    input: { ...job.input },
    warnings: [...job.warnings],
    result: job.result,
  }));
  const payload = {
    version: 1,
    generatedAt: new Date().toISOString(),
    jobs: snapshot,
  };

  videoAnalysisStateWritePromise = videoAnalysisStateWritePromise
    .catch(() => undefined)
    .then(async () => {
      await fs.mkdir(path.dirname(VIDEO_ANALYSIS_STATE_PATH), {
        recursive: true,
      });
      await fs.writeFile(
        VIDEO_ANALYSIS_STATE_PATH,
        JSON.stringify(payload, null, 2),
      );
    })
    .catch((error) => {
      const message = error instanceof Error ? error.message : String(error);
      console.warn("[video-analysis] failed to persist job state:", message);
    });

  return videoAnalysisStateWritePromise;
};

const isHttpUrl = (value: string): boolean => {
  try {
    const url = new URL(value);
    return url.protocol === "http:" || url.protocol === "https:";
  } catch {
    return false;
  }
};

const normalizeVideoSourcePath = (rawVideoPath: string): string => {
  const trimmed = rawVideoPath.trim();
  if (!trimmed) return "";
  if (trimmed.startsWith("/")) {
    if (existsSync(trimmed)) {
      return trimmed;
    }
    return `http://127.0.0.1:${PORT}${trimmed}`;
  }
  if (trimmed.startsWith("//")) return `https:${trimmed}`;
  return trimmed;
};

const normalizeWhisperLanguage = (rawLanguage: string): string => {
  const normalized = normalizeModelLookupValue(rawLanguage || "") || "auto";
  const aliasMap: Record<string, string> = {
    nb: "no",
    nn: "no",
    nor: "no",
    jp: "ja",
    zhcn: "zh",
    zhtw: "zh",
  };
  return aliasMap[normalized] || normalized;
};

const persistVideoAnalysisUpload = async (file: {
  originalname?: string;
  buffer: Buffer;
}) => {
  if (!Buffer.isBuffer(file.buffer) || file.buffer.byteLength === 0) {
    throw new Error("Uploaded video file is empty");
  }

  if (file.buffer.byteLength > MAX_VIDEO_SOURCE_BYTES) {
    throw new Error("Uploaded video exceeds max accepted size of 512MB");
  }

  await fs.mkdir(VIDEO_ANALYSIS_UPLOAD_DIR, { recursive: true });
  const originalExtension = path.extname(file.originalname || "").toLowerCase();
  const extension = originalExtension || ".mp4";
  const targetPath = path.join(
    VIDEO_ANALYSIS_UPLOAD_DIR,
    `${Date.now()}-${crypto.randomUUID()}${extension}`,
  );
  await fs.writeFile(targetPath, file.buffer);
  return targetPath;
};

const createVideoAnalysisJob = (
  type: VideoAnalysisJobType,
  input: VideoAnalysisJobInput,
): VideoAnalysisJob => {
  const nowIso = new Date().toISOString();
  const job: VideoAnalysisJob = {
    id: crypto.randomUUID(),
    type,
    status: "queued",
    progress: 0,
    stage: "queued",
    attempts: 0,
    maxAttempts:
      type === "transcribe" ? VIDEO_ANALYSIS_TRANSCRIBE_MAX_ATTEMPTS : 1,
    resumed: false,
    createdAt: nowIso,
    updatedAt: nowIso,
    input,
    warnings: [],
    result: null,
    error: null,
  };
  videoAnalysisJobs.set(job.id, job);
  persistVideoAnalysisJob(job);
  videoAnalysisJobControllers.set(job.id, new AbortController());
  void persistVideoAnalysisJobsToDisk();
  return job;
};

const patchVideoAnalysisJob = (
  jobId: string,
  updates: Partial<
    Pick<
      VideoAnalysisJob,
      | "status"
      | "progress"
      | "stage"
      | "attempts"
      | "maxAttempts"
      | "resumed"
      | "warnings"
      | "result"
      | "error"
    >
  >,
): VideoAnalysisJob | null => {
  const current = videoAnalysisJobs.get(jobId);
  if (!current) return null;
  const next: VideoAnalysisJob = {
    ...current,
    ...updates,
    updatedAt: new Date().toISOString(),
  };
  videoAnalysisJobs.set(jobId, next);
  persistVideoAnalysisJob(next);
  void persistVideoAnalysisJobsToDisk();
  return next;
};

const appendWarning = (warnings: string[], warning: string) => {
  if (!warning.trim()) return;
  if (!warnings.includes(warning)) {
    warnings.push(warning);
  }
};

interface BinaryCommandResult {
  code: number;
  stdout: string;
  stderr: string;
  timedOut: boolean;
}

const runBinaryCommand = async (
  binary: string,
  args: string[],
  timeoutMs: number,
  signal?: AbortSignal,
): Promise<BinaryCommandResult> => {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(createJobAbortError());
      return;
    }

    const processRef = spawn(binary, args, {
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    let timedOut = false;
    let settled = false;
    const MAX_LOG_CHARS = 2_000_000;

    const appendChunk = (current: string, chunk: string): string => {
      if (current.length >= MAX_LOG_CHARS) return current;
      const remaining = MAX_LOG_CHARS - current.length;
      return current + chunk.slice(0, remaining);
    };

    processRef.stdout.on("data", (chunk: Buffer | string) => {
      stdout = appendChunk(stdout, chunk.toString());
    });

    processRef.stderr.on("data", (chunk: Buffer | string) => {
      stderr = appendChunk(stderr, chunk.toString());
    });

    const cleanup = () => {
      clearTimeout(timeoutRef);
      if (signal) {
        signal.removeEventListener("abort", handleAbort);
      }
    };

    const resolveOnce = (result: BinaryCommandResult) => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(result);
    };

    const rejectOnce = (error: unknown) => {
      if (settled) return;
      settled = true;
      cleanup();
      reject(error);
    };

    processRef.on("error", (error) => {
      rejectOnce(error);
    });

    const timeoutRef = setTimeout(() => {
      timedOut = true;
      processRef.kill("SIGKILL");
    }, timeoutMs);

    const handleAbort = () => {
      processRef.kill("SIGKILL");
      rejectOnce(createJobAbortError());
    };

    if (signal) {
      signal.addEventListener("abort", handleAbort, { once: true });
    }

    processRef.on("close", (code) => {
      resolveOnce({
        code: typeof code === "number" ? code : -1,
        stdout,
        stderr,
        timedOut,
      });
    });
  });
};

const stageVideoSource = async (
  videoPath: string,
  tempDir: string,
  signal?: AbortSignal,
): Promise<string> => {
  const normalizedSource = normalizeVideoSourcePath(videoPath);
  if (!normalizedSource) {
    throw new Error("Missing video path");
  }

  if (isHttpUrl(normalizedSource)) {
    const url = new URL(normalizedSource);
    const extension = path.extname(url.pathname) || ".mp4";
    const stagedPath = path.join(tempDir, `input${extension}`);
    const response = await fetch(normalizedSource, {
      signal: signal || AbortSignal.timeout(120_000),
    });
    if (!response.ok) {
      throw new Error(`Failed to download video (${response.status})`);
    }

    const contentLength = Number(response.headers.get("content-length") || 0);
    if (
      Number.isFinite(contentLength) &&
      contentLength > MAX_VIDEO_SOURCE_BYTES
    ) {
      throw new Error("Video source is larger than 512MB limit");
    }

    const sourceBuffer = Buffer.from(await response.arrayBuffer());
    if (sourceBuffer.byteLength > MAX_VIDEO_SOURCE_BYTES) {
      throw new Error("Video source exceeds max accepted size of 512MB");
    }

    await fs.writeFile(stagedPath, sourceBuffer);
    return stagedPath;
  }

  let localPath = normalizedSource;
  if (localPath.startsWith("file://")) {
    localPath = fileURLToPath(localPath);
  }
  if (!path.isAbsolute(localPath)) {
    localPath = path.resolve(process.cwd(), localPath);
  }

  await fs.access(localPath);
  const stagedPath = path.join(
    tempDir,
    `input${path.extname(localPath) || ".mp4"}`,
  );
  await fs.copyFile(localPath, stagedPath);
  return stagedPath;
};

const probeVideoDurationSeconds = async (
  videoPath: string,
  signal?: AbortSignal,
): Promise<number> => {
  const probeResult = await runBinaryCommand(
    FFPROBE_BINARY,
    [
      "-v",
      "error",
      "-show_entries",
      "format=duration",
      "-of",
      "json",
      videoPath,
    ],
    30_000,
    signal,
  );
  if (probeResult.code !== 0) {
    throw new Error(`ffprobe failed (${probeResult.code})`);
  }

  const parsed = JSON.parse(probeResult.stdout) as {
    format?: { duration?: string | number };
  };
  const rawDuration = parsed?.format?.duration;
  const durationValue =
    typeof rawDuration === "number"
      ? rawDuration
      : typeof rawDuration === "string"
        ? Number(rawDuration)
        : NaN;

  return Number.isFinite(durationValue) && durationValue > 0
    ? durationValue
    : 0;
};

type AcademyStoredMediaType = "image" | "video" | "audio" | "document";

interface AcademyStoredMediaVersionRecord {
  version: number;
  fileName: string;
  mimeType: string;
  size: number;
  duration?: number;
  fingerprint: string;
  updatedAt: string;
  relativePath: string;
  posterRelativePath?: string;
  posterMimeType?: string;
}

interface AcademyStoredMediaAssetRecord {
  id: string;
  name: string;
  type: AcademyStoredMediaType;
  folderId: string;
  courseId?: string;
  lessonId?: string;
  tags: string[];
  createdAt: string;
  updatedAt: string;
  currentVersion: AcademyStoredMediaVersionRecord;
  history: AcademyStoredMediaVersionRecord[];
}

interface AcademyStoredMediaManifest {
  version: number;
  updatedAt: string;
  assets: AcademyStoredMediaAssetRecord[];
}

const ACADEMY_MEDIA_STORAGE_DIR = path.join(REPO_ROOT, "tmp", "academy-media");
const ACADEMY_MEDIA_MANIFEST_PATH = path.join(
  ACADEMY_MEDIA_STORAGE_DIR,
  "manifest.json",
);
let academyMediaManifestCache: AcademyStoredMediaManifest | null = null;
let academyMediaManifestWritePromise: Promise<void> = Promise.resolve();

const createDefaultAcademyMediaManifest = (): AcademyStoredMediaManifest => ({
  version: 1,
  updatedAt: new Date().toISOString(),
  assets: [],
});

const sanitizeAcademyMediaName = (value: string): string => {
  const trimmed = value.trim();
  if (!trimmed) return "academy-media";
  return (
    trimmed
      .replace(/\s+/g, "-")
      .replace(/[^a-zA-Z0-9._-]+/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 120) || "academy-media"
  );
};

const normalizeAcademyMediaType = (
  mimetype: string,
  fileName: string,
): AcademyStoredMediaType => {
  const normalizedMime = String(mimetype || "").toLowerCase();
  const extension = path.extname(fileName || "").toLowerCase();
  if (normalizedMime.startsWith("image/")) return "image";
  if (normalizedMime.startsWith("video/")) return "video";
  if (normalizedMime.startsWith("audio/")) return "audio";
  if ([".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg"].includes(extension))
    return "image";
  if (
    [
      ".mp4",
      ".mov",
      ".webm",
      ".mkv",
      ".avi",
      ".m4v",
      ".mpeg",
      ".mpg",
      ".wmv",
      ".flv",
    ].includes(extension)
  )
    return "video";
  if (
    [".mp3", ".wav", ".aac", ".m4a", ".flac", ".ogg", ".opus"].includes(
      extension,
    )
  )
    return "audio";
  return "document";
};

const computeAcademyMediaFingerprint = (buffer: Buffer): string =>
  crypto.createHash("sha1").update(buffer).digest("hex");

const normalizeAcademyMediaTags = (
  value: unknown,
  folderId: string,
): string[] => {
  const tags = Array.isArray(value)
    ? value.map((entry) => String(entry || "").trim()).filter(Boolean)
    : typeof value === "string"
      ? value
          .split(",")
          .map((entry) => entry.trim())
          .filter(Boolean)
      : [];

  const withFolderTag =
    folderId && !tags.includes(folderId) ? [folderId, ...tags] : tags;
  return Array.from(new Set(withFolderTag));
};

const buildAcademyMediaFileUrl = (assetId: string, version?: number): string =>
  `/api/academy/media-assets/${encodeURIComponent(assetId)}/file${
    version ? `?version=${encodeURIComponent(String(version))}` : ""
  }`;

const buildAcademyMediaPosterUrl = (
  assetId: string,
  version?: number,
): string =>
  `/api/academy/media-assets/${encodeURIComponent(assetId)}/poster${
    version ? `?version=${encodeURIComponent(String(version))}` : ""
  }`;

const loadAcademyMediaManifest =
  async (): Promise<AcademyStoredMediaManifest> => {
    if (academyMediaManifestCache) {
      return academyMediaManifestCache;
    }

    try {
      const raw = await fs.readFile(ACADEMY_MEDIA_MANIFEST_PATH, "utf8");
      const parsed = JSON.parse(raw) as Partial<AcademyStoredMediaManifest>;
      academyMediaManifestCache = {
        version: 1,
        updatedAt:
          String(parsed.updatedAt || "").trim() || new Date().toISOString(),
        assets: Array.isArray(parsed.assets) ? parsed.assets : [],
      };
      return academyMediaManifestCache;
    } catch (error) {
      const code =
        typeof error === "object" && error !== null && "code" in error
          ? String((error as { code?: string }).code || "")
          : "";
      if (code && code !== "ENOENT") {
        console.warn("[academy-media] failed to read manifest:", error);
      }
      academyMediaManifestCache = createDefaultAcademyMediaManifest();
      return academyMediaManifestCache;
    }
  };

const persistAcademyMediaManifest = async (
  manifest: AcademyStoredMediaManifest,
): Promise<void> => {
  academyMediaManifestCache = manifest;
  academyMediaManifestWritePromise = academyMediaManifestWritePromise
    .catch(() => undefined)
    .then(async () => {
      await fs.mkdir(ACADEMY_MEDIA_STORAGE_DIR, { recursive: true });
      await fs.writeFile(
        ACADEMY_MEDIA_MANIFEST_PATH,
        JSON.stringify(manifest, null, 2),
        "utf8",
      );
    })
    .catch((error) => {
      const message = error instanceof Error ? error.message : String(error);
      console.warn("[academy-media] failed to persist manifest:", message);
    });

  await academyMediaManifestWritePromise;
};

const extractAcademyMediaPoster = async (params: {
  assetId: string;
  version: number;
  videoFilePath: string;
  versionDir: string;
  durationSeconds?: number;
}): Promise<{ relativePath: string; mimeType: string } | null> => {
  const outputPath = path.join(params.versionDir, "poster.jpg");
  const seekSeconds =
    Number.isFinite(Number(params.durationSeconds)) &&
    Number(params.durationSeconds) > 0
      ? Math.min(2.5, Math.max(0.2, Number(params.durationSeconds) * 0.15))
      : 0.25;

  const primaryAttempt = await runBinaryCommand(
    FFMPEG_BINARY,
    [
      "-y",
      "-ss",
      seekSeconds.toFixed(3),
      "-i",
      params.videoFilePath,
      "-frames:v",
      "1",
      "-vf",
      "scale=1280:-2:force_original_aspect_ratio=decrease",
      outputPath,
    ],
    90_000,
  );

  if (primaryAttempt.code !== 0 || !existsSync(outputPath)) {
    const fallbackAttempt = await runBinaryCommand(
      FFMPEG_BINARY,
      [
        "-y",
        "-i",
        params.videoFilePath,
        "-frames:v",
        "1",
        "-vf",
        "scale=1280:-2:force_original_aspect_ratio=decrease",
        outputPath,
      ],
      90_000,
    );

    if (fallbackAttempt.code !== 0 || !existsSync(outputPath)) {
      return null;
    }
  }

  return {
    relativePath: path.join(params.assetId, `v${params.version}`, "poster.jpg"),
    mimeType: "image/jpeg",
  };
};

const persistAcademyMediaVersion = async (params: {
  assetId: string;
  version: number;
  file: {
    originalname: string;
    mimetype: string;
    buffer: Buffer;
    size: number;
  };
  type: AcademyStoredMediaType;
}): Promise<AcademyStoredMediaVersionRecord> => {
  await fs.mkdir(ACADEMY_MEDIA_STORAGE_DIR, { recursive: true });
  const versionDir = path.join(
    ACADEMY_MEDIA_STORAGE_DIR,
    params.assetId,
    `v${params.version}`,
  );
  await fs.mkdir(versionDir, { recursive: true });

  const extension =
    path.extname(params.file.originalname || "").toLowerCase() ||
    (params.type === "video"
      ? ".mp4"
      : params.type === "audio"
        ? ".mp3"
        : params.type === "image"
          ? ".jpg"
          : ".bin");
  const safeBaseName = sanitizeAcademyMediaName(
    path.basename(params.file.originalname || "academy-media", extension),
  );
  const storedFileName = `${safeBaseName}${extension}`;
  const targetPath = path.join(versionDir, storedFileName);

  await fs.writeFile(targetPath, params.file.buffer);

  let durationSeconds: number | undefined;
  if (params.type === "video") {
    try {
      const probedDuration = await probeVideoDurationSeconds(targetPath);
      if (Number.isFinite(probedDuration) && probedDuration > 0) {
        durationSeconds = probedDuration;
      }
    } catch {
      durationSeconds = undefined;
    }
  }

  const poster =
    params.type === "video"
      ? await extractAcademyMediaPoster({
          assetId: params.assetId,
          version: params.version,
          videoFilePath: targetPath,
          versionDir,
          durationSeconds,
        })
      : null;

  return {
    version: params.version,
    fileName: params.file.originalname || storedFileName,
    mimeType:
      String(params.file.mimetype || "").trim() || "application/octet-stream",
    size: params.file.size,
    duration: durationSeconds,
    fingerprint: computeAcademyMediaFingerprint(params.file.buffer),
    updatedAt: new Date().toISOString(),
    relativePath: path.join(
      params.assetId,
      `v${params.version}`,
      storedFileName,
    ),
    posterRelativePath: poster?.relativePath,
    posterMimeType: poster?.mimeType,
  };
};

const resolveAcademyMediaVersion = (
  record: AcademyStoredMediaAssetRecord,
  requestedVersion?: number,
): AcademyStoredMediaVersionRecord | null => {
  if (!requestedVersion || requestedVersion === record.currentVersion.version) {
    return record.currentVersion;
  }
  return (
    record.history.find((entry) => entry.version === requestedVersion) || null
  );
};

const mapAcademyStoredMediaRecordToResponse = (
  record: AcademyStoredMediaAssetRecord,
  requestedVersion?: number,
) => {
  const versionRecord =
    resolveAcademyMediaVersion(record, requestedVersion) ||
    record.currentVersion;
  return {
    id: record.id,
    name: record.name,
    type: record.type,
    url: buildAcademyMediaFileUrl(record.id, versionRecord.version),
    posterUrl: versionRecord.posterRelativePath
      ? buildAcademyMediaPosterUrl(record.id, versionRecord.version)
      : undefined,
    size: versionRecord.size,
    duration: versionRecord.duration,
    updatedAt: versionRecord.updatedAt,
    tags: record.tags,
    source: "upload" as const,
    courseId: record.courseId,
    lessonId: record.lessonId,
    version: versionRecord.version,
    fingerprint: versionRecord.fingerprint,
  };
};

const normalizeWordToken = (value: unknown): string => {
  const raw = readString(value);
  if (!raw) {
    return "";
  }
  return raw.replace(/\s+/g, " ").trim();
};

const buildWordTimestampsFromSegments = (
  segments: VideoAnalysisCaptionSegment[],
): VideoAnalysisWordTimestamp[] => {
  const words: VideoAnalysisWordTimestamp[] = [];
  segments.forEach((segment) => {
    const tokens = segment.text
      .split(/\s+/)
      .map((token) => normalizeWordToken(token))
      .filter(Boolean);
    if (tokens.length === 0) {
      return;
    }
    const span = Math.max(0.04, segment.end - segment.start);
    const wordDuration = span / tokens.length;
    tokens.forEach((word, index) => {
      const start = Number((segment.start + wordDuration * index).toFixed(3));
      const end =
        index === tokens.length - 1
          ? Number(segment.end.toFixed(3))
          : Number((segment.start + wordDuration * (index + 1)).toFixed(3));
      words.push({
        word,
        start,
        end: end >= start ? end : start,
        confidence: segment.confidence,
        speaker: segment.speaker || null,
      });
    });
  });
  return words;
};

const normalizeTranscriptionWords = (
  rawWords: unknown,
  segments: VideoAnalysisCaptionSegment[],
): VideoAnalysisWordTimestamp[] => {
  if (!Array.isArray(rawWords)) {
    return buildWordTimestampsFromSegments(segments);
  }
  const normalized: VideoAnalysisWordTimestamp[] = [];
  rawWords.forEach((entry) => {
    if (!isRecord(entry)) {
      return;
    }
    const word = normalizeWordToken(entry.word || entry.text || entry.token);
    const startRaw = readNumber(
      entry.start ?? entry.start_time ?? entry.begin ?? null,
    );
    const endRaw = readNumber(
      entry.end ?? entry.end_time ?? entry.stop ?? null,
    );
    if (!word || startRaw === null) {
      return;
    }
    const fallbackDuration = 0.16;
    const endCandidate = endRaw !== null ? endRaw : startRaw + fallbackDuration;
    const confidence = readNumber(entry.confidence);
    const speaker = readString(entry.speaker ?? entry.speakerName ?? null);
    normalized.push({
      word,
      start: Number(Math.max(0, startRaw).toFixed(3)),
      end: Number(Math.max(startRaw, endCandidate).toFixed(3)),
      confidence:
        confidence === null
          ? null
          : Number(Math.max(0, Math.min(1, confidence)).toFixed(3)),
      speaker: speaker || null,
    });
  });
  normalized.sort((left, right) => left.start - right.start);

  if (normalized.length > 0) {
    return normalized;
  }
  return buildWordTimestampsFromSegments(segments);
};

interface VideoAnalysisTranscriptionApiResponse {
  transcription: VideoAnalysisTranscriptionResult;
  warnings: string[];
  diarizationSegments: VideoAnalysisDiarizationSegment[];
  provider: "whisperx" | "whisper" | "fallback";
  alignmentProvider: "whisperx" | "none";
}

const normalizeDiarizationSegments = (
  payload: unknown,
): VideoAnalysisDiarizationSegment[] => {
  if (!isRecord(payload)) {
    return [];
  }

  const data = isRecord(payload.data) ? payload.data : payload;
  const sourceSegments = Array.isArray(data.segments) ? data.segments : [];

  return sourceSegments
    .map((entry) => {
      if (!isRecord(entry)) return null;
      const start = readNumber(entry.start ?? entry.start_time ?? null);
      const end = readNumber(entry.end ?? entry.end_time ?? null);
      const speaker = readString(entry.speaker ?? entry.speakerName ?? null);
      if (start === null || end === null || !speaker) return null;
      const confidence = readNumber(
        entry.confidence ?? entry.speech_confidence ?? null,
      );
      return {
        start: Number(Math.max(0, start).toFixed(3)),
        end: Number(Math.max(start, end).toFixed(3)),
        speaker,
        duration: Number(Math.max(0, end - start).toFixed(3)),
        confidence:
          confidence === null
            ? null
            : Number(Math.max(0, Math.min(1, confidence)).toFixed(3)),
      };
    })
    .filter((entry): entry is VideoAnalysisDiarizationSegment => Boolean(entry))
    .sort((left, right) => left.start - right.start);
};

const calculateIntervalOverlap = (
  leftStart: number,
  leftEnd: number,
  rightStart: number,
  rightEnd: number,
): number => {
  const overlap = Math.min(leftEnd, rightEnd) - Math.max(leftStart, rightStart);
  return overlap > 0 ? overlap : 0;
};

const getBestSpeakerMatch = (
  start: number,
  end: number,
  diarizationSegments: VideoAnalysisDiarizationSegment[],
): { speaker: string; confidence: number } | null => {
  if (!(end > start) || diarizationSegments.length === 0) {
    return null;
  }

  const intervalDuration = Math.max(0.001, end - start);
  let bestScore = 0;
  let bestMatch: { speaker: string; confidence: number } | null = null;

  for (const segment of diarizationSegments) {
    const overlap = calculateIntervalOverlap(
      start,
      end,
      segment.start,
      segment.end,
    );
    if (overlap <= 0) {
      continue;
    }
    const overlapRatio = Math.max(0, Math.min(1, overlap / intervalDuration));
    const baseConfidence =
      segment.confidence === null ? 0.75 : segment.confidence;
    const score = overlapRatio * 0.7 + baseConfidence * 0.3;
    if (score > bestScore) {
      bestScore = score;
      bestMatch = {
        speaker: segment.speaker,
        confidence: Number(Math.max(0, Math.min(1, score)).toFixed(3)),
      };
    }
  }

  return bestMatch;
};

const applyDiarizationToTranscription = (
  transcription: VideoAnalysisTranscriptionResult,
  diarizationSegments: VideoAnalysisDiarizationSegment[],
): VideoAnalysisTranscriptionResult => {
  if (diarizationSegments.length === 0) {
    return transcription;
  }

  const nextSegments: VideoAnalysisCaptionSegment[] =
    transcription.segments.map((segment) => {
      const match = getBestSpeakerMatch(
        segment.start,
        segment.end,
        diarizationSegments,
      );
      if (!match) {
        return segment;
      }
      return {
        ...segment,
        speaker: match.speaker,
        speaker_confidence: match.confidence,
      };
    });

  const nextWords: VideoAnalysisWordTimestamp[] = transcription.words.map(
    (word) => {
      const match = getBestSpeakerMatch(
        word.start,
        word.end,
        diarizationSegments,
      );
      if (!match) {
        return word;
      }
      return {
        ...word,
        speaker: match.speaker,
        confidence:
          word.confidence === null
            ? match.confidence
            : Number(
                Math.max(
                  0,
                  Math.min(1, (word.confidence + match.confidence) / 2),
                ).toFixed(3),
              ),
      };
    },
  );

  return {
    ...transcription,
    segments: nextSegments,
    words: nextWords,
  };
};

const createAbortSignalWithTimeout = (
  timeoutMs: number,
  parentSignal?: AbortSignal,
): { signal: AbortSignal; cleanup: () => void } => {
  const controller = new AbortController();
  const timeoutRef = setTimeout(() => {
    controller.abort();
  }, timeoutMs);
  const abortFromParent = () => controller.abort();

  if (parentSignal) {
    if (parentSignal.aborted) {
      controller.abort();
    } else {
      parentSignal.addEventListener("abort", abortFromParent, { once: true });
    }
  }

  return {
    signal: controller.signal,
    cleanup: () => {
      clearTimeout(timeoutRef);
      if (parentSignal) {
        parentSignal.removeEventListener("abort", abortFromParent);
      }
    },
  };
};

const waitForStoryArcWarmupBackoff = (delayMs: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, Math.max(1, delayMs));
  });

const requestPyannoteWarmup = async (
  reason: string,
): Promise<{
  statusCode: number;
  payload: Record<string, unknown>;
}> => {
  const response = await fetch(`${PYANNOTE_DIARIZATION_URL}/warmup`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      reason,
      requestedAt: new Date().toISOString(),
    }),
    signal: AbortSignal.timeout(STORY_ARC_V2_STARTUP_WARMUP_TIMEOUT_MS),
  });
  const payload = (await response.json().catch(() => ({}))) as Record<
    string,
    unknown
  >;
  if (!response.ok) {
    const error =
      readString(payload.error) ||
      readString(payload.message) ||
      `Warmup failed (${response.status})`;
    throw new Error(error);
  }
  return {
    statusCode: response.status,
    payload,
  };
};

const requestWhisperxWarmup = async (
  reason: string,
): Promise<{
  statusCode: number;
  payload: Record<string, unknown>;
}> => {
  const response = await fetch(`${WHISPERX_TRANSCRIPTION_URL}/warmup`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
    },
    body: JSON.stringify({
      reason,
      requestedAt: new Date().toISOString(),
    }),
    signal: AbortSignal.timeout(STORY_ARC_V2_STARTUP_WARMUP_TIMEOUT_MS),
  });
  const payload = (await response.json().catch(() => ({}))) as Record<
    string,
    unknown
  >;
  if (!response.ok) {
    const error =
      readString(payload.error) ||
      readString(payload.message) ||
      `Warmup failed (${response.status})`;
    throw new Error(error);
  }
  return {
    statusCode: response.status,
    payload,
  };
};

const runStoryArcV2StartupWarmup = async (): Promise<void> => {
  if (!STORY_ARC_V2_STARTUP_WARMUP_ENABLED) {
    return;
  }
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder("analyze", {
    operation: "startup_warmup",
    target: PYANNOTE_DIARIZATION_URL,
  });
  let lastError = "";
  for (
    let attempt = 1;
    attempt <= STORY_ARC_V2_STARTUP_WARMUP_RETRIES;
    attempt += 1
  ) {
    try {
      const warmup = await requestPyannoteWarmup("backend-startup");
      let whisperxStatus = "skipped";
      if (VIDEO_ANALYSIS_WHISPERX_ENABLED) {
        try {
          await requestWhisperxWarmup("backend-startup");
          whisperxStatus = "ok";
        } catch (error) {
          whisperxStatus = "degraded";
          const message =
            error instanceof Error ? error.message : String(error);
          console.warn(`[story-arc-v2] whisperx warmup failed: ${message}`);
        }
      }
      completePhaseMetric("completed", {
        attempt,
        statusCode: warmup.statusCode,
        warmupStatus: readString(warmup.payload.status) || "ok",
        whisperxStatus,
      });
      console.log(
        `[story-arc-v2] pyannote warmup succeeded (attempt ${attempt}/${STORY_ARC_V2_STARTUP_WARMUP_RETRIES})`,
      );
      return;
    } catch (error) {
      lastError = error instanceof Error ? error.message : String(error);
      console.warn(
        `[story-arc-v2] pyannote warmup failed (attempt ${attempt}/${STORY_ARC_V2_STARTUP_WARMUP_RETRIES}): ${lastError}`,
      );
      if (attempt < STORY_ARC_V2_STARTUP_WARMUP_RETRIES) {
        await waitForStoryArcWarmupBackoff(
          STORY_ARC_V2_STARTUP_WARMUP_BACKOFF_MS * attempt,
        );
      }
    }
  }
  completePhaseMetric("failed", {
    attempt: STORY_ARC_V2_STARTUP_WARMUP_RETRIES,
    error: lastError || "warmup_failed",
  });
};

const requestDiarizationViaLocalApi = async (
  audioPath: string,
  signal?: AbortSignal,
): Promise<VideoAnalysisDiarizationSegment[]> => {
  if (!VIDEO_ANALYSIS_DIARIZATION_ENABLED) {
    return [];
  }

  const audioBuffer = await fs.readFile(audioPath);
  const fileName = path.basename(audioPath);
  const form = new FormData();
  form.append(
    "file",
    new Blob([audioBuffer], { type: "audio/mpeg" }),
    fileName,
  );

  const { signal: requestSignal, cleanup } = createAbortSignalWithTimeout(
    VIDEO_ANALYSIS_DIARIZATION_TIMEOUT_MS,
    signal,
  );
  try {
    const response = await fetch(
      `${PYANNOTE_DIARIZATION_URL}/v1/audio/diarization`,
      {
        method: "POST",
        body: form,
        signal: requestSignal,
      },
    );
    if (!response.ok) {
      const body = await response.text().catch(() => "");
      throw new Error(`Diarization failed (${response.status}): ${body}`);
    }
    const payload = await response.json();
    return normalizeDiarizationSegments(payload);
  } finally {
    cleanup();
  }
};

const normalizeTranscriptionResult = (
  payload: unknown,
  fallbackLanguage: string,
): VideoAnalysisTranscriptionResult => {
  if (!isRecord(payload)) {
    throw new Error("Transcription response was not an object");
  }

  const data = isRecord(payload.data) ? payload.data : payload;
  const text = readString(data.text) || "";
  const language = readString(data.language) || fallbackLanguage;
  const durationRaw = Number(data.duration);
  const duration =
    Number.isFinite(durationRaw) && durationRaw >= 0 ? durationRaw : null;

  const sourceSegments = Array.isArray(data.segments) ? data.segments : [];
  const segments: VideoAnalysisCaptionSegment[] = [];
  sourceSegments.forEach((segment, index) => {
    if (!isRecord(segment)) return;
    const start = Number(segment.start);
    const end = Number(segment.end);
    const segText = readString(segment.text) || "";
    if (!Number.isFinite(start) || !Number.isFinite(end) || !segText) return;

    const confidenceRaw = Number(segment.confidence);
    const confidence = Number.isFinite(confidenceRaw)
      ? Math.max(0, Math.min(1, confidenceRaw))
      : 1;
    const speaker =
      readString(segment.speaker) || readString(segment.speakerName) || null;

    segments.push({
      id: Number.isFinite(Number(segment.id)) ? Number(segment.id) : index + 1,
      start,
      end: end >= start ? end : start,
      text: segText,
      confidence,
      speaker,
      speaker_confidence: speaker ? confidence : null,
    });
  });

  const words = normalizeTranscriptionWords(data.words, segments);
  const normalizedText =
    text ||
    segments
      .map((segment) => segment.text)
      .join(" ")
      .trim();

  return {
    text: normalizedText,
    language,
    duration,
    segments,
    words,
  };
};

const extractTranscriptionWarnings = (payload: unknown): string[] => {
  if (!isRecord(payload)) {
    return [];
  }
  const sourceWarnings =
    isRecord(payload.data) && Array.isArray(payload.data.warnings)
      ? payload.data.warnings
      : Array.isArray(payload.warnings)
        ? payload.warnings
        : [];
  return sourceWarnings
    .map((warning) => readString(warning))
    .filter((warning): warning is string => Boolean(warning));
};

const requestTranscriptionViaWhisperXLocalApi = async (
  audioBuffer: Buffer,
  fileName: string,
  languageHint: string | null,
  signal?: AbortSignal,
): Promise<{
  transcription: VideoAnalysisTranscriptionResult;
  warnings: string[];
}> => {
  const form = new FormData();
  // @ts-ignore: Buffer satisfies BlobPart at runtime
  form.append("file", new Blob([audioBuffer], { type: "audio/wav" }), fileName);
  if (languageHint) {
    form.append("language", languageHint);
  }
  form.append("response_format", "verbose_json");
  form.append("timestamp_granularities", "word,segment");

  const { signal: requestSignal, cleanup } = createAbortSignalWithTimeout(
    VIDEO_ANALYSIS_WHISPERX_TIMEOUT_MS,
    signal,
  );

  try {
    const response = await fetch(
      `${WHISPERX_TRANSCRIPTION_URL}/v1/audio/transcriptions`,
      {
        method: "POST",
        body: form,
        signal: requestSignal,
      },
    );
    if (!response.ok) {
      const body = await response.text().catch(() => "");
      throw new Error(`WhisperX failed (${response.status}): ${body}`);
    }
    const payload = await response.json();
    return {
      transcription: normalizeTranscriptionResult(
        payload,
        languageHint || "auto",
      ),
      warnings: extractTranscriptionWarnings(payload),
    };
  } finally {
    cleanup();
  }
};

const requestTranscriptionViaLocalApi = async (
  audioPath: string,
  languageHint: string | null,
  signal?: AbortSignal,
): Promise<VideoAnalysisTranscriptionApiResponse> => {
  const warnings: string[] = [];
  const audioBuffer = await fs.readFile(audioPath);
  const fileName = path.basename(audioPath);
  let provider: VideoAnalysisTranscriptionApiResponse["provider"] = "fallback";
  let alignmentProvider: VideoAnalysisTranscriptionApiResponse["alignmentProvider"] =
    "none";

  let transcription: VideoAnalysisTranscriptionResult | null = null;
  if (VIDEO_ANALYSIS_WHISPERX_ENABLED) {
    try {
      const whisperXResult = await requestTranscriptionViaWhisperXLocalApi(
        audioBuffer,
        fileName,
        languageHint,
        signal,
      );
      const normalizedWhisperX = whisperXResult.transcription;
      const whisperXHasText = normalizedWhisperX.text.trim().length > 0;
      const whisperXHasSegments = normalizedWhisperX.segments.length > 0;
      if (whisperXHasText || whisperXHasSegments) {
        transcription = normalizedWhisperX;
        provider = "whisperx";
        alignmentProvider = "whisperx";
      } else {
        appendWarning(
          warnings,
          "WhisperX returned empty transcription; attempting Whisper fallback",
        );
      }
      whisperXResult.warnings.forEach((warning) =>
        appendWarning(warnings, warning),
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown WhisperX request error";
      appendWarning(
        warnings,
        `WhisperX unavailable: ${message}; attempting Whisper fallback`,
      );
    }
  } else {
    appendWarning(warnings, "WhisperX is disabled; using Whisper fallback");
  }

  if (!transcription) {
    const whisperForm = new FormData();
    whisperForm.append(
      "audio",
      new Blob([audioBuffer], { type: "audio/mpeg" }),
      fileName,
    );
    if (languageHint) {
      whisperForm.append("language", languageHint);
    }
    whisperForm.append("response_format", "verbose_json");
    whisperForm.append("timestamp_granularities", "word,segment");

    const whisperSignal = createAbortSignalWithTimeout(240_000, signal);
    let whisperResponse: Response | null = null;
    try {
      whisperResponse = await fetch(
        `http://127.0.0.1:${PORT}/api/ai/whisper-transcribe`,
        {
          method: "POST",
          body: whisperForm,
          signal: whisperSignal.signal,
        },
      );
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : "Unknown whisper request error";
      appendWarning(
        warnings,
        `Whisper request error: ${message}; attempting fallback transcriber`,
      );
    } finally {
      whisperSignal.cleanup();
    }

    if (whisperResponse?.ok) {
      const whisperPayload = await whisperResponse.json();
      const normalizedWhisper = normalizeTranscriptionResult(
        whisperPayload,
        languageHint || "auto",
      );
      const whisperHasText = normalizedWhisper.text.trim().length > 0;
      const whisperHasSegments = normalizedWhisper.segments.length > 0;

      if (whisperHasText || whisperHasSegments) {
        transcription = normalizedWhisper;
        provider = "whisper";
      } else {
        appendWarning(
          warnings,
          "Whisper returned empty transcription; attempting fallback transcriber",
        );
      }
    } else {
      appendWarning(
        warnings,
        whisperResponse
          ? `Whisper request failed (${whisperResponse.status}); attempting fallback transcriber`
          : "Whisper request unavailable; attempting fallback transcriber",
      );
    }
  }

  if (!transcription) {
    const fallbackForm = new FormData();
    fallbackForm.append(
      "audio",
      new Blob([audioBuffer], { type: "audio/mpeg" }),
      fileName,
    );
    if (languageHint) {
      fallbackForm.append("language", languageHint);
    }
    const fallbackSignal = createAbortSignalWithTimeout(240_000, signal);

    const fallbackResponse = await fetch(
      `http://127.0.0.1:${PORT}/api/ai/transcribe`,
      {
        method: "POST",
        body: fallbackForm,
        signal: fallbackSignal.signal,
      },
    ).finally(() => {
      fallbackSignal.cleanup();
    });

    if (!fallbackResponse.ok) {
      const fallbackError = await fallbackResponse.text().catch(() => "");
      throw new Error(
        `Transcription failed (${fallbackResponse.status}): ${fallbackError}`,
      );
    }

    const fallbackPayload = await fallbackResponse.json();
    transcription = normalizeTranscriptionResult(
      fallbackPayload,
      languageHint || "auto",
    );
    provider = "fallback";
    alignmentProvider = "none";
  }

  if (!transcription) {
    throw new Error("Transcription pipeline returned no result");
  }

  let diarizationSegments: VideoAnalysisDiarizationSegment[] = [];
  if (transcription.segments.length > 0 && VIDEO_ANALYSIS_DIARIZATION_ENABLED) {
    try {
      diarizationSegments = await requestDiarizationViaLocalApi(
        audioPath,
        signal,
      );
      if (diarizationSegments.length > 0) {
        transcription = applyDiarizationToTranscription(
          transcription,
          diarizationSegments,
        );
      } else {
        appendWarning(warnings, "Diarization returned no speaker segments");
      }
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Diarization unavailable";
      appendWarning(warnings, `Speaker diarization unavailable: ${message}`);
    }
  }

  return {
    transcription,
    warnings,
    diarizationSegments,
    provider,
    alignmentProvider,
  };
};

const sanitizeOcrLine = (line: string): string => {
  const cleaned = line
    .replace(/[^\p{L}\p{N}\s.,!?;:'"()\-+&/]/gu, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (cleaned.length < 4 || cleaned.length > 140) return "";

  const letters = cleaned.match(/\p{L}/gu) || [];
  if (letters.length < 3) return "";
  const letterDensity = letters.length / cleaned.length;
  if (letterDensity < 0.3) return "";

  const normalizedTokens = cleaned
    .split(" ")
    .map((token) =>
      token.replace(/^[^\p{L}\p{N}]+/gu, "").replace(/[^\p{L}\p{N}]+$/gu, ""),
    )
    .filter(Boolean);
  if (normalizedTokens.length === 0) return "";

  const alphaTokens = normalizedTokens.filter((token) =>
    /^\p{L}+$/u.test(token),
  );
  if (alphaTokens.length === 0) return "";

  const longAlphaTokens = alphaTokens.filter((token) => token.length >= 4);
  if (alphaTokens.length > 1 && longAlphaTokens.length === 0) return "";

  if (alphaTokens.length >= 3) {
    const shortRatio =
      alphaTokens.filter((token) => token.length <= 2).length /
      alphaTokens.length;
    if (shortRatio > 0.5) return "";
  }

  const vowelCount = (cleaned.match(/[aeiouyAEIOUY]/g) || []).length;
  const vowelRatio = vowelCount / letters.length;
  if (vowelRatio < 0.15 || vowelRatio > 0.85) return "";

  const hasWord = /\p{L}{3,}/u.test(cleaned);
  return hasWord ? cleaned : "";
};

const extractOcrTextLines = (output: string): string[] => {
  const normalized = output.replace(/\r/g, "");
  const blocks: string[] = [];
  const matcher =
    /lavfi\.ocr\.text=([\s\S]*?)(?=\n\[Parsed_metadata_[^\n]*lavfi\.ocr\.confidence=|\nframe=\s*\d+|$)/g;

  let match = matcher.exec(normalized);
  while (match) {
    blocks.push(match[1]);
    match = matcher.exec(normalized);
  }

  const cleanedLines = blocks
    .flatMap((block) => block.split("\n"))
    .map((line) => sanitizeOcrLine(line))
    .filter(Boolean);

  return uniqueStrings(cleanedLines).slice(0, 24);
};

let tesseractLanguagesCache: Set<string> | null = null;

const getInstalledTesseractLanguages = async (): Promise<Set<string>> => {
  if (tesseractLanguagesCache) {
    return tesseractLanguagesCache;
  }

  const result = await runBinaryCommand(
    TESSERACT_BINARY,
    ["--list-langs"],
    10_000,
  );
  if (result.code !== 0) {
    tesseractLanguagesCache = new Set<string>();
    return tesseractLanguagesCache;
  }

  const lines = `${result.stdout}\n${result.stderr}`
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

  const languageEntries = lines.filter(
    (line) => !/list of available languages/i.test(line),
  );
  tesseractLanguagesCache = new Set(languageEntries);
  return tesseractLanguagesCache;
};

const getTesseractLanguageCandidates = async (
  languageHint: string | null,
): Promise<string[]> => {
  const requested = normalizeWhisperLanguage(languageHint || "");
  const mapped: Record<string, string[]> = {
    no: ["nor", "eng"],
    en: ["eng"],
    es: ["spa", "eng"],
    fr: ["fra", "eng"],
    de: ["deu", "eng"],
    it: ["ita", "eng"],
    pt: ["por", "eng"],
    zh: ["chi_sim", "eng"],
    ja: ["jpn", "eng"],
    ko: ["kor", "eng"],
    ar: ["ara", "eng"],
    hi: ["hin", "eng"],
  };

  const installed = await getInstalledTesseractLanguages();
  if (!requested || requested === "auto") {
    const installedList = Array.from(installed);
    const prioritized = [
      "eng",
      "nor",
      "spa",
      "fra",
      "deu",
      "ita",
      "por",
      "jpn",
      "kor",
      "chi_sim",
    ].filter((code) => installed.has(code));
    return Array.from(new Set([...prioritized, ...installedList])).slice(0, 8);
  }

  const preferred = mapped[requested] || [requested, "eng"];
  const available = preferred.filter((code) => installed.has(code));

  if (available.length > 0) {
    return available;
  }
  if (installed.has("eng")) {
    return ["eng"];
  }
  return preferred;
};

const detectOnscreenTextViaTesseract = async (
  stagedVideoPath: string,
  languageHint: string | null,
): Promise<{ detectedText: string[]; warnings: string[] }> => {
  const warnings: string[] = [];
  const detected = new Set<string>();
  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "storyarc-ocr-"));

  try {
    const languageCandidates =
      await getTesseractLanguageCandidates(languageHint);
    const extractionFilters = [
      "fps=1/2,crop=iw:ih*0.28:0:ih*0.72,scale=1280:-2:force_original_aspect_ratio=decrease",
      "fps=1/2,crop=iw:ih*0.28:0:0,scale=1280:-2:force_original_aspect_ratio=decrease",
      "fps=1/3,scale=1280:-2:force_original_aspect_ratio=decrease",
    ];

    for (
      let filterIndex = 0;
      filterIndex < extractionFilters.length;
      filterIndex += 1
    ) {
      const framesPattern = path.join(
        tempDir,
        `ocr-pass-${filterIndex}-%03d.jpg`,
      );
      const frameExtractResult = await runBinaryCommand(
        FFMPEG_BINARY,
        [
          "-hide_banner",
          "-loglevel",
          "error",
          "-y",
          "-t",
          "30",
          "-i",
          stagedVideoPath,
          "-vf",
          extractionFilters[filterIndex],
          "-q:v",
          "3",
          framesPattern,
        ],
        180_000,
      );

      if (frameExtractResult.timedOut) {
        appendWarning(warnings, "Tesseract OCR frame extraction timed out");
        continue;
      }
      if (frameExtractResult.code !== 0) {
        appendWarning(warnings, "Tesseract OCR frame extraction failed");
        continue;
      }

      const frameFiles = (await fs.readdir(tempDir))
        .filter(
          (name) =>
            name.startsWith(`ocr-pass-${filterIndex}-`) &&
            name.endsWith(".jpg"),
        )
        .sort()
        .slice(0, 20)
        .map((name) => path.join(tempDir, name));

      for (const framePath of frameFiles) {
        for (const languageCode of languageCandidates) {
          const commandResult = await runBinaryCommand(
            TESSERACT_BINARY,
            [framePath, "stdout", "--psm", "7", "-l", languageCode],
            30_000,
          );

          if (commandResult.timedOut) {
            appendWarning(warnings, "Tesseract OCR timed out on one frame");
            break;
          }
          if (commandResult.code !== 0) {
            continue;
          }

          const lines = commandResult.stdout
            .split("\n")
            .map((line) => sanitizeOcrLine(line))
            .filter(Boolean);

          for (const line of lines) {
            detected.add(line);
          }

          if (lines.length > 0) {
            break;
          }
        }

        if (detected.size >= 24) {
          break;
        }
      }

      if (detected.size >= 24) {
        break;
      }
    }

    if (detected.size === 0) {
      appendWarning(warnings, "Tesseract OCR did not detect on-screen text");
    }

    return {
      detectedText: Array.from(detected).slice(0, 24),
      warnings,
    };
  } finally {
    await fs.rm(tempDir, { recursive: true, force: true });
  }
};

const detectOnscreenTextFromVideo = async (
  stagedVideoPath: string,
  languageHint: string | null,
): Promise<{ detectedText: string[]; warnings: string[] }> => {
  const warnings: string[] = [];
  const detected = new Set<string>();
  let ffmpegOcrUnavailable = false;

  const ocrPasses = [
    "fps=1/2,crop=iw:ih*0.28:0:ih*0.72,ocr,metadata=mode=print:file=-",
    "fps=1/2,crop=iw:ih*0.28:0:0,ocr,metadata=mode=print:file=-",
    "fps=1/3,ocr,metadata=mode=print:file=-",
  ];

  for (const filter of ocrPasses) {
    const commandResult = await runBinaryCommand(
      FFMPEG_BINARY,
      [
        "-hide_banner",
        "-loglevel",
        "info",
        "-t",
        "30",
        "-i",
        stagedVideoPath,
        "-vf",
        filter,
        "-f",
        "null",
        "-",
      ],
      180_000,
    );

    if (commandResult.timedOut) {
      appendWarning(warnings, "OCR pass timed out and was skipped");
      continue;
    }

    const combinedOutput = `${commandResult.stdout}\n${commandResult.stderr}`;

    if (commandResult.code !== 0) {
      if (/no such filter:\s*'?ocr'?/i.test(combinedOutput)) {
        ffmpegOcrUnavailable = true;
        appendWarning(
          warnings,
          "FFmpeg was built without OCR filter; using Tesseract fallback for text detection",
        );
        break;
      }
      appendWarning(
        warnings,
        `OCR pass failed (code ${commandResult.code}); continuing with other passes`,
      );
      continue;
    }

    const passTexts = extractOcrTextLines(combinedOutput);
    for (const entry of passTexts) {
      detected.add(entry);
    }

    if (detected.size >= 16) {
      break;
    }
  }

  if (detected.size === 0 || ffmpegOcrUnavailable) {
    const tesseractResult = await detectOnscreenTextViaTesseract(
      stagedVideoPath,
      languageHint,
    );
    for (const entry of tesseractResult.detectedText) {
      detected.add(entry);
    }
    tesseractResult.warnings.forEach((warning) =>
      appendWarning(warnings, warning),
    );
  }

  return {
    detectedText: Array.from(detected).slice(0, 24),
    warnings,
  };
};

const toCaptionTimestamp = (
  seconds: number,
  decimalSeparator: "." | ",",
): string => {
  const normalized = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
  const totalMilliseconds = Math.round(normalized * 1000);
  const hours = Math.floor(totalMilliseconds / 3_600_000);
  const minutes = Math.floor((totalMilliseconds % 3_600_000) / 60_000);
  const secs = Math.floor((totalMilliseconds % 60_000) / 1000);
  const millis = totalMilliseconds % 1000;
  const hourStr = String(hours).padStart(2, "0");
  const minuteStr = String(minutes).padStart(2, "0");
  const secondStr = String(secs).padStart(2, "0");
  const millisecondStr = String(millis).padStart(3, "0");
  return `${hourStr}:${minuteStr}:${secondStr}${decimalSeparator}${millisecondStr}`;
};

const exportCaptionsToSrt = (
  segments: VideoAnalysisCaptionSegment[],
): string => {
  return segments
    .map(
      (segment, index) =>
        `${index + 1}\n${toCaptionTimestamp(segment.start, ",")} --> ${toCaptionTimestamp(
          segment.end,
          ",",
        )}\n${segment.text.trim()}\n`,
    )
    .join("\n");
};

const exportCaptionsToVtt = (
  segments: VideoAnalysisCaptionSegment[],
): string => {
  const body = segments
    .map(
      (segment) =>
        `${toCaptionTimestamp(segment.start, ".")} --> ${toCaptionTimestamp(
          segment.end,
          ".",
        )}\n${segment.text.trim()}\n`,
    )
    .join("\n");
  return `WEBVTT\n\n${body}`;
};

const createEmptyVideoAnalysisAudioTracks = (): VideoAnalysisAudioTracks => ({
  hasAudio: false,
  master: null,
  analysis: null,
  demucsRequested: VIDEO_ANALYSIS_ANALYSIS_TRACK_USE_DEMUCS,
  demucsApplied: false,
  demucsUsedModel: false,
  demucsModel: null,
});

const prepareVideoAnalysisAudioTracks = async (
  masterAudioPath: string,
  analysisAudioPath: string,
  warnings: string[],
  signal?: AbortSignal,
): Promise<VideoAnalysisAudioTracks> => {
  const tracks = createEmptyVideoAnalysisAudioTracks();
  tracks.hasAudio = true;
  tracks.master = {
    format: "wav",
    sampleRateHz: VIDEO_ANALYSIS_MASTER_TRACK_SAMPLE_RATE_HZ,
    channels: 1,
    source: "video_audio",
    durationSeconds: null,
  };
  tracks.analysis = {
    format: "wav",
    sampleRateHz: VIDEO_ANALYSIS_ANALYSIS_TRACK_SAMPLE_RATE_HZ,
    channels: 1,
    source: "master_fallback",
    durationSeconds: null,
  };

  let analysisReady = false;
  if (VIDEO_ANALYSIS_ANALYSIS_TRACK_USE_DEMUCS) {
    try {
      const demucsResult = await runAudioMixDemucsDenoise(
        masterAudioPath,
        analysisAudioPath,
        {
          demucsModel:
            readString(process.env.VIDEO_ANALYSIS_DEMUCS_MODEL) ||
            AUDIO_MIX_DEMUCS_MODEL,
          demucsDevice:
            readString(process.env.VIDEO_ANALYSIS_DEMUCS_DEVICE) ||
            AUDIO_MIX_DEMUCS_DEVICE,
          preEmphasisAlpha:
            readNumber(process.env.VIDEO_ANALYSIS_PRE_EMPHASIS_ALPHA) ?? 0.97,
          wienerFloor:
            readNumber(process.env.VIDEO_ANALYSIS_WIENER_FLOOR) ?? 0.05,
        },
      );
      tracks.demucsApplied = demucsResult.applied;
      tracks.demucsUsedModel = demucsResult.demucsUsed;
      tracks.demucsModel = demucsResult.model;
      if (demucsResult.applied) {
        tracks.analysis = {
          format: "wav",
          sampleRateHz: VIDEO_ANALYSIS_ANALYSIS_TRACK_SAMPLE_RATE_HZ,
          channels: 1,
          source: "demucs_vocals",
          durationSeconds: null,
        };
        analysisReady = true;
      } else if (demucsResult.warning) {
        appendWarning(warnings, `[analysis-track] ${demucsResult.warning}`);
      }
    } catch (error) {
      const message =
        error instanceof Error ? error.message : "Demucs preparation failed";
      appendWarning(warnings, `[analysis-track] demucs error: ${message}`);
    }
  }

  if (!analysisReady) {
    const normalizeAnalysisTrack = await runBinaryCommand(
      FFMPEG_BINARY,
      [
        "-hide_banner",
        "-loglevel",
        "error",
        "-y",
        "-i",
        masterAudioPath,
        "-ac",
        "1",
        "-ar",
        String(VIDEO_ANALYSIS_ANALYSIS_TRACK_SAMPLE_RATE_HZ),
        "-c:a",
        "pcm_s16le",
        analysisAudioPath,
      ],
      180_000,
      signal,
    );
    if (normalizeAnalysisTrack.timedOut) {
      throw new Error("Analysis track normalization timed out");
    }
    if (normalizeAnalysisTrack.code !== 0) {
      throw new Error(
        `Analysis track normalization failed: ${normalizeAnalysisTrack.stderr.slice(0, 400)}`,
      );
    }
  }

  return tracks;
};

const transcribeVideoSource = async (
  videoPath: string,
  languageHint: string | null,
  signal?: AbortSignal,
): Promise<VideoAnalysisJobResultTranscribe> => {
  const tempDir = await fs.mkdtemp(
    path.join(os.tmpdir(), "storyarc-transcribe-"),
  );
  const warnings: string[] = [];
  let diarizationSegments: VideoAnalysisDiarizationSegment[] = [];
  let audioTracks = createEmptyVideoAnalysisAudioTracks();
  let transcriptionProvider: VideoAnalysisJobResultTranscribe["transcription_provider"] =
    "fallback";
  let alignmentProvider: VideoAnalysisJobResultTranscribe["alignment_provider"] =
    "none";

  try {
    const stagedVideoPath = await stageVideoSource(videoPath, tempDir, signal);
    const masterAudioPath = path.join(tempDir, "audio-master.wav");
    const analysisAudioPath = path.join(tempDir, "audio-analysis.wav");
    let transcription: VideoAnalysisTranscriptionResult = {
      text: "",
      language: languageHint || "auto",
      duration: null,
      segments: [],
      words: [],
    };
    const extractAudioResult = await runBinaryCommand(
      FFMPEG_BINARY,
      [
        "-hide_banner",
        "-loglevel",
        "error",
        "-y",
        "-i",
        stagedVideoPath,
        "-vn",
        "-ac",
        "1",
        "-ar",
        String(VIDEO_ANALYSIS_MASTER_TRACK_SAMPLE_RATE_HZ),
        "-c:a",
        "pcm_s16le",
        masterAudioPath,
      ],
      180_000,
      signal,
    );

    if (extractAudioResult.timedOut) {
      throw new Error("Audio extraction timed out");
    }

    const noAudioStreamDetected =
      /does not contain any stream/i.test(extractAudioResult.stderr) ||
      /stream map .*matches no streams/i.test(extractAudioResult.stderr) ||
      /audio.*not found/i.test(extractAudioResult.stderr);

    if (extractAudioResult.code !== 0 && !noAudioStreamDetected) {
      throw new Error(
        `Audio extraction failed: ${extractAudioResult.stderr.slice(0, 400)}`,
      );
    }

    if (noAudioStreamDetected) {
      appendWarning(
        warnings,
        "Video has no audio track; using OCR-only analysis",
      );
    } else {
      try {
        audioTracks = await prepareVideoAnalysisAudioTracks(
          masterAudioPath,
          analysisAudioPath,
          warnings,
          signal,
        );
        const transcriptionResult = await requestTranscriptionViaLocalApi(
          analysisAudioPath,
          languageHint,
          signal,
        );
        transcription = transcriptionResult.transcription;
        diarizationSegments = transcriptionResult.diarizationSegments;
        transcriptionProvider = transcriptionResult.provider;
        alignmentProvider = transcriptionResult.alignmentProvider;
        transcriptionResult.warnings.forEach((warning) =>
          appendWarning(warnings, warning),
        );
      } catch (error) {
        const message =
          error instanceof Error
            ? error.message
            : "Transcription service unavailable";
        appendWarning(warnings, `Audio transcription unavailable: ${message}`);
      }
    }

    const ocrLanguageHint = normalizeStoryArcV2LanguageHint(
      readString(transcription.language) || languageHint || "auto",
    );
    const ocrResult = await detectOnscreenTextFromVideo(
      stagedVideoPath,
      ocrLanguageHint,
    );
    ocrResult.warnings.forEach((warning) => appendWarning(warnings, warning));

    return {
      transcription,
      detected_text: ocrResult.detectedText,
      warnings,
      diarization_segments: diarizationSegments,
      audio_tracks: audioTracks,
      transcription_provider: transcriptionProvider,
      alignment_provider: alignmentProvider,
    };
  } finally {
    await fs.rm(tempDir, { recursive: true, force: true });
  }
};

const parseSceneCuts = (output: string): number[] => {
  const matches = output.matchAll(/pts_time:([0-9]+(?:\.[0-9]+)?)/g);
  const values = Array.from(matches)
    .map((match) => Number(match[1]))
    .filter((value) => Number.isFinite(value) && value > 0);
  return uniqueNumbers(values).sort((left, right) => left - right);
};

const uniqueNumbers = (values: number[]): number[] => {
  const seen = new Set<number>();
  const ordered: number[] = [];
  for (const value of values) {
    const rounded = Number(value.toFixed(3));
    if (!seen.has(rounded)) {
      seen.add(rounded);
      ordered.push(value);
    }
  }
  return ordered;
};

const buildSceneList = (
  durationSeconds: number,
  cutTimes: number[],
  minSceneLenSeconds: number,
): VideoAnalysisScene[] => {
  const boundedCuts = cutTimes.filter(
    (cut) => cut > 0 && cut < durationSeconds && Number.isFinite(cut),
  );
  const boundaries = uniqueNumbers([0, ...boundedCuts, durationSeconds]).sort(
    (left, right) => left - right,
  );

  const scenes: VideoAnalysisScene[] = [];
  let sceneStart = boundaries[0];
  for (let index = 1; index < boundaries.length; index += 1) {
    const boundary = boundaries[index];
    const segmentDuration = boundary - sceneStart;
    if (segmentDuration < minSceneLenSeconds && index < boundaries.length - 1) {
      continue;
    }

    scenes.push({
      scene_number: scenes.length + 1,
      start_time: Number(sceneStart.toFixed(3)),
      end_time: Number(boundary.toFixed(3)),
      duration: Number(Math.max(0, segmentDuration).toFixed(3)),
    });
    sceneStart = boundary;
  }

  if (scenes.length === 0) {
    scenes.push({
      scene_number: 1,
      start_time: 0,
      end_time: Number(durationSeconds.toFixed(3)),
      duration: Number(durationSeconds.toFixed(3)),
    });
  }

  return scenes;
};

const detectScenesFromVideo = async (
  videoPath: string,
  threshold: number,
  minSceneLenSeconds: number,
  signal?: AbortSignal,
): Promise<VideoAnalysisJobResultSceneDetection> => {
  const tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "storyarc-scenes-"));
  const warnings: string[] = [];

  try {
    const stagedVideoPath = await stageVideoSource(videoPath, tempDir, signal);
    const durationSeconds = await probeVideoDurationSeconds(
      stagedVideoPath,
      signal,
    );
    if (!(durationSeconds > 0)) {
      throw new Error("Unable to probe video duration");
    }

    const thresholdValue = Math.max(0.05, Math.min(0.95, threshold));
    const commandResult = await runBinaryCommand(
      FFMPEG_BINARY,
      [
        "-hide_banner",
        "-loglevel",
        "info",
        "-i",
        stagedVideoPath,
        "-filter:v",
        `select=gt(scene\\,${thresholdValue.toFixed(3)}),showinfo`,
        "-f",
        "null",
        "-",
      ],
      180_000,
      signal,
    );

    if (commandResult.timedOut) {
      throw new Error("Scene detection timed out");
    }

    if (commandResult.code !== 0) {
      appendWarning(
        warnings,
        `ffmpeg scene detection exited with code ${commandResult.code}; using fallback scene split`,
      );
    }

    const cutTimes = parseSceneCuts(
      `${commandResult.stdout}\n${commandResult.stderr}`,
    );
    const scenes = buildSceneList(
      durationSeconds,
      cutTimes,
      minSceneLenSeconds,
    );

    return {
      result: {
        scenes,
        total_scenes: scenes.length,
        threshold: thresholdValue,
        min_scene_len_seconds: minSceneLenSeconds,
        duration_seconds: Number(durationSeconds.toFixed(3)),
      },
      warnings,
    };
  } finally {
    await fs.rm(tempDir, { recursive: true, force: true });
  }
};

const runTranscriptionJob = async (jobId: string) => {
  const job = videoAnalysisJobs.get(jobId);
  if (!job) return;
  const controller =
    videoAnalysisJobControllers.get(jobId) || new AbortController();
  videoAnalysisJobControllers.set(jobId, controller);

  patchVideoAnalysisJob(jobId, {
    status: "processing",
    progress: 10,
    stage: "staging_source",
  });

  try {
    const result = await transcribeVideoSource(
      job.input.videoPath,
      job.input.language,
      controller.signal,
    );
    const latest = videoAnalysisJobs.get(jobId);
    if (!latest || latest.status === "cancelled" || controller.signal.aborted) {
      patchVideoAnalysisJob(jobId, {
        status: "cancelled",
        progress: 100,
        stage: "cancelled",
        error: "Cancelled by user",
      });
      return;
    }
    patchVideoAnalysisJob(jobId, {
      status: "completed",
      progress: 100,
      stage: "completed",
      warnings: result.warnings,
      result,
      error: null,
    });
  } catch (error) {
    if (isAbortLikeError(error) || controller.signal.aborted) {
      patchVideoAnalysisJob(jobId, {
        status: "cancelled",
        progress: 100,
        stage: "cancelled",
        error: "Cancelled by user",
      });
      return;
    }
    const message =
      error instanceof Error ? error.message : "Transcription job failed";
    patchVideoAnalysisJob(jobId, {
      status: "failed",
      progress: 100,
      stage: "failed",
      error: message,
    });
  } finally {
    if (job.input.cleanupSourcePath) {
      await fs
        .rm(job.input.cleanupSourcePath, { force: true })
        .catch(() => undefined);
    }
    videoAnalysisJobControllers.delete(jobId);
  }
};

const runSceneDetectionJob = async (jobId: string) => {
  const job = videoAnalysisJobs.get(jobId);
  if (!job) return;
  const controller =
    videoAnalysisJobControllers.get(jobId) || new AbortController();
  videoAnalysisJobControllers.set(jobId, controller);

  patchVideoAnalysisJob(jobId, { status: "processing", progress: 10 });

  try {
    const result = await detectScenesFromVideo(
      job.input.videoPath,
      job.input.threshold,
      job.input.minSceneLenSeconds,
      controller.signal,
    );
    const latest = videoAnalysisJobs.get(jobId);
    if (!latest || latest.status === "cancelled" || controller.signal.aborted) {
      patchVideoAnalysisJob(jobId, {
        status: "cancelled",
        progress: 100,
        error: "Cancelled by user",
      });
      return;
    }
    patchVideoAnalysisJob(jobId, {
      status: "completed",
      progress: 100,
      warnings: result.warnings,
      result,
      error: null,
    });
  } catch (error) {
    if (isAbortLikeError(error) || controller.signal.aborted) {
      patchVideoAnalysisJob(jobId, {
        status: "cancelled",
        progress: 100,
        error: "Cancelled by user",
      });
      return;
    }
    const message =
      error instanceof Error ? error.message : "Scene detection job failed";
    patchVideoAnalysisJob(jobId, {
      status: "failed",
      progress: 100,
      error: message,
    });
  } finally {
    if (job.input.cleanupSourcePath) {
      await fs
        .rm(job.input.cleanupSourcePath, { force: true })
        .catch(() => undefined);
    }
    videoAnalysisJobControllers.delete(jobId);
  }
};

