const createEmptyStoryArcV2MusicAnalysis = (): StoryArcV2MusicAnalysis => ({
  source: "none",
  durationSeconds: null,
  bpm: null,
  beatIntervalSeconds: null,
  beats: [],
  sections: [],
  energyCurve: [],
  warnings: [],
});

const resolveStoryArcV2CulturalProfile = (
  value: string | null | undefined,
): StoryArcV2CulturalProfile => {
  const normalized = normalizeModelLookupValue(value || "");
  if (!normalized) return "mixed";
  if (normalized.includes("sikh") || normalized.includes("punjabi"))
    return "sikh";
  if (normalized.includes("pakistani") || normalized.includes("nikah"))
    return "pakistani";
  if (
    normalized.includes("norwegian") ||
    normalized === "no" ||
    normalized === "nb" ||
    normalized.includes("norsk")
  ) {
    return "norwegian";
  }
  if (normalized.includes("generic")) return "generic_wedding";
  if (normalized.includes("mixed") || normalized.includes("multi"))
    return "mixed";
  return "mixed";
};

const normalizeStoryArcV2MomentTokenList = (value: unknown): string[] => {
  const rawValues = Array.isArray(value)
    ? value
    : typeof value === "string"
      ? value.split(/[,;\n|]+/)
      : [];
  return Array.from(
    new Set(
      rawValues
        .map((entry) =>
          normalizeModelLookupValue(
            typeof entry === "string" ? entry : readString(entry) || "",
          ),
        )
        .filter((entry) => entry.length >= 2)
        .slice(0, 32),
    ),
  );
};

const resolveStoryArcV2CulturalModules = (
  value: unknown,
): StoryArcV2CulturalProfile[] => {
  const modules = normalizeStoryArcV2MomentTokenList(value)
    .map((entry) => resolveStoryArcV2CulturalProfile(entry))
    .filter((entry) => entry !== "mixed")
    .slice(0, 4);
  return Array.from(new Set(modules));
};

const toStoryArcV2EventPriorityFromRule = (
  rulebook: StoryArcV2CulturalRulebook,
  eventType: StoryArcV2DetectedEventType,
): StoryArcV2EventPriority => {
  const fromRule = rulebook.eventRules.find(
    (rule) => rule.type === eventType,
  )?.priority;
  return fromRule || "C";
};

const toStoryArcV2EventPriorityWeight = (
  priority: StoryArcV2EventPriority,
): number => {
  if (priority === "A") return 0.34;
  if (priority === "B") return 0.22;
  return 0.12;
};

const mergeStoryArcV2CulturalRulebook = (params: {
  profile: StoryArcV2CulturalProfile;
  modules: StoryArcV2CulturalProfile[];
}): StoryArcV2CulturalRulebook => {
  const selectedProfiles: Array<Exclude<StoryArcV2CulturalProfile, "mixed">> = [
    "generic_wedding",
  ];
  if (params.profile !== "mixed") {
    selectedProfiles.push(
      params.profile as Exclude<StoryArcV2CulturalProfile, "mixed">,
    );
  }

  const moduleProfiles =
    params.profile === "mixed" && params.modules.length === 0
      ? (["sikh", "pakistani", "norwegian"] as StoryArcV2CulturalProfile[])
      : params.modules;
  moduleProfiles.forEach((moduleProfile) => {
    if (moduleProfile === "mixed") return;
    const resolved = moduleProfile as Exclude<
      StoryArcV2CulturalProfile,
      "mixed"
    >;
    if (!selectedProfiles.includes(resolved)) {
      selectedProfiles.push(resolved);
    }
  });

  const eventRuleMap = new Map<
    StoryArcV2DetectedEventType,
    StoryArcV2CulturalEventRule
  >();
  const noCutSet = new Set<StoryArcV2DetectedEventType>();
  const sacredSet = new Set<StoryArcV2DetectedEventType>();
  const minClipLenByEventType: Partial<
    Record<StoryArcV2DetectedEventType, number>
  > = {};
  const mustIncludeDefaults = new Set<string>();
  const mergedPacing: StoryArcV2CulturalRulebook["pacing"] = {
    ceremony: { shotMin: 2.8, shotMax: 11 },
    speeches: { shotMin: 2.2, shotMax: 9 },
    party: { shotMin: 1.2, shotMax: 5.2 },
  };

  selectedProfiles.forEach((profileKey) => {
    const profileRulebook = STORY_ARC_V2_CULTURAL_RULEBOOKS[profileKey];
    profileRulebook.eventRules.forEach((rule) => {
      const existing = eventRuleMap.get(rule.type);
      if (!existing) {
        eventRuleMap.set(rule.type, {
          ...rule,
          keywords: [...rule.keywords],
        });
      } else {
        const existingPriorityScore =
          STORY_ARC_V2_EVENT_PRIORITY_SCORE[existing.priority];
        const incomingPriorityScore =
          STORY_ARC_V2_EVENT_PRIORITY_SCORE[rule.priority];
        existing.priority =
          incomingPriorityScore > existingPriorityScore
            ? rule.priority
            : existing.priority;
        existing.keywords = Array.from(
          new Set([...existing.keywords, ...rule.keywords]),
        );
        existing.noCut = Boolean(existing.noCut || rule.noCut);
        existing.sacred = Boolean(existing.sacred || rule.sacred);
        existing.minClipLenSec =
          Math.max(existing.minClipLenSec || 0, rule.minClipLenSec || 0) ||
          undefined;
      }
    });
    profileRulebook.noCutEventTypes.forEach((eventType) =>
      noCutSet.add(eventType),
    );
    profileRulebook.sacredEventTypes.forEach((eventType) =>
      sacredSet.add(eventType),
    );
    Object.entries(profileRulebook.minClipLenByEventType).forEach(
      ([eventType, value]) => {
        const key = eventType as StoryArcV2DetectedEventType;
        const numeric = Number(value);
        if (!Number.isFinite(numeric)) return;
        minClipLenByEventType[key] = Math.max(
          minClipLenByEventType[key] || 0,
          numeric,
        );
      },
    );
    profileRulebook.mustIncludeDefaults.forEach((token) =>
      mustIncludeDefaults.add(token),
    );
    mergedPacing.ceremony.shotMin = Math.max(
      mergedPacing.ceremony.shotMin,
      profileRulebook.pacing.ceremony.shotMin,
    );
    mergedPacing.ceremony.shotMax = Math.max(
      mergedPacing.ceremony.shotMax,
      profileRulebook.pacing.ceremony.shotMax,
    );
    mergedPacing.speeches.shotMin = Math.max(
      mergedPacing.speeches.shotMin,
      profileRulebook.pacing.speeches.shotMin,
    );
    mergedPacing.speeches.shotMax = Math.max(
      mergedPacing.speeches.shotMax,
      profileRulebook.pacing.speeches.shotMax,
    );
    mergedPacing.party.shotMin = Math.max(
      mergedPacing.party.shotMin,
      profileRulebook.pacing.party.shotMin,
    );
    mergedPacing.party.shotMax = Math.max(
      mergedPacing.party.shotMax,
      profileRulebook.pacing.party.shotMax,
    );
  });

  eventRuleMap.forEach((rule) => {
    if (rule.noCut) noCutSet.add(rule.type);
    if (rule.sacred) sacredSet.add(rule.type);
    if (rule.minClipLenSec && Number.isFinite(rule.minClipLenSec)) {
      minClipLenByEventType[rule.type] = Math.max(
        minClipLenByEventType[rule.type] || 0,
        rule.minClipLenSec,
      );
    }
  });

  return {
    profile: params.profile,
    label:
      params.profile === "mixed"
        ? "Mixed Cultural Wedding"
        : STORY_ARC_V2_CULTURAL_RULEBOOKS[
            params.profile as Exclude<StoryArcV2CulturalProfile, "mixed">
          ].label,
    eventRules: Array.from(eventRuleMap.values()),
    noCutEventTypes: Array.from(noCutSet),
    sacredEventTypes: Array.from(sacredSet),
    minClipLenByEventType,
    pacing: mergedPacing,
    mustIncludeDefaults: Array.from(mustIncludeDefaults),
  };
};

const buildStoryArcV2EventKeywordMap = (
  rulebook: StoryArcV2CulturalRulebook,
): Record<StoryArcV2DetectedEventType, string[]> => {
  const keywords = {
    ...STORY_ARC_V2_EVENT_KEYWORDS,
  };
  rulebook.eventRules.forEach((rule) => {
    keywords[rule.type] = Array.from(
      new Set([...(keywords[rule.type] || []), ...rule.keywords]),
    );
  });
  return keywords;
};

const buildStoryArcV2EventImportanceFromRulebook = (
  rulebook: StoryArcV2CulturalRulebook,
  profile: StoryArcV2ProjectProfile,
): Record<StoryArcV2DetectedEventType, number> => {
  const weights = {
    ...STORY_ARC_V2_EVENT_IMPORTANCE,
  };
  rulebook.eventRules.forEach((rule) => {
    weights[rule.type] = Math.max(
      weights[rule.type],
      toStoryArcV2EventPriorityWeight(rule.priority),
    );
  });
  if (profile === "wedding") {
    weights.vow = Math.max(weights.vow, 0.32);
    weights.ring_exchange = Math.max(weights.ring_exchange, 0.3);
    weights.kiss = Math.max(weights.kiss, 0.3);
    weights.first_dance = Math.max(weights.first_dance, 0.25);
  }
  return weights;
};

const resolveStoryArcV2ProjectProfile = (
  value: string | null | undefined,
): StoryArcV2ProjectProfile => {
  const normalized = normalizeModelLookupValue(value || "");
  if (!normalized) return "wedding";
  if (normalized.includes("corporate") || normalized.includes("brand"))
    return "corporate_brand";
  if (normalized.includes("youtube") || normalized.includes("vlog"))
    return "youtube_vlog";
  if (normalized.includes("highlight")) return "highlight_reel";
  if (normalized.includes("dialogue") || normalized.includes("jumpcut"))
    return "dialogue_clean_jumpcut";
  if (
    normalized.includes("aroll") ||
    normalized.includes("interview") ||
    normalized.includes("podcast")
  ) {
    return "a_roll_story_cut";
  }
  if (normalized.includes("wedding") || normalized.includes("bryllup"))
    return "wedding";
  return "wedding";
};

const resolveStoryArcV2EditingMode = (
  value: string | null | undefined,
  profile: StoryArcV2ProjectProfile,
): StoryArcV2EditingMode => {
  const normalized = normalizeModelLookupValue(value || "");
  if (normalized.includes("fullauto") || normalized.includes("full_auto"))
    return "full_auto";
  if (normalized.includes("guided")) return "guided_story";
  if (
    normalized.includes("dialogueclean") ||
    normalized.includes("dialogue_clean")
  )
    return "dialogue_clean";
  if (
    normalized.includes("highlightsync") ||
    normalized.includes("music") ||
    normalized.includes("beat")
  ) {
    return "highlight_music_sync";
  }
  if (normalized.includes("copilot") || normalized.includes("co_pilot"))
    return "co_pilot";

  if (profile === "dialogue_clean_jumpcut") return "dialogue_clean";
  if (profile === "highlight_reel" || profile === "wedding")
    return "highlight_music_sync";
  return "co_pilot";
};

const toStoryArcV2BeatHintFromEventType = (
  eventType: StoryArcV2DetectedEventType,
  fallback: StoryArcV2NarrativeBeat,
): StoryArcV2NarrativeBeat => {
  if (eventType === "vow" || eventType === "ring_exchange")
    return "turning_point";
  if (eventType === "kiss" || eventType === "first_dance") return "resolution";
  if (eventType === "emotional_speech" || eventType === "speech_highlight")
    return "conflict";
  if (
    eventType === "applause" ||
    eventType === "laughter" ||
    eventType === "dancing" ||
    eventType === "hug"
  ) {
    return "resolution";
  }
  return fallback;
};

const collectStoryArcV2KeywordHits = (
  normalizedText: string,
  keywords: string[],
): string[] =>
  keywords
    .filter((keyword) =>
      normalizedText.includes(normalizeModelLookupValue(keyword)),
    )
    .slice(0, 6);

const rangesOverlapStoryArcV2 = (
  startA: number,
  endA: number,
  startB: number,
  endB: number,
): boolean => endA > startB && endB > startA;

const medianStoryArcV2Number = (values: number[]): number | null => {
  if (values.length === 0) return null;
  const sorted = [...values].sort((left, right) => left - right);
  const middle = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[middle - 1] + sorted[middle]) / 2;
  }
  return sorted[middle];
};

const parseStoryArcV2WavMono16 = (
  wavBuffer: Buffer,
): { sampleRate: number; samples: Int16Array } | null => {
  if (wavBuffer.length < 44) return null;
  if (
    wavBuffer.toString("ascii", 0, 4) !== "RIFF" ||
    wavBuffer.toString("ascii", 8, 12) !== "WAVE"
  ) {
    return null;
  }

  let offset = 12;
  let channels = 1;
  let sampleRate = 0;
  let bitsPerSample = 0;
  let dataOffset = -1;
  let dataLength = 0;

  while (offset + 8 <= wavBuffer.length) {
    const chunkId = wavBuffer.toString("ascii", offset, offset + 4);
    const chunkSize = wavBuffer.readUInt32LE(offset + 4);
    const chunkStart = offset + 8;
    const nextOffset = chunkStart + chunkSize + (chunkSize % 2);
    if (nextOffset > wavBuffer.length + 1) {
      break;
    }

    if (chunkId === "fmt " && chunkSize >= 16) {
      channels = wavBuffer.readUInt16LE(chunkStart + 2);
      sampleRate = wavBuffer.readUInt32LE(chunkStart + 4);
      bitsPerSample = wavBuffer.readUInt16LE(chunkStart + 14);
    } else if (chunkId === "data") {
      dataOffset = chunkStart;
      dataLength = chunkSize;
      break;
    }

    offset = nextOffset;
  }

  if (
    dataOffset < 0 ||
    sampleRate <= 0 ||
    bitsPerSample !== 16 ||
    dataLength <= 0
  ) {
    return null;
  }
  if (channels <= 0) channels = 1;

  const bytesPerSampleFrame = channels * 2;
  const frameCount = Math.floor(dataLength / bytesPerSampleFrame);
  if (frameCount <= 0) {
    return null;
  }

  const samples = new Int16Array(frameCount);
  for (let index = 0; index < frameCount; index += 1) {
    const frameOffset = dataOffset + index * bytesPerSampleFrame;
    if (channels === 1) {
      samples[index] = wavBuffer.readInt16LE(frameOffset);
      continue;
    }

    let sum = 0;
    for (let channel = 0; channel < channels; channel += 1) {
      sum += wavBuffer.readInt16LE(frameOffset + channel * 2);
    }
    samples[index] = Math.round(sum / channels);
  }

  return { sampleRate, samples };
};

const analyzeStoryArcV2MusicFromVideo = async (
  videoPath: string,
  signal?: AbortSignal,
): Promise<StoryArcV2MusicAnalysis> => {
  const analysis = createEmptyStoryArcV2MusicAnalysis();
  const tempDir = await fs.mkdtemp(
    path.join(os.tmpdir(), "storyarc-v2-music-"),
  );
  const reducedWavPath = path.join(tempDir, "music-analysis.wav");
  try {
    const extractResult = await runBinaryCommand(
      FFMPEG_BINARY,
      [
        "-hide_banner",
        "-loglevel",
        "error",
        "-y",
        "-i",
        videoPath,
        "-vn",
        "-ac",
        "1",
        "-ar",
        "200",
        "-c:a",
        "pcm_s16le",
        reducedWavPath,
      ],
      240_000,
      signal,
    );

    if (extractResult.timedOut) {
      analysis.warnings.push(
        "Music analysis timed out while extracting audio.",
      );
      return analysis;
    }

    const noAudioStreamDetected =
      /does not contain any stream/i.test(extractResult.stderr) ||
      /stream map .*matches no streams/i.test(extractResult.stderr) ||
      /audio.*not found/i.test(extractResult.stderr);
    if (extractResult.code !== 0) {
      analysis.warnings.push(
        noAudioStreamDetected
          ? "Music analysis skipped (video has no audio stream)."
          : `Music analysis extraction failed: ${extractResult.stderr.slice(0, 280)}`,
      );
      return analysis;
    }

    const wavBuffer = await fs.readFile(reducedWavPath);
    const parsed = parseStoryArcV2WavMono16(wavBuffer);
    if (!parsed) {
      analysis.warnings.push(
        "Music analysis could not parse extracted WAV track.",
      );
      return analysis;
    }

    const { sampleRate, samples } = parsed;
    if (samples.length === 0) {
      analysis.warnings.push("Music analysis received empty audio samples.");
      return analysis;
    }

    const windowDurationSeconds = 0.2;
    const windowSize = Math.max(
      1,
      Math.round(sampleRate * windowDurationSeconds),
    );
    const rawEnergy: number[] = [];
    for (let offset = 0; offset < samples.length; offset += windowSize) {
      const end = Math.min(samples.length, offset + windowSize);
      let squared = 0;
      for (let index = offset; index < end; index += 1) {
        const normalized = samples[index] / 32768;
        squared += normalized * normalized;
      }
      const rms = Math.sqrt(squared / Math.max(1, end - offset));
      rawEnergy.push(rms);
    }

    if (rawEnergy.length === 0) {
      analysis.warnings.push("Music analysis energy curve is empty.");
      return analysis;
    }

    const smoothedEnergy = rawEnergy.map((value, index) => {
      const from = Math.max(0, index - 2);
      const to = Math.min(rawEnergy.length - 1, index + 2);
      let total = 0;
      let count = 0;
      for (let cursor = from; cursor <= to; cursor += 1) {
        total += rawEnergy[cursor];
        count += 1;
      }
      return total / Math.max(1, count);
    });

    const avgEnergy =
      smoothedEnergy.reduce((sum, value) => sum + value, 0) /
      smoothedEnergy.length;
    const minPeakGapSeconds = 0.24;
    let lastPeakTime = -100;
    const beats: StoryArcV2MusicBeatPoint[] = [];
    for (let index = 1; index < smoothedEnergy.length - 1; index += 1) {
      const energy = smoothedEnergy[index];
      const prev = smoothedEnergy[index - 1];
      const next = smoothedEnergy[index + 1];
      const time = index * windowDurationSeconds;
      if (energy <= prev || energy < next) continue;
      if (energy < avgEnergy * 1.12) continue;
      if (time - lastPeakTime < minPeakGapSeconds) continue;
      const confidence = clampStoryArcV2Number(
        (energy - avgEnergy) / Math.max(0.0001, avgEnergy),
        0,
        1,
      );
      beats.push({
        time: Number(time.toFixed(3)),
        confidence: Number(confidence.toFixed(3)),
        energy: Number(clampStoryArcV2Number(energy * 3.4, 0, 1).toFixed(3)),
      });
      lastPeakTime = time;
    }

    const beatIntervals = beats
      .slice(1)
      .map((beat, index) => beat.time - beats[index].time)
      .filter((interval) => interval >= 0.28 && interval <= 1.4);
    const medianInterval = medianStoryArcV2Number(beatIntervals);
    const bpm = medianInterval
      ? clampStoryArcV2Number(60 / medianInterval, 50, 190)
      : null;
    const beatIntervalSeconds = bpm ? Number((60 / bpm).toFixed(3)) : null;

    const sectionWindowPoints = Math.max(
      12,
      Math.round(8 / windowDurationSeconds),
    );
    const sectionMeans: number[] = [];
    for (
      let offset = 0;
      offset < smoothedEnergy.length;
      offset += sectionWindowPoints
    ) {
      const section = smoothedEnergy.slice(
        offset,
        offset + sectionWindowPoints,
      );
      const mean =
        section.reduce((sum, value) => sum + value, 0) /
        Math.max(1, section.length);
      sectionMeans.push(mean);
    }
    const sortedMeans = [...sectionMeans].sort((left, right) => left - right);
    const q33 =
      sortedMeans[Math.max(0, Math.floor(sortedMeans.length * 0.33) - 1)] ?? 0;
    const q66 =
      sortedMeans[Math.max(0, Math.floor(sortedMeans.length * 0.66) - 1)] ??
      q33;

    const durationSeconds = Number(
      (samples.length / sampleRate || 0).toFixed(3),
    );
    const sections: StoryArcV2MusicSection[] = sectionMeans.map(
      (mean, index) => {
        const start = Number(
          (index * sectionWindowPoints * windowDurationSeconds).toFixed(3),
        );
        const end = Number(
          Math.min(
            durationSeconds,
            (index + 1) * sectionWindowPoints * windowDurationSeconds,
          ).toFixed(3),
        );
        const energyLevel: StoryArcV2MusicSection["energyLevel"] =
          mean < q33 ? "low" : mean < q66 ? "medium" : "high";
        let label: StoryArcV2MusicSection["label"] = "verse";
        if (index === 0) {
          label = "intro";
        } else if (index === sectionMeans.length - 1) {
          label = "outro";
        } else if (energyLevel === "high") {
          label = "chorus";
        } else if (energyLevel === "medium" && sectionMeans[index - 1] < q33) {
          label = "build";
        } else if (index % 4 === 0) {
          label = "bridge";
        }
        return {
          sectionId: `section-${index + 1}`,
          start,
          end: end > start ? end : Number((start + 0.2).toFixed(3)),
          label,
          energyLevel,
        };
      },
    );

    const maxCurvePoints = 400;
    const curveStep = Math.max(
      1,
      Math.floor(smoothedEnergy.length / maxCurvePoints),
    );
    const energyCurve = smoothedEnergy
      .filter((_value, index) => index % curveStep === 0)
      .slice(0, maxCurvePoints)
      .map((value) =>
        Number(clampStoryArcV2Number(value * 3.2, 0, 1).toFixed(4)),
      );

    return {
      source: "video_audio",
      durationSeconds,
      bpm: bpm ? Number(bpm.toFixed(2)) : null,
      beatIntervalSeconds,
      beats: beats.slice(0, 2400),
      sections: sections.slice(0, 240),
      energyCurve,
      warnings: [],
    };
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Unknown music analysis error";
    analysis.warnings.push(`Music analysis failed: ${message}`);
    return analysis;
  } finally {
    await fs.rm(tempDir, { recursive: true, force: true });
  }
};

const detectStoryArcV2EventsForMedia = (params: {
  mediaId: string;
  profile: StoryArcV2ProjectProfile;
  rulebook: StoryArcV2CulturalRulebook;
  mustIncludeMoments: string[];
  avoidMoments: string[];
  transcription: VideoAnalysisTranscriptionResult;
  semanticProfiles: StoryArcV2SemanticProfile[];
  detectedText: string[];
}): StoryArcV2DetectedEvent[] => {
  const {
    mediaId,
    profile,
    rulebook,
    mustIncludeMoments,
    avoidMoments,
    transcription,
    semanticProfiles,
    detectedText,
  } = params;
  const events: StoryArcV2DetectedEvent[] = [];
  const eventKeywordMap = buildStoryArcV2EventKeywordMap(rulebook);
  const normalizedMustInclude = mustIncludeMoments
    .map((entry) => normalizeModelLookupValue(entry))
    .filter((entry) => entry.length >= 2);
  const normalizedAvoid = avoidMoments
    .map((entry) => normalizeModelLookupValue(entry))
    .filter((entry) => entry.length >= 2);
  const mediaDuration = Number(
    (
      transcription.duration ??
      semanticProfiles.reduce(
        (max, profileItem) => Math.max(max, profileItem.end),
        0,
      )
    ).toFixed(3),
  );

  const pushEvent = (event: Omit<StoryArcV2DetectedEvent, "eventId">) => {
    const normalizedStart = Number(Math.max(0, event.start).toFixed(3));
    const normalizedEnd = Number(
      Math.max(normalizedStart + 0.2, event.end).toFixed(3),
    );
    events.push({
      eventId: `${mediaId}:${event.type}:${normalizedStart.toFixed(2)}:${events.length + 1}`,
      ...event,
      start: normalizedStart,
      end: normalizedEnd,
      confidence: Number(
        clampStoryArcV2Number(event.confidence, 0, 1).toFixed(3),
      ),
      keywords: event.keywords.slice(0, 8),
      priority: event.priority || "C",
      culturalProfile: event.culturalProfile || rulebook.profile,
    });
  };

  const segmentEventTypes: StoryArcV2DetectedEventType[] = [
    "vow",
    "emotional_speech",
    "speech_highlight",
    "applause",
    "laughter",
    "first_dance",
    "dancing",
  ];

  transcription.segments.forEach((segment, index) => {
    const text = readString(segment.text) || "";
    const normalizedText = normalizeModelLookupValue(text);
    if (!normalizedText) return;
    const segmentStart = Number(readNumber(segment.start) ?? 0);
    const segmentEnd = Number(readNumber(segment.end) ?? segmentStart + 1.4);
    const speaker = readString(segment.speaker) || null;
    const baseBeat = classifyStoryArcV2Beat(
      text,
      index,
      Math.max(1, transcription.segments.length),
    );
    const emotion = inferStoryArcV2Emotion(text);
    const punctuationBoost =
      text.includes("!") || text.includes("?") ? 0.08 : 0;
    const longSentenceBoost =
      text.trim().split(/\s+/).filter(Boolean).length >= 20 ? 0.06 : 0;
    const profileBoost = profile === "wedding" ? 0.06 : 0;
    const mustIncludeHits = normalizedMustInclude.filter((token) =>
      normalizedText.includes(token),
    ).length;
    const avoidHits = normalizedAvoid.filter((token) =>
      normalizedText.includes(token),
    ).length;

    segmentEventTypes.forEach((eventType) => {
      const hits = collectStoryArcV2KeywordHits(
        normalizedText,
        eventKeywordMap[eventType] || [],
      );
      if (hits.length === 0 && eventType !== "speech_highlight") return;

      const priority = toStoryArcV2EventPriorityFromRule(rulebook, eventType);
      let confidence =
        0.45 +
        hits.length * 0.14 +
        punctuationBoost +
        profileBoost +
        toStoryArcV2EventPriorityWeight(priority) * 0.18 +
        mustIncludeHits * 0.08 -
        avoidHits * 0.12;
      if (eventType === "emotional_speech") {
        confidence += emotion.score * 0.25;
      }
      if (eventType === "speech_highlight") {
        if (
          hits.length === 0 &&
          punctuationBoost === 0 &&
          longSentenceBoost === 0
        ) {
          return;
        }
        confidence += longSentenceBoost;
      }
      pushEvent({
        mediaId,
        type: eventType,
        label: eventType.replaceAll("_", " "),
        start: segmentStart,
        end: segmentEnd,
        confidence,
        speaker,
        source: "transcript",
        beatHint: toStoryArcV2BeatHintFromEventType(eventType, baseBeat),
        keywords: hits,
        priority,
        culturalProfile: rulebook.profile,
        rationale:
          `Transcript matched ${eventType.replaceAll("_", " ")} cues.` +
          (mustIncludeHits > 0
            ? ` Matched ${mustIncludeHits} must-include intent cues.`
            : "") +
          (avoidHits > 0
            ? ` Contains ${avoidHits} avoid-intent cues (confidence penalty applied).`
            : ""),
      });
    });
  });

  semanticProfiles.forEach((profileItem, index) => {
    const profileEvents: StoryArcV2DetectedEventType[] = [];
    if (profileItem.actions.includes("dance")) profileEvents.push("dancing");
    if (profileItem.actions.includes("ceremony"))
      profileEvents.push("ring_exchange");
    if (
      profileItem.emotion.label === "emotional" &&
      profileItem.emotion.score >= 0.7
    ) {
      profileEvents.push("emotional_speech");
    }

    profileEvents.forEach((eventType) => {
      const beatHint = toStoryArcV2BeatHintFromEventType(
        eventType,
        classifyStoryArcV2Beat(
          eventType,
          index,
          Math.max(1, semanticProfiles.length),
        ),
      );
      const priority = toStoryArcV2EventPriorityFromRule(rulebook, eventType);
      pushEvent({
        mediaId,
        type: eventType,
        label: eventType.replaceAll("_", " "),
        start: profileItem.start,
        end: profileItem.end,
        confidence:
          0.52 +
          profileItem.emotion.score * 0.24 +
          toStoryArcV2EventPriorityWeight(priority) * 0.2,
        speaker: profileItem.people[0] || null,
        source: "semantic",
        beatHint,
        keywords: profileItem.actions,
        priority,
        culturalProfile: rulebook.profile,
        rationale: `Semantic profile indicates ${eventType.replaceAll("_", " ")} action.`,
      });
    });
  });

  const ocrEventOrder: StoryArcV2DetectedEventType[] = [
    "kiss",
    "hug",
    "ring_exchange",
    "first_dance",
    "dancing",
  ];
  detectedText.forEach((line, index) => {
    const normalizedLine = normalizeModelLookupValue(line);
    if (!normalizedLine) return;
    ocrEventOrder.forEach((eventType) => {
      const hits = collectStoryArcV2KeywordHits(
        normalizedLine,
        eventKeywordMap[eventType] || [],
      );
      if (hits.length === 0) return;
      const anchorRatio =
        mediaDuration > 0 ? index / Math.max(1, detectedText.length) : 0;
      const start = Number((anchorRatio * mediaDuration).toFixed(3));
      const priority = toStoryArcV2EventPriorityFromRule(rulebook, eventType);
      pushEvent({
        mediaId,
        type: eventType,
        label: eventType.replaceAll("_", " "),
        start,
        end: Number((start + 2.2).toFixed(3)),
        confidence:
          0.58 +
          hits.length * 0.1 +
          (profile === "wedding" ? 0.07 : 0) +
          toStoryArcV2EventPriorityWeight(priority) * 0.16,
        speaker: null,
        source: "ocr",
        beatHint: toStoryArcV2BeatHintFromEventType(eventType, "context"),
        keywords: hits,
        priority,
        culturalProfile: rulebook.profile,
        rationale: "OCR detected a wedding visual cue.",
      });
    });
  });

  const sortedEvents = events.sort((left, right) => left.start - right.start);
  const merged: StoryArcV2DetectedEvent[] = [];
  sortedEvents.forEach((event) => {
    const existing = merged.find(
      (candidate) =>
        candidate.mediaId === event.mediaId &&
        candidate.type === event.type &&
        (rangesOverlapStoryArcV2(
          candidate.start,
          candidate.end,
          event.start,
          event.end,
        ) ||
          Math.abs(candidate.start - event.start) <= 1.2),
    );
    if (!existing) {
      merged.push(event);
      return;
    }
    existing.start = Number(Math.min(existing.start, event.start).toFixed(3));
    existing.end = Number(Math.max(existing.end, event.end).toFixed(3));
    existing.confidence = Number(
      Math.max(existing.confidence, event.confidence).toFixed(3),
    );
    existing.keywords = Array.from(
      new Set([...existing.keywords, ...event.keywords]),
    ).slice(0, 8);
    existing.rationale = `${existing.rationale} ${event.rationale}`.trim();
    existing.source =
      existing.source === event.source ? existing.source : "composite";
    existing.priority =
      STORY_ARC_V2_EVENT_PRIORITY_SCORE[event.priority] >
      STORY_ARC_V2_EVENT_PRIORITY_SCORE[existing.priority]
        ? event.priority
        : existing.priority;
  });

  return merged
    .sort((left, right) => right.confidence - left.confidence)
    .slice(0, 260)
    .sort((left, right) => left.start - right.start);
};

const buildStoryArcV2NarrativeAnchorsForMedia = (params: {
  mediaId: string;
  profile: StoryArcV2ProjectProfile;
  rulebook: StoryArcV2CulturalRulebook;
  transcription: VideoAnalysisTranscriptionResult;
  events: StoryArcV2DetectedEvent[];
}): StoryArcV2NarrativeAnchor[] => {
  const { mediaId, profile, rulebook, transcription, events } = params;
  const anchors: StoryArcV2NarrativeAnchor[] = [];
  const maxQuotes = profile === "wedding" ? 18 : 14;
  const eventKeywordMap = buildStoryArcV2EventKeywordMap(rulebook);

  transcription.segments.forEach((segment, index) => {
    const text = (readString(segment.text) || "").trim();
    if (!text) return;
    const start = Number(readNumber(segment.start) ?? 0);
    const end = Number(readNumber(segment.end) ?? start + 1.2);
    const words = text.split(/\s+/).filter(Boolean).length;
    const emotion = inferStoryArcV2Emotion(text);
    const keywordHits =
      collectStoryArcV2KeywordHits(
        normalizeModelLookupValue(text),
        eventKeywordMap.emotional_speech || [],
      ).length +
      collectStoryArcV2KeywordHits(
        normalizeModelLookupValue(text),
        eventKeywordMap.vow || [],
      ).length;
    const score = clampStoryArcV2Number(
      words / 26 +
        emotion.score * 0.35 +
        (text.includes("!") || text.includes("?") ? 0.08 : 0) +
        keywordHits * 0.08 +
        (profile === "wedding" ? 0.04 : 0),
      0,
      1,
    );
    if (score < 0.44) return;
    anchors.push({
      anchorId: `${mediaId}:quote:${index + 1}`,
      mediaId,
      start: Number(start.toFixed(3)),
      end: Number(end.toFixed(3)),
      text,
      score: Number(score.toFixed(3)),
      type: "quote",
      speaker: readString(segment.speaker) || null,
      beatHint: classifyStoryArcV2Beat(
        text,
        index,
        Math.max(1, transcription.segments.length),
      ),
      eventType: null,
    });
  });

  events
    .slice()
    .sort((left, right) => right.confidence - left.confidence)
    .slice(0, profile === "wedding" ? 28 : 16)
    .forEach((event, index) => {
      const priorityBoost =
        event.priority === "A" ? 0.12 : event.priority === "B" ? 0.06 : 0.02;
      anchors.push({
        anchorId: `${mediaId}:event:${index + 1}:${event.type}`,
        mediaId,
        start: event.start,
        end: event.end,
        text: `${event.label}: ${event.rationale}`,
        score: Number(
          clampStoryArcV2Number(
            event.confidence + 0.08 + priorityBoost,
            0,
            1,
          ).toFixed(3),
        ),
        type: "event",
        speaker: event.speaker,
        beatHint: event.beatHint,
        eventType: event.type,
      });
    });

  return anchors
    .sort((left, right) => right.score - left.score)
    .slice(0, maxQuotes + 18)
    .sort((left, right) => left.start - right.start);
};

const mergeStoryArcV2MusicAnalysis = (
  media: StoryArcV2AnalyzedMedia[],
): StoryArcV2MusicAnalysis => {
  const valid = media
    .map((item) => item.musicAnalysis)
    .filter(
      (entry) => entry && entry.source !== "none" && entry.beats.length > 0,
    );
  if (valid.length === 0) {
    return createEmptyStoryArcV2MusicAnalysis();
  }

  const bpmValues = valid
    .map((entry) => entry.bpm)
    .filter(
      (value): value is number =>
        typeof value === "number" && Number.isFinite(value),
    );
  const bpm = medianStoryArcV2Number(bpmValues);
  const beatIntervalSeconds = bpm
    ? Number((60 / bpm).toFixed(3))
    : valid[0].beatIntervalSeconds;

  let offset = 0;
  const beats: StoryArcV2MusicBeatPoint[] = [];
  const sections: StoryArcV2MusicSection[] = [];
  const energyCurve: number[] = [];
  valid.forEach((entry, mediaIndex) => {
    entry.beats.forEach((beat) => {
      beats.push({
        time: Number((beat.time + offset).toFixed(3)),
        confidence: beat.confidence,
        energy: beat.energy,
      });
    });
    entry.sections.forEach((section, sectionIndex) => {
      sections.push({
        ...section,
        sectionId: `m${mediaIndex + 1}-s${sectionIndex + 1}`,
        start: Number((section.start + offset).toFixed(3)),
        end: Number((section.end + offset).toFixed(3)),
      });
    });
    energyCurve.push(...entry.energyCurve);
    offset += entry.durationSeconds || 0;
  });

  return {
    source: "video_audio",
    durationSeconds: Number(offset.toFixed(3)),
    bpm: bpm ? Number(bpm.toFixed(2)) : null,
    beatIntervalSeconds: beatIntervalSeconds || null,
    beats: beats.slice(0, 2800),
    sections: sections.slice(0, 320),
    energyCurve: energyCurve.slice(0, 600),
    warnings: [],
  };
};

const resolveStoryArcV2ProjectKey = (projectId: string | null): string => {
  const key = normalizeModelLookupValue(projectId || "global");
  return key || "global";
};

const normalizeStoryArcV2FeedbackKey = (value: string): string => {
  return normalizeModelLookupValue(value);
};

const tokenizeStoryArcV2FeedbackReason = (reason: string): string[] => {
  const normalized = normalizeModelLookupValue(reason);
  if (!normalized) return [];
  return Array.from(
    new Set(
      normalized.split(/[^a-z0-9æøå]+/u).filter((token) => token.length >= 4),
    ),
  ).slice(0, 12);
};

const createStoryArcV2EmptyFeedbackProfile = (
  projectKey: string,
): StoryArcV2FeedbackProfile => ({
  projectKey,
  clipPenalty: {},
  clipBoost: {},
  speakerPenalty: {},
  speakerBoost: {},
  reasonPenaltyTokens: {},
  updatedAt: new Date().toISOString(),
});

const applyStoryArcV2FeedbackToProfile = (
  profile: StoryArcV2FeedbackProfile,
  event: {
    type: "ban" | "approve";
    clipId?: string | null;
    speaker?: string | null;
    reason?: string | null;
  },
): StoryArcV2FeedbackProfile => {
  const clipKey = event.clipId
    ? normalizeStoryArcV2FeedbackKey(event.clipId)
    : "";
  const speakerKey = event.speaker
    ? normalizeStoryArcV2FeedbackKey(event.speaker)
    : "";

  if (event.type === "ban") {
    if (clipKey) {
      profile.clipPenalty[clipKey] = (profile.clipPenalty[clipKey] || 0) + 1;
    }
    if (speakerKey) {
      profile.speakerPenalty[speakerKey] =
        (profile.speakerPenalty[speakerKey] || 0) + 1;
    }
    tokenizeStoryArcV2FeedbackReason(event.reason || "").forEach((token) => {
      profile.reasonPenaltyTokens[token] =
        (profile.reasonPenaltyTokens[token] || 0) + 1;
    });
  } else {
    if (clipKey) {
      profile.clipBoost[clipKey] = (profile.clipBoost[clipKey] || 0) + 1;
    }
    if (speakerKey) {
      profile.speakerBoost[speakerKey] =
        (profile.speakerBoost[speakerKey] || 0) + 1;
    }
  }

  profile.updatedAt = new Date().toISOString();
  return profile;
};

const ensureStoryArcV2FeedbackProfile = async (
  projectKey: string,
): Promise<StoryArcV2FeedbackProfile> => {
  const cached = storyArcV2FeedbackProfiles.get(projectKey);
  if (cached) return cached;

  const profile = createStoryArcV2EmptyFeedbackProfile(projectKey);
  try {
    if (await hasTable("storyarc_feedback_events")) {
      const result = await pool.query(
        "select event_payload from storyarc_feedback_events where coalesce(event_payload->>'projectKey', 'global') = $1 order by created_at desc limit 500",
        [projectKey],
      );
      result.rows.forEach((row) => {
        const payload = isUnknownRecord(row.event_payload)
          ? (row.event_payload as Record<string, unknown>)
          : {};
        const type = normalizeModelLookupValue(readString(payload.type) || "");
        const clipId = readString(payload.clipId);
        const speaker = readString(payload.speaker);
        const reason = readString(payload.reason);
        if (type === "ban_clip") {
          applyStoryArcV2FeedbackToProfile(profile, {
            type: "ban",
            clipId,
            speaker,
            reason,
          });
        }
        if (type === "approve_node") {
          applyStoryArcV2FeedbackToProfile(profile, {
            type: "approve",
            clipId,
            speaker,
            reason,
          });
        }
      });
    }
  } catch (error) {
    console.warn("story-arc-v2 feedback profile load warning:", error);
  }

  storyArcV2FeedbackProfiles.set(projectKey, profile);
  return profile;
};

const scoreStoryArcV2FeedbackAlignment = (
  profile: StoryArcV2FeedbackProfile,
  clipId: string | null,
  speaker: string | null,
): number => {
  const clipKey = clipId ? normalizeStoryArcV2FeedbackKey(clipId) : "";
  const speakerKey = speaker ? normalizeStoryArcV2FeedbackKey(speaker) : "";
  const clipPenalty = clipKey ? profile.clipPenalty[clipKey] || 0 : 0;
  const clipBoost = clipKey ? profile.clipBoost[clipKey] || 0 : 0;
  const speakerPenalty = speakerKey
    ? profile.speakerPenalty[speakerKey] || 0
    : 0;
  const speakerBoost = speakerKey ? profile.speakerBoost[speakerKey] || 0 : 0;
  return (
    clipBoost * 1.2 +
    speakerBoost * 0.8 -
    clipPenalty * 1.4 -
    speakerPenalty * 1.0
  );
};

const inferStoryArcV2Emotion = (
  text: string,
): { label: string; score: number } => {
  const normalized = normalizeModelLookupValue(text);
  if (!normalized) {
    return { label: "neutral", score: 0.4 };
  }
  if (
    normalized.includes("love") ||
    normalized.includes("elsker") ||
    normalized.includes("takkn") ||
    normalized.includes("happy") ||
    normalized.includes("glad")
  ) {
    return { label: "warm", score: 0.82 };
  }
  if (
    normalized.includes("cry") ||
    normalized.includes("tear") ||
    normalized.includes("savner") ||
    normalized.includes("hard")
  ) {
    return { label: "emotional", score: 0.78 };
  }
  if (
    normalized.includes("joke") ||
    normalized.includes("laugh") ||
    normalized.includes("morsom")
  ) {
    return { label: "joyful", score: 0.74 };
  }
  return { label: "neutral", score: 0.52 };
};

const inferStoryArcV2Actions = (text: string): string[] => {
  const normalized = normalizeModelLookupValue(text);
  const actions: string[] = [];
  if (normalized.includes("dance") || normalized.includes("dans"))
    actions.push("dance");
  if (normalized.includes("toast") || normalized.includes("skål"))
    actions.push("toast");
  if (
    normalized.includes("ring") ||
    normalized.includes("vow") ||
    normalized.includes("løfte")
  ) {
    actions.push("ceremony");
  }
  if (normalized.includes("speech") || normalized.includes("tale"))
    actions.push("speech");
  if (actions.length === 0) actions.push("moment");
  return actions;
};

const buildStoryArcV2SemanticProfiles = (
  mediaId: string,
  scenes: VideoAnalysisScene[],
  transcription: VideoAnalysisTranscriptionResult,
): StoryArcV2SemanticProfile[] => {
  return scenes.map((scene) => {
    const overlappingSegments = transcription.segments.filter(
      (segment) =>
        segment.end > scene.start_time && segment.start < scene.end_time,
    );
    const transcriptText = overlappingSegments
      .map((segment) => segment.text)
      .join(" ")
      .trim();
    const speakers = Array.from(
      new Set(
        overlappingSegments
          .map((segment) => readString(segment.speaker))
          .filter((speaker): speaker is string => Boolean(speaker)),
      ),
    );
    const emotion = inferStoryArcV2Emotion(transcriptText);
    const clipId = `${mediaId}:scene-${scene.scene_number}`;
    const segmentConfidence =
      overlappingSegments.length > 0
        ? overlappingSegments.reduce(
            (sum, segment) => sum + segment.confidence,
            0,
          ) / overlappingSegments.length
        : 0.55;
    return {
      clipId,
      mediaId,
      start: Number(scene.start_time.toFixed(3)),
      end: Number(scene.end_time.toFixed(3)),
      people: speakers,
      actions: inferStoryArcV2Actions(transcriptText),
      locationTags: ["wedding", "event"],
      emotion,
      quality: {
        visual: 0.72,
        audio: Number(
          clampStoryArcV2Number(segmentConfidence, 0.3, 0.95).toFixed(3),
        ),
        stability: 0.68,
      },
      embeddingRef: `r2://models/storyarc-v2/embeddings/${clipId}.json`,
    };
  });
};

const toStoryArcV2VisualActions = (
  actions: string[],
): StoryArcV2VisualAction[] => {
  const normalizedActions = actions.map((entry) =>
    normalizeModelLookupValue(entry),
  );
  const visualActions: StoryArcV2VisualAction[] = [];
  if (
    normalizedActions.some(
      (entry) => entry.includes("speech") || entry.includes("toast"),
    )
  ) {
    visualActions.push("speech");
  }
  if (normalizedActions.some((entry) => entry.includes("dance"))) {
    visualActions.push("dancing");
  }
  if (
    normalizedActions.some(
      (entry) => entry.includes("ring") || entry.includes("ceremony"),
    )
  ) {
    visualActions.push("ring_exchange", "ceremony");
  }
  if (
    normalizedActions.some(
      (entry) => entry.includes("walk") || entry.includes("aisle"),
    )
  ) {
    visualActions.push("walking_aisle");
  }
  if (
    normalizedActions.some(
      (entry) => entry.includes("clap") || entry.includes("applause"),
    )
  ) {
    visualActions.push("clapping");
  }
  if (
    normalizedActions.some(
      (entry) => entry.includes("cheer") || entry.includes("party"),
    )
  ) {
    visualActions.push("cheering");
  }
  if (visualActions.length === 0) {
    visualActions.push("moment");
  }
  return Array.from(new Set(visualActions)).slice(0, 4);
};

const inferStoryArcV2VisualObjects = (params: {
  semanticProfile: StoryArcV2SemanticProfile;
  detectedTextContext: string;
  culturalProfile: StoryArcV2CulturalProfile;
}): string[] => {
  const { semanticProfile, detectedTextContext, culturalProfile } = params;
  const normalizedContext = normalizeModelLookupValue(
    `${detectedTextContext} ${semanticProfile.actions.join(" ")} ${semanticProfile.locationTags.join(" ")}`,
  );
  const objects = new Set<string>();
  if (semanticProfile.people.length > 0) objects.add("person");
  if (semanticProfile.people.length > 1) objects.add("group");
  if (
    normalizedContext.includes("ring") ||
    normalizedContext.includes("ringer")
  )
    objects.add("ring");
  if (
    normalizedContext.includes("bouquet") ||
    normalizedContext.includes("flowers")
  )
    objects.add("bouquet");
  if (
    normalizedContext.includes("microphone") ||
    normalizedContext.includes("mikrofon")
  )
    objects.add("microphone");
  if (
    normalizedContext.includes("altar") ||
    normalizedContext.includes("church")
  )
    objects.add("altar");
  if (normalizedContext.includes("cake")) objects.add("cake");
  if (
    normalizedContext.includes("confetti") ||
    normalizedContext.includes("sparkler")
  )
    objects.add("confetti");
  if (culturalProfile === "sikh" && normalizedContext.includes("gurdwara"))
    objects.add("gurdwara");
  if (culturalProfile === "pakistani" && normalizedContext.includes("nikah"))
    objects.add("nikah-contract");
  return Array.from(objects).slice(0, 8);
};

const inferStoryArcV2VisualLocation = (params: {
  detectedTextContext: string;
  profile: StoryArcV2ProjectProfile;
  culturalProfile: StoryArcV2CulturalProfile;
}): string => {
  const normalized = normalizeModelLookupValue(params.detectedTextContext);
  if (normalized.includes("gurdwara")) return "gurdwara";
  if (normalized.includes("mosque") || normalized.includes("nikah"))
    return "mosque";
  if (normalized.includes("church") || normalized.includes("kirke"))
    return "church";
  if (normalized.includes("dance floor") || normalized.includes("party"))
    return "reception";
  if (params.culturalProfile === "sikh") return "ceremony_hall_sikh";
  if (params.culturalProfile === "pakistani") return "ceremony_hall_pakistani";
  if (params.profile === "wedding") return "wedding_venue";
  return "event_space";
};

const buildStoryArcV2VisualFeaturesForMedia = (params: {
  mediaId: string;
  profile: StoryArcV2ProjectProfile;
  culturalProfile: StoryArcV2CulturalProfile;
  semanticProfiles: StoryArcV2SemanticProfile[];
  detectedText: string[];
}): StoryArcV2VisualFeaturePoint[] => {
  const { mediaId, profile, culturalProfile, semanticProfiles, detectedText } =
    params;
  const textPool = detectedText
    .map((entry) => normalizeModelLookupValue(entry))
    .filter((entry) => entry.length > 0)
    .slice(0, 256);
  const contextWindow = textPool.join(" ");

  return semanticProfiles.map((semanticProfile, index) => {
    const t = Number(
      ((semanticProfile.start + semanticProfile.end) / 2).toFixed(3),
    );
    const shot: StoryArcV2VisualFeaturePoint["scene"]["shot"] =
      semanticProfile.people.length <= 1
        ? semanticProfile.quality.visual >= 0.76
          ? "close"
          : "medium"
        : semanticProfile.people.length >= 4
          ? "wide"
          : "medium";
    const faces: StoryArcV2VisualFeatureFace[] = semanticProfile.people
      .slice(0, 3)
      .map((person, faceIndex) => ({
        id: `${mediaId}:face:${index + 1}:${faceIndex + 1}:${normalizeModelLookupValue(person) || "person"}`,
        bbox:
          faceIndex === 0
            ? [0.26, 0.14, 0.48, 0.64]
            : faceIndex === 1
              ? [0.54, 0.16, 0.78, 0.66]
              : [0.08, 0.2, 0.28, 0.68],
        emotion: semanticProfile.emotion.label,
        confidence: Number(
          clampStoryArcV2Number(
            semanticProfile.emotion.score * 0.88 + 0.08,
            0,
            1,
          ).toFixed(3),
        ),
      }));
    const poses: StoryArcV2VisualFeaturePose[] = faces.map((face) => ({
      id: `${face.id}:pose`,
      keypoints: [],
    }));
    const visualActions = toStoryArcV2VisualActions(semanticProfile.actions);
    const objects = inferStoryArcV2VisualObjects({
      semanticProfile,
      detectedTextContext: contextWindow,
      culturalProfile,
    });
    const location = inferStoryArcV2VisualLocation({
      detectedTextContext: contextWindow,
      profile,
      culturalProfile,
    });
    return {
      featureId: `${mediaId}:vf:${index + 1}`,
      mediaId,
      t,
      objects,
      faces,
      poses,
      actions: visualActions,
      scene: {
        location,
        shot,
        qualityScore: Number(
          clampStoryArcV2Number(
            semanticProfile.quality.visual * 0.55 +
              semanticProfile.quality.stability * 0.45,
            0,
            1,
          ).toFixed(3),
        ),
      },
      confidence: Number(
        clampStoryArcV2Number(
          semanticProfile.quality.visual * 0.52 +
            semanticProfile.quality.stability * 0.24 +
            semanticProfile.emotion.score * 0.24,
          0,
          1,
        ).toFixed(3),
      ),
      source: "semantic_proxy",
    };
  });
};

const buildStoryArcV2EventMarkersForMedia = (params: {
  mediaId: string;
  events: StoryArcV2DetectedEvent[];
  semanticProfiles: StoryArcV2SemanticProfile[];
}): StoryArcV2EventMarker[] => {
  const { mediaId, events, semanticProfiles } = params;
  return events
    .map((event, eventIndex) => {
      const actionHints = STORY_ARC_V2_EVENT_ACTION_HINTS[event.type] || [];
      const localCandidates = semanticProfiles
        .filter((profile) =>
          rangesOverlapStoryArcV2(
            profile.start,
            profile.end,
            event.start - 0.6,
            event.end + 0.6,
          ),
        )
        .map((profile) => {
          const normalizedActions = profile.actions.map((entry) =>
            normalizeModelLookupValue(entry),
          );
          const actionMatches = actionHints.filter((hint) =>
            normalizedActions.some((action) =>
              action.includes(normalizeModelLookupValue(hint)),
            ),
          ).length;
          const speakerMatch =
            event.speaker &&
            profile.people
              .map((entry) => normalizeModelLookupValue(entry))
              .includes(normalizeModelLookupValue(event.speaker))
              ? 1
              : 0;
          const score = clampStoryArcV2Number(
            profile.quality.visual * 0.42 +
              profile.quality.stability * 0.2 +
              profile.quality.audio * 0.16 +
              profile.emotion.score * 0.14 +
              event.confidence * 0.08 +
              actionMatches * 0.08 +
              speakerMatch * 0.08 +
              toStoryArcV2EventPriorityWeight(event.priority) * 0.14,
            0,
            1,
          );
          return {
            clipId: profile.clipId,
            start: Number(profile.start.toFixed(3)),
            end: Number(profile.end.toFixed(3)),
            score: Number(score.toFixed(3)),
            reasons: [
              `Matched event ${event.type}`,
              `Priority ${event.priority}`,
              actionMatches > 0
                ? `Action hint matches ${actionMatches}`
                : "Fallback by proximity/quality",
              speakerMatch > 0
                ? "Speaker visible in candidate clip"
                : "Speaker visibility uncertain",
            ],
          } satisfies StoryArcV2EventTakeCandidate;
        })
        .sort((left, right) => right.score - left.score);

      const bestTakes = localCandidates.slice(0, 3);
      const markerConfidence =
        bestTakes.length > 0
          ? Number(
              clampStoryArcV2Number(
                (event.confidence + bestTakes[0].score) / 2,
                0,
                1,
              ).toFixed(3),
            )
          : event.confidence;

      return {
        markerId: `${mediaId}:event-marker:${eventIndex + 1}:${event.type}`,
        mediaId,
        eventType: event.type,
        label: `${event.priority} ${event.label}`,
        start: event.start,
        end: event.end,
        confidence: markerConfidence,
        reasons: [
          event.rationale,
          `Event priority ${event.priority}`,
          `Cultural profile ${event.culturalProfile}`,
        ],
        bestTakes,
      } satisfies StoryArcV2EventMarker;
    })
    .sort((left, right) => left.start - right.start)
    .slice(0, 320);
};

const buildStoryArcV2PersonIdentities = (
  analysisId: string,
  media: StoryArcV2AnalyzedMedia[],
): StoryArcV2PersonIdentity[] => {
  const aggregate = new Map<
    string,
    {
      segmentCount: number;
      totalDuration: number;
      mediaIds: Set<string>;
      confidenceSum: number;
      confidenceCount: number;
    }
  >();

  media.forEach((mediaItem) => {
    mediaItem.transcription.segments.forEach((segment) => {
      const label = readString(segment.speaker)?.trim();
      if (!label) return;
      const duration = Math.max(
        0,
        (readNumber(segment.end) ?? 0) - (readNumber(segment.start) ?? 0),
      );
      const speakerConfidence =
        readNumber(segment.speaker_confidence) ??
        readNumber(segment.confidence) ??
        0.6;
      const current = aggregate.get(label) || {
        segmentCount: 0,
        totalDuration: 0,
        mediaIds: new Set<string>(),
        confidenceSum: 0,
        confidenceCount: 0,
      };
      current.segmentCount += 1;
      current.totalDuration += duration;
      current.mediaIds.add(mediaItem.mediaId);
      current.confidenceSum += speakerConfidence;
      current.confidenceCount += 1;
      aggregate.set(label, current);
    });
  });

  return Array.from(aggregate.entries())
    .sort((left, right) => right[1].segmentCount - left[1].segmentCount)
    .map(([personLabel, value], index) => {
      const personKey =
        normalizeModelLookupValue(personLabel) || `person-${index + 1}`;
      const confidence =
        value.confidenceCount > 0
          ? value.confidenceSum / value.confidenceCount
          : 0.55;
      return {
        identityId: `${analysisId}:person:${personKey}`,
        analysisId,
        personLabel,
        segmentCount: value.segmentCount,
        totalDuration: Number(value.totalDuration.toFixed(3)),
        mediaIds: Array.from(value.mediaIds),
        confidence: Number(
          clampStoryArcV2Number(confidence, 0.2, 0.99).toFixed(3),
        ),
      };
    });
};

const classifyStoryArcV2Beat = (
  text: string,
  index: number,
  total: number,
): StoryArcV2NarrativeBeat => {
  const normalized = normalizeModelLookupValue(text);
  const ratio = total > 0 ? index / total : 0;

  if (
    normalized.includes("remember") ||
    normalized.includes("visste") ||
    normalized.includes("first time") ||
    normalized.includes("første gang")
  ) {
    return "hook";
  }
  if (
    normalized.includes("difficult") ||
    normalized.includes("challenge") ||
    normalized.includes("hard") ||
    normalized.includes("kamp")
  ) {
    return "conflict";
  }
  if (
    normalized.includes("then") ||
    normalized.includes("suddenly") ||
    normalized.includes("så") ||
    normalized.includes("plutselig")
  ) {
    return "turning_point";
  }
  if (
    normalized.includes("today") ||
    normalized.includes("forever") ||
    normalized.includes("framtid") ||
    normalized.includes("takk")
  ) {
    return "resolution";
  }

  if (ratio < 0.15) return "hook";
  if (ratio < 0.4) return "context";
  if (ratio < 0.65) return "conflict";
  if (ratio < 0.85) return "turning_point";
  return "resolution";
};

