app.get("/api/story-arc/v2/quality/scorecards", async (req, res) => {
  try {
    const requestedProjectKey = resolveStoryArcV2ProjectKey(
      readString(req.query?.projectId) || null,
    );
    const filterByProject = Boolean(readString(req.query?.projectId));
    const limit = Math.max(
      1,
      Math.min(100, Math.round(readNumber(req.query?.limit) ?? 20)),
    );

    const fromMemory = Array.from(storyArcV2QualityScorecards.values())
      .filter((entry) =>
        filterByProject
          ? resolveStoryArcV2ProjectKey(entry.projectId) === requestedProjectKey
          : true,
      )
      .sort((left, right) => right.generatedAt.localeCompare(left.generatedAt));

    if (
      fromMemory.length < limit &&
      (await hasTable("storyarc_quality_scorecards"))
    ) {
      const dbRows = filterByProject
        ? await pool.query(
            `select scorecard_payload from storyarc_quality_scorecards
             where coalesce(project_id, 'global') = $1
             order by created_at desc
             limit $2`,
            [requestedProjectKey, limit],
          )
        : await pool.query(
            `select scorecard_payload from storyarc_quality_scorecards
             order by created_at desc
             limit $1`,
            [limit],
          );

      dbRows.rows.forEach((row) => {
        if (!isUnknownRecord(row.scorecard_payload)) return;
        const scorecard =
          row.scorecard_payload as unknown as StoryArcV2QualityScorecard;
        if (!scorecard.scorecardId) return;
        storyArcV2QualityScorecards.set(scorecard.scorecardId, scorecard);
      });
    }

    const scorecards = Array.from(storyArcV2QualityScorecards.values())
      .filter((entry) =>
        filterByProject
          ? resolveStoryArcV2ProjectKey(entry.projectId) === requestedProjectKey
          : true,
      )
      .sort((left, right) => right.generatedAt.localeCompare(left.generatedAt))
      .slice(0, limit);

    return res.json({
      success: true,
      total: scorecards.length,
      scorecards,
    });
  } catch (error) {
    const message =
      error instanceof Error
        ? error.message
        : "Failed to list quality scorecards";
    return res.status(500).json({ success: false, error: message });
  }
});

