function normalizeCommunityProfession(rawValue: unknown): string {
  const normalized = String(rawValue || "")
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");

  switch (normalized) {
    case "photo":
    case "photographer":
      return "photographer";
    case "video":
    case "videographer":
      return "videographer";
    case "music":
    case "producer":
    case "musicproducer":
    case "music_producer":
      return "music_producer";
    case "enterprise":
      return "enterprise";
    case "vendor":
      return "vendor";
    case "cross_profession":
    case "all":
      return "cross_profession";
    default:
      return normalized || "photographer";
  }
}

function getCommunityProfessionLabel(profession: string): string {
  switch (normalizeCommunityProfession(profession)) {
    case "videographer":
      return "videografer";
    case "music_producer":
      return "music producers";
    case "enterprise":
      return "enterprise-team";
    case "vendor":
      return "partnere";
    case "cross_profession":
      return "skapere";
    case "photographer":
    default:
      return "fotografer";
  }
}
async function getCommunityTargetGroups(
  profession: string,
): Promise<CommunityGroupRecord[]> {
  const normalizedProfession = normalizeCommunityProfession(profession);
  const groupTypes =
    normalizedProfession === "enterprise"
      ? ["cross_profession"]
      : normalizedProfession === "vendor"
        ? ["cross_profession"]
        : [normalizedProfession, "cross_profession"];

  const result = await pool.query(
    `
      SELECT
        id,
        name,
        slug,
        COALESCE(description, '') AS description,
        COALESCE(icon, 'group') AS icon,
        profession_type,
        COALESCE(is_active, true) AS is_active,
        COALESCE(member_count, 0) AS member_count
      FROM community_groups
      WHERE COALESCE(is_active, true) = true
        AND profession_type = ANY($1::text[])
      ORDER BY
        CASE
          WHEN profession_type = $2 THEN 0
          WHEN profession_type = 'cross_profession' THEN 1
          ELSE 2
        END,
        created_at ASC NULLS LAST,
        name ASC
    `,
    [groupTypes, normalizedProfession],
  );

  return result.rows.map((row: any) => ({
    id: String(row.id),
    name: String(row.name || ""),
    slug: String(row.slug || ""),
    description: String(row.description || ""),
    icon: String(row.icon || "group"),
    profession_type: String(row.profession_type || normalizedProfession),
    is_active: Boolean(row.is_active),
    member_count: Number(row.member_count || 0),
  }));
}

async function recalculateCommunityGroupMemberCount(groupId: string) {
  await pool.query(
    `
      UPDATE community_groups
      SET member_count = (
        SELECT COUNT(*)::int
        FROM user_community_memberships
        WHERE group_id = $1
          AND status = 'active'
          AND left_at IS NULL
      ),
      updated_at = NOW()
      WHERE id = $1
    `,
    [groupId],
  );
}

async function ensureCommunityDefaultChannels(
  group: Pick<CommunityGroupRecord, "id" | "profession_type" | "name">,
) {
  const existing = await pool.query(
    `
      SELECT COUNT(*)::int AS count
      FROM community_channels
      WHERE group_id = $1
        AND COALESCE(is_archived, false) = false
    `,
    [group.id],
  );

  if (Number(existing.rows[0]?.count || 0) > 0) {
    return;
  }

  const audience = getCommunityProfessionLabel(group.profession_type);
  const channels = [
    {
      name: "announcements",
      displayName: "Oppslagstavle",
      description: `Viktige oppdateringer og community-beskjeder for ${audience}.`,
      channelType: "announcement",
      isDefault: true,
      isReadOnly: true,
      position: 0,
    },
    {
      name: "introductions",
      displayName: "Presentasjoner",
      description: "Presenter deg, hvem du jobber med og hva du vil faa ut av community.",
      channelType: "discussion",
      isDefault: true,
      isReadOnly: false,
      position: 1,
    },
    {
      name: "questions-help",
      displayName: "Spoersmaal & hjelp",
      description: "Still konkrete fagspoersmaal og faa raske svar fra andre medlemmer.",
      channelType: "support",
      isDefault: true,
      isReadOnly: false,
      position: 2,
    },
  ];

  for (const channel of channels) {
    await pool.query(
      `
        INSERT INTO community_channels (
          id,
          group_id,
          name,
          display_name,
          description,
          channel_type,
          is_default,
          requires_feature,
          requires_subscription_tier,
          is_read_only,
          is_archived,
          position,
          message_count,
          member_count,
          created_at,
          updated_at
        )
        VALUES (
          $1, $2, $3, $4, $5, $6, $7, NULL, NULL, $8, false, $9, 0, 0, NOW(), NOW()
        )
      `,
      [
        crypto.randomUUID(),
        group.id,
        channel.name,
        channel.displayName,
        channel.description,
        channel.channelType,
        channel.isDefault,
        channel.isReadOnly,
        channel.position,
      ],
    );
  }
}

async function onboardUserToCommunity({
  userId,
  profession,
  email,
}: {
  userId: string;
  profession: string;
  email?: string | null;
}) {
  const normalizedProfession = normalizeCommunityProfession(profession);
  if (!userId || normalizedProfession === "vendor") {
    return {
      success: false,
      skipped: true,
      reason: "User is not eligible for community onboarding",
    };
  }

  const targetGroups = await getCommunityTargetGroups(normalizedProfession);
  if (targetGroups.length === 0) {
    return {
      success: false,
      skipped: true,
      reason: "No active community groups found",
    };
  }

  const memberships: Array<Record<string, unknown>> = [];

  for (const group of targetGroups) {
    await ensureCommunityDefaultChannels(group);

    const membershipResult = await pool.query(
      `
        INSERT INTO user_community_memberships (
          id,
          user_id,
          group_id,
          status,
          joined_at,
          left_at,
          message_count,
          last_active_at,
          onboarding_completed,
          onboarding_completed_at,
          created_at,
          updated_at
        )
        VALUES ($1, $2, $3, 'active', NOW(), NULL, 0, NOW(), false, NULL, NOW(), NOW())
        ON CONFLICT (user_id, group_id)
        DO UPDATE SET
          status = 'active',
          left_at = NULL,
          last_active_at = NOW(),
          updated_at = NOW()
        RETURNING *
      `,
      [crypto.randomUUID(), userId, group.id],
    );

    await recalculateCommunityGroupMemberCount(group.id);
    memberships.push({
      ...membershipResult.rows[0],
      group,
    });
  }

  return {
    success: true,
    userId,
    profession: normalizedProfession,
    email: email || null,
    groups: targetGroups,
    memberships,
  };
}

async function ensureCommunityAccessForApprovedInvite(
  requestRow: Record<string, any> | null | undefined,
  fallbackUserId?: string | null,
) {
  const status = String(requestRow?.status || "").trim().toLowerCase();
  const profession = normalizeCommunityProfession(requestRow?.profession);
  const userId =
    String(
      requestRow?.registered_user_id ||
        requestRow?.user_id ||
        fallbackUserId ||
        "",
    ).trim();

  if (status !== "approved" || !userId || profession === "vendor") {
    return null;
  }

  try {
    return await onboardUserToCommunity({
      userId,
      profession,
      email:
        typeof requestRow?.email === "string" ? String(requestRow.email) : null,
    });
  } catch (error) {
    console.error("Community onboarding after approval failed:", error);
    return null;
  }
}
