const handleCreateGoogleMeet = async (
  req: express.Request,
  res: express.Response,
) => {
  try {
    const preferredUserId =
      readString(req.headers["x-user-id"]) ??
      readString(req.body?.userId) ??
      null;
    if (!preferredUserId) {
      return res.status(400).json({
        error:
          "Du må være logget inn med en koblet Google Workspace-bruker for å starte Google Meet.",
      });
    }
    const meeting = await createGoogleMeetLink(
      pool,
      req.body ?? {},
      preferredUserId,
      { preferredOauthApps: derivePreferredGoogleWorkspaceOauthApps(req) },
    );
    const notebookScope = {
      userId: preferredUserId,
      projectId: readString(req.body?.projectId),
      clientId:
        readString(req.body?.clientId) || readString(req.body?.customerId),
      profession: readString(req.body?.profession),
      projectTitle:
        readString(req.body?.projectName) || readString(req.body?.projectTitle),
      clientName: readString(req.body?.clientName),
      clientEmail: readString(req.body?.clientEmail),
      latestMeetingTitle: readString(req.body?.title),
    };

    let notebookLmStatus = await getNotebookLmWorkspaceStatus(
      pool,
      notebookScope,
    ).catch(() => null);
    const meetingNote = await upsertMeetingNoteDraftForGoogleMeet(
      meeting,
      req.body ?? {},
      preferredUserId,
    ).catch((error) => {
      console.warn(
        "Meeting note draft sync skipped on Google Meet create:",
        error instanceof Error ? error.message : error,
      );
      return null;
    });

    if (notebookLmStatus?.syncEligible) {
      await syncNotebookLmWorkspaceForScope(pool, notebookScope).catch(
        (error) => {
          console.warn(
            "NotebookLM workspace sync skipped on Google Meet create:",
            error instanceof Error ? error.message : error,
          );
        },
      );
      notebookLmStatus = await getNotebookLmWorkspaceStatus(
        pool,
        notebookScope,
      ).catch(() => notebookLmStatus);
    }

    res.json({
      ...meeting,
      meetingNote,
      notebookLmWorkspace: notebookLmStatus?.workspace || null,
      notebookLmStatus,
      meetingNotesContext: {
        projectId: notebookScope.projectId,
        clientId: notebookScope.clientId,
        profession: notebookScope.profession,
        projectTitle: notebookScope.projectTitle,
        clientName: notebookScope.clientName,
        clientEmail: notebookScope.clientEmail,
        suggestedMeetingTitle: readString(req.body?.title) || meeting.title,
        calendarEventId: meeting.calendarEventId || null,
        meetingId: meetingNote?.meetingId || null,
      },
    });
  } catch (error) {
    console.error("Failed to create Google Meet meeting:", error);
    res.status(500).json({
      error:
        error instanceof Error
          ? error.message
          : "Failed to create Google Meet meeting",
    });
  }
};

