const showcaseCompatKey = (...parts: Array<string | null | undefined>) =>
  ["showcase", ...parts.filter((part): part is string => Boolean(part))].join(
    ":",
  );

const showcaseCollectionShowcasesKey = (collectionId: string) =>
  showcaseCompatKey("collections", collectionId, "showcases");
const showcaseGoogleAlbumsKey = (userId: string) =>
  showcaseCompatKey("google-photos", userId, "albums");
const showcaseGoogleAlbumPhotosKey = (albumId: string) =>
  showcaseCompatKey("google-photos", "album", albumId, "photos");
const showcaseBatchUndoKey = (userId: string) =>
  showcaseCompatKey("batch-undo", userId);
function showcaseVideoCommentsKey(videoId: string): string {
  return showcaseCompatKey("video", videoId, "comments");
}
function showcaseVideoSequencesKey(projectId: string): string {
  return showcaseCompatKey("video", projectId, "sequences");
}

const inferShowcaseFileType = (
  profession: string | null,
  rawType: string | null,
  fileUrl: string | null,
) => {
  const normalizedType = (rawType || "").toLowerCase();
  if (
    normalizedType === "photo" ||
    normalizedType === "video" ||
    normalizedType === "audio" ||
    normalizedType === "document" ||
    normalizedType === "design"
  ) {
    return normalizedType;
  }

  const normalizedUrl = (fileUrl || "").toLowerCase();
  if (/\.(mp4|mov|webm|mkv|avi|m4v)(\?|$)/.test(normalizedUrl)) {
    return "video";
  }
  if (/\.(mp3|wav|flac|aac|ogg|m4a)(\?|$)/.test(normalizedUrl)) {
    return "audio";
  }
  if (/\.(pdf|doc|docx|ppt|pptx)(\?|$)/.test(normalizedUrl)) {
    return "document";
  }

  if (profession === "videographer") return "video";
  if (profession === "music_producer") return "audio";
  return "photo";
};

const buildShowcaseCropData = (
  payload: Record<string, unknown>,
  existing: Record<string, unknown> = {},
) => {
  const next = {
    ...existing,
    ...(normalizeJsonObjectField(payload.cropData) || {}),
  };

  if (payload.tags !== undefined) {
    next.tags = readStringArray(payload.tags);
  }
  if (payload.clientName !== undefined) {
    next.clientName = readString(payload.clientName) || "";
  }
  if (payload.subtitle !== undefined) {
    next.subtitle = readString(payload.subtitle) || "";
  }
  if (payload.status !== undefined) {
    next.status = readString(payload.status) || "draft";
  }
  if (payload.clientInfo !== undefined) {
    next.clientInfo = normalizeJsonObjectField(payload.clientInfo) || {};
  }
  if (payload.mediaConfig !== undefined) {
    next.mediaConfig = normalizeJsonObjectField(payload.mediaConfig) || {};
  }
  if (payload.displayConfig !== undefined) {
    next.displayConfig = normalizeJsonObjectField(payload.displayConfig) || {};
  }
  if (payload.displayPreferences !== undefined) {
    next.displayPreferences =
      normalizeJsonObjectField(payload.displayPreferences) || {};
  }
  if (payload.location !== undefined) {
    next.location = readString(payload.location) || "";
  }
  if (payload.copyright !== undefined) {
    next.copyright = readString(payload.copyright) || "";
  }
  if (payload.transformations !== undefined) {
    next.transformations =
      normalizeJsonObjectField(payload.transformations) || {};
  }
  if (payload.googlePhotosData !== undefined) {
    next.googlePhotosData =
      normalizeJsonObjectField(payload.googlePhotosData) || {};
  }
  if (payload.metadata !== undefined) {
    next.metadata = normalizeJsonObjectField(payload.metadata) || {};
  }
  if (payload.duration !== undefined) {
    next.duration = readNumber(payload.duration) ?? payload.duration;
  }
  if (payload.fileSize !== undefined || payload.size !== undefined) {
    next.fileSize =
      readNumber(payload.fileSize) ?? readNumber(payload.size) ?? null;
  }

  return next;
};

const mapShowcaseItemRow = (row: Record<string, unknown>) => {
  const cropData = normalizeJsonObjectField(row.crop_data) || {};
  const mediaConfig = normalizeJsonObjectField(cropData.mediaConfig) || {};
  const primaryMedia =
    normalizeJsonObjectField(mediaConfig.primaryMedia) || {};
  const clientInfo = normalizeJsonObjectField(cropData.clientInfo) || {};
  const transformations =
    normalizeJsonObjectField(cropData.transformations) || {};
  const displayPreferences =
    normalizeJsonObjectField(cropData.displayPreferences) || {};
  const fileUrl =
    readString(row.image_url) ||
    readString(row.media_url) ||
    readString(primaryMedia.url) ||
    readString(cropData.fileUrl) ||
    readString(cropData.baseUrl) ||
    null;
  const thumbnailUrl =
    readString(row.thumbnail_url) ||
    readString(primaryMedia.thumbnailUrl) ||
    readString(cropData.thumbnailUrl) ||
    fileUrl;
  const profession =
    readString(row.profession) || readString(cropData.profession) || "photographer";
  const fileType = inferShowcaseFileType(
    profession,
    readString(row.media_type) || readString(cropData.fileType),
    fileUrl,
  );
  const tags = readStringArray(row.tags).length
    ? readStringArray(row.tags)
    : readStringArray(cropData.tags);
  const rating =
    readNumber(clientInfo.rating) ??
    readNumber(cropData.rating) ??
    readNumber(row.rating) ??
    0;
  const featured =
    readBoolean(row.is_featured) ??
    readBoolean(cropData.isFeatured) ??
    readBoolean(row.is_public) ??
    false;
  const isActive = readBoolean(row.is_active);
  const status =
    readString(cropData.status) ||
    (isActive === false ? "archived" : readBoolean(row.is_public) ? "published" : "draft");
  const viewCount = Number(row.view_count || 0);
  const likeCount = Number(row.like_count || 0);
  const downloadCount = Number(row.download_count || 0);

  return {
    id: String(row.id),
    title: readString(row.title) || "Uten tittel",
    description: readString(row.description) || "",
    subtitle: readString(cropData.subtitle) || "",
    thumbnailUrl: thumbnailUrl || "",
    fileUrl: fileUrl || "",
    imageUrl: fileUrl || "",
    type: fileType,
    fileType,
    mediaType: fileType,
    tags,
    clientName:
      readString(cropData.clientName) || readString(clientInfo.name) || "",
    projectType: readString(cropData.projectType) || profession,
    category: readString(row.category) || "Portfolio",
    createdAt: readOptionalIsoDate(row.created_at) || new Date().toISOString(),
    updatedAt: readOptionalIsoDate(row.updated_at) || new Date().toISOString(),
    featured,
    isFeatured: featured,
    isPublic: readBoolean(row.is_public) ?? true,
    isPublished: readBoolean(row.is_public) ?? true,
    status,
    rating,
    viewCount,
    likeCount,
    downloadCount,
    stats: {
      views: viewCount,
      likes: likeCount,
      downloads: downloadCount,
    },
    brandLogoUrl: readString(cropData.brandLogoUrl) || undefined,
    projectId: readString(row.project_id) || undefined,
    mediaConfig,
    displayConfig: normalizeJsonObjectField(cropData.displayConfig) || {},
    clientInfo,
    cropData: normalizeJsonObjectField(cropData.cropData) || transformations,
    displayPreferences,
    googlePhotosData:
      normalizeJsonObjectField(cropData.googlePhotosData) || undefined,
    duration:
      readNumber(row.duration) ?? readNumber(cropData.duration) ?? undefined,
    fileSize:
      readNumber(row.file_size) ??
      readNumber(cropData.fileSize) ??
      undefined,
    size:
      readNumber(row.file_size) ??
      readNumber(cropData.fileSize) ??
      undefined,
  };
};

async function createShowcaseItemRecord(
  payload: Record<string, unknown>,
): Promise<Record<string, unknown>> {
  const columns = await getTableColumns("showcase_items");
  const now = new Date().toISOString();
  const id = readString(payload.id) || crypto.randomUUID();
  const mediaConfig = normalizeJsonObjectField(payload.mediaConfig) || {};
  const primaryMedia =
    normalizeJsonObjectField(mediaConfig.primaryMedia) || {};
  const fileUrl =
    readString(payload.fileUrl) ||
    readString(payload.imageUrl) ||
    readString(primaryMedia.url) ||
    "";
  const thumbnailUrl =
    readString(payload.thumbnailUrl) ||
    readString(primaryMedia.thumbnailUrl) ||
    fileUrl;
  const profession =
    readString(payload.profession) || "photographer";
  const fileType = inferShowcaseFileType(
    profession,
    readString(payload.fileType) || readString(payload.type),
    fileUrl,
  );
  const cropData = buildShowcaseCropData(payload, {
    profession,
    fileType,
  });

  const fieldSpecs = [
    { column: "id", value: id },
    {
      column: "user_id",
      value: readString(payload.userId) || readString(payload.createdBy) || "",
    },
    { column: "profession", value: profession },
    { column: "project_id", value: readString(payload.projectId) || null },
    { column: "title", value: readString(payload.title) || "Uten tittel" },
    { column: "description", value: readString(payload.description) || "" },
    { column: "image_url", value: fileUrl },
    { column: "media_url", value: fileUrl },
    { column: "thumbnail_url", value: thumbnailUrl },
    { column: "media_type", value: fileType },
    {
      column: "category",
      value: readString(payload.category) || "Portfolio",
    },
    {
      column: "tags",
      value: JSON.stringify(readStringArray(payload.tags)),
      json: true,
    },
    { column: "crop_data", value: JSON.stringify(cropData), json: true },
    {
      column: "is_public",
      value: readBoolean(payload.isPublic) ?? true,
    },
    {
      column: "is_featured",
      value:
        readBoolean(payload.isFeatured) ??
        readBoolean(payload.featured) ??
        false,
    },
    {
      column: "is_active",
      value: readString(payload.status) !== "archived",
    },
    {
      column: "sort_order",
      value: readNumber(payload.sortOrder) ?? 0,
    },
    { column: "created_at", value: now, timestamp: true },
    { column: "updated_at", value: now, timestamp: true },
  ].filter((spec) => columns.has(spec.column));

  const placeholders: string[] = [];
  const values: unknown[] = [];

  for (const spec of fieldSpecs) {
    values.push(spec.value);
    if (spec.json) {
      placeholders.push(`$${values.length}::jsonb`);
    } else if (spec.timestamp) {
      placeholders.push(`$${values.length}::timestamp`);
    } else {
      placeholders.push(`$${values.length}`);
    }
  }

  const result = await pool.query(
    `INSERT INTO showcase_items (${fieldSpecs.map((spec) => spec.column).join(", ")})
     VALUES (${placeholders.join(", ")})
     RETURNING *`,
    values,
  );

  return result.rows[0] as Record<string, unknown>;
}

async function updateShowcaseItemRecord(
  itemId: string,
  payload: Record<string, unknown>,
): Promise<Record<string, unknown> | null> {
  const existingResult = await pool.query(
    "SELECT * FROM showcase_items WHERE id = $1 LIMIT 1",
    [itemId],
  );

  if (!existingResult.rows.length) {
    return null;
  }

  const existingRow = existingResult.rows[0] as Record<string, unknown>;
  const columns = await getTableColumns("showcase_items");
  const currentCropData = normalizeJsonObjectField(existingRow.crop_data) || {};
  const nextCropData = buildShowcaseCropData(payload, currentCropData);
  const now = new Date().toISOString();

  const mediaConfig =
    normalizeJsonObjectField(payload.mediaConfig) ||
    normalizeJsonObjectField(nextCropData.mediaConfig) ||
    {};
  const primaryMedia =
    normalizeJsonObjectField(mediaConfig.primaryMedia) || {};
  const fileUrl =
    readString(payload.fileUrl) ||
    readString(payload.imageUrl) ||
    readString(primaryMedia.url) ||
    readString(existingRow.image_url) ||
    readString(existingRow.media_url) ||
    "";
  const thumbnailUrl =
    readString(payload.thumbnailUrl) ||
    readString(primaryMedia.thumbnailUrl) ||
    readString(existingRow.thumbnail_url) ||
    fileUrl;
  const profession =
    readString(payload.profession) ||
    readString(existingRow.profession) ||
    "photographer";
  const fileType = inferShowcaseFileType(
    profession,
    readString(payload.fileType) ||
      readString(payload.type) ||
      readString(existingRow.media_type) ||
      readString(nextCropData.fileType),
    fileUrl,
  );

  nextCropData.profession = profession;
  nextCropData.fileType = fileType;

  const fieldSpecs = [
    {
      column: "title",
      value: payload.title !== undefined ? readString(payload.title) || "Uten tittel" : undefined,
    },
    {
      column: "description",
      value:
        payload.description !== undefined
          ? readString(payload.description) || ""
          : undefined,
    },
    {
      column: "image_url",
      value:
        payload.fileUrl !== undefined || payload.imageUrl !== undefined
          ? fileUrl
          : undefined,
    },
    {
      column: "media_url",
      value:
        payload.fileUrl !== undefined || payload.imageUrl !== undefined
          ? fileUrl
          : undefined,
    },
    {
      column: "thumbnail_url",
      value:
        payload.thumbnailUrl !== undefined ||
        payload.fileUrl !== undefined ||
        payload.imageUrl !== undefined
          ? thumbnailUrl
          : undefined,
    },
    {
      column: "media_type",
      value:
        payload.fileType !== undefined || payload.type !== undefined
          ? fileType
          : undefined,
    },
    {
      column: "profession",
      value: payload.profession !== undefined ? profession : undefined,
    },
    {
      column: "project_id",
      value:
        payload.projectId !== undefined
          ? readString(payload.projectId) || null
          : undefined,
    },
    {
      column: "category",
      value:
        payload.category !== undefined
          ? readString(payload.category) || "Portfolio"
          : undefined,
    },
    {
      column: "tags",
      value:
        payload.tags !== undefined
          ? JSON.stringify(readStringArray(payload.tags))
          : undefined,
      json: true,
    },
    {
      column: "crop_data",
      value: JSON.stringify(nextCropData),
      json: true,
    },
    {
      column: "is_public",
      value:
        payload.isPublic !== undefined
          ? readBoolean(payload.isPublic) ?? true
          : undefined,
    },
    {
      column: "is_featured",
      value:
        payload.isFeatured !== undefined || payload.featured !== undefined
          ? readBoolean(payload.isFeatured) ??
            readBoolean(payload.featured) ??
            false
          : undefined,
    },
    {
      column: "is_active",
      value:
        payload.isActive !== undefined || payload.status !== undefined
          ? readBoolean(payload.isActive) ??
            (readString(payload.status) !== "archived")
          : undefined,
    },
    {
      column: "updated_at",
      value: now,
      timestamp: true,
    },
  ].filter(
    (spec) => columns.has(spec.column) && spec.value !== undefined,
  );

  if (!fieldSpecs.length) {
    return existingRow;
  }

  const setClauses: string[] = [];
  const values: unknown[] = [];

  for (const spec of fieldSpecs) {
    values.push(spec.value);
    if (spec.json) {
      setClauses.push(`${spec.column} = $${values.length}::jsonb`);
    } else if (spec.timestamp) {
      setClauses.push(`${spec.column} = $${values.length}::timestamp`);
    } else {
      setClauses.push(`${spec.column} = $${values.length}`);
    }
  }

  values.push(itemId);
  const result = await pool.query(
    `UPDATE showcase_items
        SET ${setClauses.join(", ")}
      WHERE id = $${values.length}
      RETURNING *`,
    values,
  );

  return (result.rows[0] as Record<string, unknown> | undefined) || null;
}

async function getShowcaseCollectionShowcaseIds(
  collectionId: string,
): Promise<string[]> {
  const stored = await compatStoreGet<string[]>(
    showcaseCollectionShowcasesKey(collectionId),
  );
  if (!Array.isArray(stored)) {
    return [];
  }
  return stored.filter((item): item is string => typeof item === "string");
}

async function setShowcaseCollectionShowcaseIds(
  collectionId: string,
  showcaseIds: string[],
) {
  await compatStoreSet(
    showcaseCollectionShowcasesKey(collectionId),
    Array.from(new Set(showcaseIds)),
  );
}

