async function resolveShowcasePricing(
  profession: string,
  userId?: string | null,
) {
  const normalizedProfession =
    profession === "videographer" || profession === "music_producer"
      ? profession
      : "photographer";

  const defaults = SHOWCASE_PRICING_DEFAULTS[normalizedProfession];

  if (!userId) {
    return defaults;
  }

  try {
    const projectRows = await pool.query(
      `SELECT settings
         FROM legacy.projects
        WHERE user_id = $1
          AND profession = $2
        ORDER BY updated_at DESC NULLS LAST, created_at DESC NULLS LAST
        LIMIT 5`,
      [userId, profession],
    );

    for (const row of projectRows.rows as Array<Record<string, unknown>>) {
      const settings = normalizeJsonObjectField(row.settings) || {};
      const pricing =
        normalizeJsonObjectField(settings.pricing) ||
        normalizeJsonObjectField(settings.showcasePricing);
      if (!pricing) {
        continue;
      }

      return {
        perImage:
          readNumber(pricing.perImage) ??
          readNumber(pricing.per_image) ??
          defaults.perImage,
        contractedBase:
          readNumber(pricing.contractedBase) ??
          readNumber(pricing.contracted_images) ??
          defaults.contractedBase,
        packages: Array.isArray(pricing.packages)
          ? pricing.packages.map((entry) => ({
              id: readString((entry as Record<string, unknown>).id) || crypto.randomUUID(),
              name: readString((entry as Record<string, unknown>).name) || undefined,
              description:
                readString((entry as Record<string, unknown>).description) ||
                undefined,
              images: readNumber((entry as Record<string, unknown>).images) ?? undefined,
              minutes: readNumber((entry as Record<string, unknown>).minutes) ?? undefined,
              tracks: readNumber((entry as Record<string, unknown>).tracks) ?? undefined,
              price: readNumber((entry as Record<string, unknown>).price) ?? 0,
              savings:
                readNumber((entry as Record<string, unknown>).savings) ?? undefined,
            }))
          : defaults.packages,
      };
    }
  } catch (error) {
    console.warn("Showcase pricing lookup failed, using defaults:", error);
  }

  return defaults;
}

function mapGooglePhotoRow(row: Record<string, unknown>): ShowcaseGooglePhotoRecord {
  return {
    id: readString(row.media_item_id) || String(row.id),
    filename: readString(row.filename) || "Google Photo",
    baseUrl: readString(row.base_url) || "",
    mimeType: readString(row.mime_type) || "image/jpeg",
    creationTime:
      readOptionalIsoDate(row.creation_time) || new Date().toISOString(),
    productUrl:
      readString(row.base_url) || "https://photos.google.com",
    width:
      readNumber(row.width) !== null ? String(readNumber(row.width)) : undefined,
    height:
      readNumber(row.height) !== null
        ? String(readNumber(row.height))
        : undefined,
  };
}

function fileBufferToDataUrl(file: Express.Multer.File): string {
  return `data:${file.mimetype};base64,${file.buffer.toString("base64")}`;
}

async function persistUploadedShowcaseAsset(params: {
  userId: string;
  fileName: string;
  mimeType: string;
  fileUrl: string;
  size: number;
  metadata?: Record<string, unknown>;
}) {
  if (!(await hasTable("user_files"))) {
    return;
  }

  try {
    const columns = await getTableColumns("user_files");
    const insertColumns = [
      "id",
      "user_id",
      "file_name",
      "file_path",
      "file_type",
      "file_size",
      "mime_type",
      "metadata",
    ].filter((column) => columns.has(column));

    if (columns.has("file_url")) {
      insertColumns.splice(4, 0, "file_url");
    }

    const values = insertColumns.map((column) => {
      switch (column) {
        case "id":
          return crypto.randomUUID();
        case "user_id":
          return params.userId;
        case "file_name":
          return params.fileName;
        case "file_path":
          return `showcase-assets/${params.userId}/${Date.now()}-${params.fileName}`;
        case "file_url":
          return params.fileUrl;
        case "file_type":
          return "showcase_asset";
        case "file_size":
          return String(params.size);
        case "mime_type":
          return params.mimeType;
        case "metadata":
          return JSON.stringify(params.metadata || {});
        default:
          return null;
      }
    });

    const placeholders = insertColumns
      .map((_, index) => `$${index + 1}`)
      .join(", ");
    await pool.query(
      `INSERT INTO user_files (${insertColumns.join(", ")}) VALUES (${placeholders})`,
      values,
    );
  } catch (error) {
    console.warn("Could not persist showcase asset:", error);
  }
}

