// GET /api/proofing/sessions/:sessionId — Get proofing session details
app.get("/api/proofing/sessions/:sessionId", async (req, res) => {
  try {
    const { sessionId } = req.params;
    const sessionResult = await pool
      .query(
        `SELECT *
           FROM client_gallery_sessions
          WHERE id = $1
          LIMIT 1`,
        [sessionId],
      )
      .catch(() => ({ rows: [] as Array<Record<string, unknown>> }));
    const row =
      (sessionResult.rows[0] as Record<string, unknown> | undefined) || null;
    const selectionResult = await pool
      .query(
        `SELECT COUNT(*)::int AS total
           FROM client_selections
          WHERE session_id = $1
            AND is_selected = true`,
        [sessionId],
      )
      .catch(() => ({ rows: [{ total: 0 }] }));

    const deadline =
      readOptionalIsoDate(row?.selection_deadline) ||
      readOptionalIsoDate(row?.expires_at) ||
      new Date(Date.now() + 14 * 86400000).toISOString();
    const deadlineMs = new Date(deadline).getTime();
    const timeRemaining = Number.isFinite(deadlineMs)
      ? Math.max(0, deadlineMs - Date.now())
      : 0;

    res.json({
      id: sessionId,
      status: readString(row?.status) || "active",
      round: readNumber(row?.proofing_round) ?? 1,
      maxSelections: readNumber(row?.max_selections) ?? 50,
      minSelections: readNumber(row?.min_selections) ?? 0,
      currentSelections: Number(selectionResult.rows[0]?.total || 0),
      selectedCount: Number(selectionResult.rows[0]?.total || 0),
      deadline,
      selectionDeadline: deadline,
      timeRemaining,
      requiresPassword: readBoolean(row?.requires_password) ?? false,
      allowComments: readBoolean(row?.allow_comments) ?? true,
      allowDownloads: readBoolean(row?.allow_downloads) ?? false,
    });
  } catch (error) {
    res.status(500).json({ error: "Kunne ikke hente prøvesesjon" });
  }
});

