app.post("/api/crm/generate-response", async (req, res) => {
  try {
    const { prompt, clientContext, profession } = req.body;

    // Generate contextual response templates based on profession and context
    const clientName = clientContext?.name || "valued customer";
    const professionLabel = profession || "creative professional";

    const templates: Record<string, string> = {
      greeting: `Hei ${clientName}! Takk for din henvendelse. Som ${professionLabel} ser jeg frem til å diskutere prosjektet ditt. Kan du fortelle mer om hva du ser for deg?`,
      pricing: `Takk for interessen, ${clientName}! Mine priser varierer basert på prosjektets omfang og kompleksitet. La oss sette opp et uforpliktende møte for å diskutere dine behov og jeg kan gi deg et skreddersydd tilbud.`,
      availability: `Hei ${clientName}! Jeg har god kapasitet fremover. Kan du dele ønsket dato og lokasjon, så sjekker jeg tilgjengeligheten min?`,
      followup: `Hei igjen ${clientName}! Jeg ville bare følge opp samtalen vår. Har du hatt tid til å tenke over tilbudet? Jeg er tilgjengelig for spørsmål.`,
      technical: `Godt spørsmål, ${clientName}! La meg forklare prosessen min og hvordan vi kan tilpasse den til dine behov.`,
    };

    // Try to match the prompt to a template category
    const promptLower = (prompt || "").toLowerCase();
    let response = templates.greeting;

    if (
      promptLower.includes("pris") ||
      promptLower.includes("kost") ||
      promptLower.includes("price")
    ) {
      response = templates.pricing;
    } else if (
      promptLower.includes("ledig") ||
      promptLower.includes("dato") ||
      promptLower.includes("available")
    ) {
      response = templates.availability;
    } else if (
      promptLower.includes("følge") ||
      promptLower.includes("follow")
    ) {
      response = templates.followup;
    } else if (
      promptLower.includes("teknisk") ||
      promptLower.includes("technical") ||
      promptLower.includes("prosess")
    ) {
      response = templates.technical;
    }

    return res.json({ response });
  } catch (error) {
    console.error("CRM generate response error:", error);
    return res.json({
      response: "Beklager, kunne ikke generere svar. Prøv igjen senere.",
    });
  }
});

app.post(
  "/api/academy/media-assets/upload",
  academyMediaUpload.array("files", 20),
  async (req, res) => {
    try {
      if (!(await requireAcademySession(req, res, "instructor"))) {
        return;
      }
      const files = Array.isArray(req.files)
        ? (req.files as Array<{
            originalname: string;
            mimetype: string;
            buffer: Buffer;
            size: number;
          }>)
        : [];
      if (files.length === 0) {
        return res.status(400).json({ error: "No files uploaded" });
      }

      const folderId =
        String(req.body?.folderId || "course-materials").trim() ||
        "course-materials";
      const courseId = String(req.body?.courseId || "").trim() || undefined;
      const lessonId = String(req.body?.lessonId || "").trim() || undefined;
      const tags = normalizeAcademyMediaTags(req.body?.tags, folderId);
      const manifest = await loadAcademyMediaManifest();
      const createdRecords: AcademyStoredMediaAssetRecord[] = [];

      for (const file of files) {
        const assetId = `academy-media-${crypto.randomUUID()}`;
        const mediaType = normalizeAcademyMediaType(
          file.mimetype,
          file.originalname,
        );
        const currentVersion = await persistAcademyMediaVersion({
          assetId,
          version: 1,
          file,
          type: mediaType,
        });
        const nowIso = currentVersion.updatedAt;
        const record: AcademyStoredMediaAssetRecord = {
          id: assetId,
          name:
            String(file.originalname || "").trim() ||
            `academy-media-${assetId}`,
          type: mediaType,
          folderId,
          courseId,
          lessonId,
          tags,
          createdAt: nowIso,
          updatedAt: nowIso,
          currentVersion,
          history: [],
        };
        manifest.assets.unshift(record);
        createdRecords.push(record);
      }

      manifest.updatedAt = new Date().toISOString();
      await persistAcademyMediaManifest(manifest);

      return res.json({
        assets: createdRecords.map((record) =>
          mapAcademyStoredMediaRecordToResponse(record),
        ),
      });
    } catch (error) {
      console.error("[academy-media] upload failed:", error);
      return res.status(500).json({ error: "Failed to upload academy media" });
    }
  },
);

app.post(
  "/api/academy/media-assets/:assetId/replace",
  academyMediaUpload.single("file"),
  async (req, res) => {
    try {
      if (!(await requireAcademySession(req, res, "instructor"))) {
        return;
      }
      const assetId = String(req.params.assetId || "").trim();
      if (!assetId) {
        return res.status(400).json({ error: "Missing asset id" });
      }
      const file = req.file as
        | {
            originalname: string;
            mimetype: string;
            buffer: Buffer;
            size: number;
          }
        | undefined;
      if (!file) {
        return res.status(400).json({ error: "No file uploaded" });
      }

      const manifest = await loadAcademyMediaManifest();
      const recordIndex = manifest.assets.findIndex(
        (entry) => entry.id === assetId,
      );
      const existing = recordIndex >= 0 ? manifest.assets[recordIndex] : null;
      const requestedType = normalizeAcademyMediaType(
        String(req.body?.type || file.mimetype || ""),
        String(file.originalname || ""),
      );
      if (existing && existing.type !== requestedType) {
        return res
          .status(400)
          .json({ error: "Replacement must keep the same media type" });
      }

      const folderId =
        String(
          req.body?.folderId || existing?.folderId || "course-materials",
        ).trim() || "course-materials";
      const courseId =
        String(req.body?.courseId || existing?.courseId || "").trim() ||
        undefined;
      const lessonId =
        String(req.body?.lessonId || existing?.lessonId || "").trim() ||
        undefined;
      const tags = normalizeAcademyMediaTags(req.body?.tags, folderId);
      const requestedCurrentVersion = Number(req.body?.currentVersion || 0);
      const currentVersionSeed = Math.max(
        existing?.currentVersion.version || 0,
        Number.isFinite(requestedCurrentVersion) ? requestedCurrentVersion : 0,
        1,
      );
      const nextVersion = currentVersionSeed + 1;
      const currentVersion = await persistAcademyMediaVersion({
        assetId,
        version: nextVersion,
        file,
        type: existing?.type || requestedType,
      });
      const nowIso = currentVersion.updatedAt;

      const nextRecord: AcademyStoredMediaAssetRecord = {
        id: assetId,
        name:
          String(req.body?.name || "").trim() ||
          String(file.originalname || "").trim() ||
          existing?.name ||
          `academy-media-${assetId}`,
        type: existing?.type || requestedType,
        folderId,
        courseId,
        lessonId,
        tags: tags.length > 0 ? tags : existing?.tags || [folderId],
        createdAt: existing?.createdAt || nowIso,
        updatedAt: nowIso,
        currentVersion,
        history: existing
          ? [
              ...existing.history.filter(
                (entry) => entry.version !== existing.currentVersion.version,
              ),
              existing.currentVersion,
            ]
          : [],
      };

      if (recordIndex >= 0) {
        manifest.assets.splice(recordIndex, 1, nextRecord);
      } else {
        manifest.assets.unshift(nextRecord);
      }
      manifest.updatedAt = new Date().toISOString();
      await persistAcademyMediaManifest(manifest);

      return res.json({
        asset: mapAcademyStoredMediaRecordToResponse(nextRecord),
      });
    } catch (error) {
      console.error("[academy-media] replace failed:", error);
      return res
        .status(500)
        .json({ error: "Failed to replace academy media asset" });
    }
  },
);

app.delete("/api/academy/media-assets/:assetId", async (req, res) => {
  try {
    if (!(await requireAcademySession(req, res, "instructor"))) {
      return;
    }
    const assetId = String(req.params.assetId || "").trim();
    if (!assetId) {
      return res.status(400).json({ error: "Missing asset id" });
    }
    const manifest = await loadAcademyMediaManifest();
    const nextAssets = manifest.assets.filter((entry) => entry.id !== assetId);
    if (nextAssets.length === manifest.assets.length) {
      return res.status(404).json({ error: "Academy media asset not found" });
    }

    manifest.assets = nextAssets;
    manifest.updatedAt = new Date().toISOString();
    await persistAcademyMediaManifest(manifest);

    const assetDir = path.join(ACADEMY_MEDIA_STORAGE_DIR, assetId);
    try {
      await fs.rm(assetDir, { recursive: true, force: true });
    } catch (error) {
      console.warn("[academy-media] failed to remove asset directory:", error);
    }

    return res.json({ success: true, assetId });
  } catch (error) {
    console.error("[academy-media] delete failed:", error);
    return res
      .status(500)
      .json({ error: "Failed to delete academy media asset" });
  }
});

app.get("/api/academy/media-assets/:assetId/file", async (req, res) => {
  try {
    if (!(await requireAcademySession(req, res, "authenticated"))) {
      return;
    }
    const assetId = String(req.params.assetId || "").trim();
    const requestedVersion = Number(req.query.version || 0);
    const manifest = await loadAcademyMediaManifest();
    const record = manifest.assets.find((entry) => entry.id === assetId);
    if (!record) {
      return res.status(404).json({ error: "Academy media asset not found" });
    }
    const versionRecord = resolveAcademyMediaVersion(
      record,
      Number.isFinite(requestedVersion) && requestedVersion > 0
        ? requestedVersion
        : undefined,
    );
    if (!versionRecord) {
      return res.status(404).json({ error: "Academy media version not found" });
    }

    const absolutePath = path.join(
      ACADEMY_MEDIA_STORAGE_DIR,
      versionRecord.relativePath,
    );
    if (!existsSync(absolutePath)) {
      return res
        .status(404)
        .json({ error: "Academy media file missing on disk" });
    }

    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.type(versionRecord.mimeType || "application/octet-stream");
    return res.sendFile(absolutePath);
  } catch (error) {
    console.error("[academy-media] serve file failed:", error);
    return res.status(500).json({ error: "Failed to load academy media file" });
  }
});

app.get("/api/academy/media-assets/:assetId/poster", async (req, res) => {
  try {
    if (!(await requireAcademySession(req, res, "authenticated"))) {
      return;
    }
    const assetId = String(req.params.assetId || "").trim();
    const requestedVersion = Number(req.query.version || 0);
    const manifest = await loadAcademyMediaManifest();
    const record = manifest.assets.find((entry) => entry.id === assetId);
    if (!record) {
      return res.status(404).json({ error: "Academy media asset not found" });
    }
    const versionRecord = resolveAcademyMediaVersion(
      record,
      Number.isFinite(requestedVersion) && requestedVersion > 0
        ? requestedVersion
        : undefined,
    );
    if (!versionRecord?.posterRelativePath) {
      return res
        .status(404)
        .json({ error: "Poster not available for this asset" });
    }

    const absolutePath = path.join(
      ACADEMY_MEDIA_STORAGE_DIR,
      versionRecord.posterRelativePath,
    );
    if (!existsSync(absolutePath)) {
      return res.status(404).json({ error: "Poster file missing on disk" });
    }

    res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
    res.type(versionRecord.posterMimeType || "image/jpeg");
    return res.sendFile(absolutePath);
  } catch (error) {
    console.error("[academy-media] serve poster failed:", error);
    return res
      .status(500)
      .json({ error: "Failed to load academy media poster" });
  }
});

