// Drive batch upload worker: periodic sweep of ``queued`` +
// ``running`` batches. Tick interval set conservatively so one
// unresponsive OAuth refresh can't starve other workers. Skipped
// automatically when the CreatorHub Google OAuth env vars are
// unset (dev environments without Google wiring).
const driveBatchWorker = startDriveBatchWorker(
  pool,
  makePgDriveClientResolver(pool),
);
// ``driveBatchWorker.stop`` is intentionally not wired to a
// shutdown hook — ``.unref()`` inside the worker lets the process
// exit on its own, and ``app.close`` isn't a pattern used elsewhere
// here. Exposed on the module scope for tests that need to reach in.
void driveBatchWorker;

httpServer.listen(PORT, "0.0.0.0", () => {
  console.log(`🚀 Backend server running on port ${PORT} (HTTP + WebSocket)`);
  // Slice 9X.79 — SmartFlyt scheduler-loop (poller every 60s)
  void (async () => {
    try {
      const { startSchedulerLoop } = await import('./workflow-scheduler.js');
      startSchedulerLoop(pool, async (userId: string, workflowId: string) => {
        try {
          const rows = await db
            .select()
            .from(schema.editingWorkflows)
            .where(eq(schema.editingWorkflows.userId, userId));
          const w = rows.find((r: any) => r.id === workflowId || r.workflowId === workflowId);
          if (!w) return null;
          let steps = w.steps;
          if (typeof steps === 'string') {
            try { steps = JSON.parse(steps); } catch { steps = []; }
          }
          return { ...w, steps };
        } catch {
          return null;
        }
      });
      console.log('[workflow-scheduler] loop started');
    } catch (err: any) {
      console.warn('[workflow-scheduler] could not start:', err.message);
    }
  })();
  maybeStartRoleRoomGoogleRedirectBridge();
  maybeStartRoleRoomLinkedInRedirectBridge();
  maybeStartRoleRoomCommercialReminderSweep();
  maybeStartAuditionReminderSweep({ pool });
  maybeStartTeamInviteSweep({ pool });
  const stripeForInvoiceRunner = getRoleRoomStripeClient();
  if (stripeForInvoiceRunner) {
    maybeStartSmsInvoiceSweep({
      pool,
      stripe: stripeForInvoiceRunner,
      resolveCustomer: resolveStripeCustomerForCastingProject,
    });
    maybeStartWhatsAppInvoiceSweep({
      pool,
      stripe: stripeForInvoiceRunner,
      resolveCustomer: resolveStripeCustomerForCastingProject,
    });
    // Pressroom (composer) månedlig faktura-sweep. Kjører første gang
    // ~120s etter boot og deretter hver 24t; idempotent via
    // composer_usage.stripe_invoice_item_id. Stripe-klient instansieres
    // internt i runneren fra STRIPE_SECRET_KEY.
    maybeStartComposerInvoiceSweep(pool);
  }
  // Page Metadata 2.0 — daglig competitor-watchlist-snapshot. Kjører
  // første sweep ~180s etter boot og deretter hver 24t; idempotent via
  // 12-timers skip-vindu på last_fetched_at.
  maybeStartCompetitorSnapshotSweep(pool);
  maybeStartRoleRoomAiAuditPrune();
  maybeStartRoleRoomAgentDailyScan();
  // Scheduled-publish worker: scan role_room_instagram_publish_jobs
  // every 30s for due rows and run them. No-op until a job actually
  // becomes due, so it's safe to always start.
  startInstagramPublishWorker(pool);
  // Cross-platform publisher registry: registrer alle plattform-implementa-
  // sjoner i social-publisher-modulen. Feed Planner / Marketing Plan
  // dispatchPublish() ruter til riktig publisher basert på platform-felt.
  registerInstagramPublisher(pool);
  registerFacebookPagePublisher(pool);
  registerLinkedInPublisher(pool);
  registerYouTubePublisher(pool);
  registerTikTokPublisher(pool);
  // Sentiment-worker for unified inbox: skanner social_events hvert 60s
  // og scorer pending events via Claude Haiku. Disabled hvis
  // ANTHROPIC_API_KEY ikke er satt.
  startSentimentWorker(pool);
  // Proaktiv token-refresh: timely sweep gjennom alle connections for å
  // refresh-e tokens innen 7 dager av expiry. Hindrer at en konto som
  // ikke brukes regelmessig ender opp med expired token. Disabled hvis
  // META_APP_ID/SECRET ikke er satt.
  startTokenRefreshWorker(pool);
  // LinkedIn-insights polling: 1-time sweep mot /v2/socialActions for
  // post-level engagement (likes + comments). LinkedIn har ingen webhooks
  // for member-level posts, så polling er eneste vei.
  startLinkedInInsightsWorker(pool);
  // YouTube-insights polling: samme mønster som LinkedIn. Henter views,
  // likes, comments-counts via youtube.videos.list og kommentar-bodies
  // via youtube.commentThreads.list. Ingen YouTube-webhooks for member-
  // channels, så polling er eneste vei.
  startYouTubeInsightsWorker(pool);
  // One-off probe so the boot log makes ffmpeg presence/absence
  // obvious without hitting /api/health. Dockerfile installs ffmpeg
  // on the Render image, so this should always log "available".
  void ffmpegAvailable().then((ok) => {
    console.log(`🎬 ffmpeg ${ok ? "available — reels will be normalised to 1080×1920 H.264" : "NOT FOUND — reels pass through unchanged"}`);
  });
  if (isStoryArcV2Enabled() && STORY_ARC_V2_STARTUP_WARMUP_ENABLED) {
    void runStoryArcV2StartupWarmup();
  }
});
